window.POEM_DB=window.POEM_DB||{};POEM_DB["ming_007"]={"n":"陈献章","dyn":"明","poems":[{"t":"次韵荅伯饶见拉出钓","f":"七言律诗","c":["好共溪山结晚缘，竹枝深夜响渔椽。","风清月朗沧溟外，鱼跃鸢飞枕几边。","茶灶烟销回野艇，竹竿霜冷钓秋天。","少年孟浪东西走，衰病于今耻复然。"]},{"t":"寄容一之","f":"五言律诗","c":["直以佣为业，何妨睡作魔。","吟诗终日少，饮酒一生多。","坐久头鸣籁，行迟脚有鹅。","林居三十载，一室小维摩。"]},{"t":"至陈冕家","f":"五言律诗","c":["远树晴堪数，孤云暝欲遮。","自怜江海迹，能到友生家。","落日明江色，轻风动麦花。","相看吾鬓白，不必问年华。"]},{"t":"闻林缉熙初归自平湖寄之","f":"五言律诗","c":["短世渊明醉，长愁子美歌。","高情谁复尔，久别公如何。","淡月初出浦，好风来飏蓑。","买田沧海上，耕亦不须多。"]},{"t":"新年 其三","f":"五言律诗","c":["朝雨黄鹂静，春风暗蕊低。","极知来令节，未肯踏深泥。","狼藉桃无语，侵寻草满蹊。","还闻骑马客，踯躅向沙堤。"]},{"t":"答梅绣衣见访","f":"古风","c":["一春烟雨暗荆扉，系马怜君共落晖。","酒盏香风吹月桂，砚池清露滴?醾。","水中郭索嗔皆是，屋上慈乌爱亦非。","天道不移人自异，红尘飞上钓鱼矶。"]},{"t":"吴明府送菊次韵答之","f":"五言律诗","c":["黄菊有名花，渊明无酒官。","酒多人自醉，花好月同看。","老未厌人世，天教共岁寒。","未应携不去，高步蓬莱山。"]},{"t":"冬夜二首 其一","f":"五言古诗","c":["长夜气始凄，木棉被重裘。","端坐思古人，寒灯耿悠悠。","是时病初间，背汗仍未收。","学业坐妨夺，田芜废锄耰。","高堂有老亲，遍身无完紬。","丈夫庇四海，而以俯仰忧。","口腹非所营，水菽吾当求。","明旦理黄犊，进我南冈舟。"]},{"t":"藤蓑五首 其一","f":"五言古诗","c":["一蓑费几藤，南冈砺朝斧。","交加落翠蔓，制作类上古。","吾闻大泽滨，羊裘动世祖。","何如六尺蓑，灭迹芦花渚。","举俗无与同，天随梦中语。","今夜不须归，前溪正风雨。"]},{"t":"藤蓑五首 其四","f":"五言古诗","c":["新蓑藤叶青，旧蓑藤叶白。","新故理则然，胡为浪忻戚。","扁舟西浦口，坐望南山石。","东风吹新蓑，浩荡沧溟黑。","须臾月东上，万里天一碧。","安得同心人，婆娑共今夕。"]},{"t":"漫题二首 其一","f":"五言古诗","c":["日月逝不处，奄忽几华颠。","华颠亦奚为，所希在寡愆。","韦编绝《周易》，锦囊韬虞弦。","饥餐玉台霞，渴饮沧溟渊。","所以慰我情，无非畹与田。","提携众雏上，啼笑高堂前。","此事如不乐，它尚何乐焉。","东园集茅本，西岭烧松烟。","疾书澄心胸，散满天地间。","聊以悦俄顷，焉知身后年。"]},{"t":"和陶 归田园三首 其一","f":"五言古诗","c":["我始惭名羁，长揖归故山。","故山樵采深，焉知世上年。","是名鸟抢榆，非曰龙潜渊。","东篱采霜菊，两渚收菰田。","游目高原外，披怀深树间。","禽鸟鸣我后，鹿豕游我前。","泠泠玉台风，漠漠圣池烟。","閒持一觞酒，欢饮忘华颠。","逍遥复逍遥，白云如我閒。","乘化以归尽，斯道古来然。"]},{"t":"和陶 归田园三首 其二","f":"五言古诗","c":["高人谢名利，良马罢羁鞅。","归耕吾岂羞，贪得而妄想。","今年秋又熟，欢呼负禾往。","商量大作社，连村集少长。","但忧村酒少，不充侬量广。","醉即拍手歌，东西卧林莽。"]},{"t":"和陶 归田园三首 其三","f":"五言律诗","c":["近来织畚徒，城市售者希。","朝从东皋耕，夕望西岩归。","贫妇业纺绩，灯下成岁衣。","但令家温饱，不问我行违。"]},{"t":"和陶 其二 移居","f":"五言古诗","c":["留连脯时酒，吟咏古人诗。","夕阳傍秋菊，采之复采之。","采之欲遗谁，将以赠所思。","所思在何许，千古不同时。","四海倘不逢，吾宁独去兹。","愿言秉孤贞，勿为时所欺。"]},{"t":"和陶 饮酒","f":"五言古诗","c":["木犀冷于菊，更后十日开。","清风吹芳香，芳香袭人怀。","千回咽入腹，五内无一乖。","虽靡鸾凤吟，亦有鹪鹩栖。","昔者东篱饮，百榼醉如泥。","那知此日花，复与此酒谐。","一曲尽一杯，酩酊花间迷。","赤脚步明月，酒尽吾当回。"]},{"t":"和陶 怀古田舍","f":"五言古诗","c":["君子固有忧，不在贱与贫。","农事久不归，道路竟徒勤。","青阳动芳草，白日悲行人。","沮溺去千载，相知恒若新。","出门转穷厄，得已聊一欣。","甘雨濡夕畛，繁花幕春津。","独往亦何乐，耦耕多近邻。","百年鼎鼎流，永从耕凿民。"]},{"t":"秋兴三首 其一","f":"五言律诗","c":["西风振庭木，虚堂夜萧萧。","揽衣起步月，归雁双飘飖。","天地岂予独，知音不可招。","冥心祈有合，怅望空云霄。"]},{"t":"秋兴三首 其二","f":"五言律诗","c":["盛时不得意，衰老徒伤悲。","志士曷为尔，载籍多见之。","翘首面昆崙，白龙有遗池。","振衣一千仞，高咏秋风谁。"]},{"t":"秋兴三首 其三","f":"五言古诗","c":["海上有一士，来往不知年。","或就胥靡饭，或投上方眠。","游处各有徒，孰谓世情然。","饮酒不在醉，弄琴本无弦。","借问子为谁，得非鲁仲连。"]},{"t":"送李刘二生还江右用陶韵 其一","f":"五言古诗","c":["夜闻桂树芳，晨起山鸟喧。","客从远方来，历我阶西偏。","手持诸侯书，徵会在匡山。","我愿结其人，遂往不复还。","滞形宇宙内，俛仰独何言。"]},{"t":"送李刘二生还江右用陶韵 其二","f":"五言古诗","c":["中年见二子，楚楚西江英。","问讯徐苏里，千年有馀情。","开樽对冥月，高歌亦心倾。","胡为别我去，感此秋蛩鸣。","赠处各有言，慨然尽平生。"]},{"t":"赠李世卿六首 其一","f":"五言律诗","c":["采菊复采菊，严霜下庭木。","岂无桃李颜，畏此天地肃。","落落枝上英，未伤餐者独。","持赠楚人归，投之江鱼腹。"]},{"t":"赠李世卿六首 其二","f":"五言律诗","c":["青青墙下竹，冬后色如是。","灿灿月中花，岁寒香不匮。","新知语未足，远别情难置。","独上江门舟，北风日凌厉。"]},{"t":"有怀世卿 其一","f":"五言律诗","c":["仙鹤去不归，黄鹂向人语。","空馆忽相思，云山杳何许。","出门东望海，默默空延伫。","月出潮复来，鸣桡下沧渚。"]},{"t":"有怀世卿 其二","f":"五言律诗","c":["时雨日夕来，郊原蔼新绿。","白云被重崖，下映寒塘曲。","情结竹上言，魂消井边躅。","三年隔潇湘，书至不可读。"]},{"t":"有怀世卿 其三","f":"五言律诗","c":["伏枕庐山下，春怀惨不舒。","哀弦久去耳，风韵今何如。","灼灼花自媚，嘤嘤鸟相娱。","高台夕流盼，古道行人疏。"]},{"t":"有怀世卿 其四","f":"五言律诗","c":["烦嚣谢人境，抱膝山台居。","奈此枝上鸟，交交春雨馀。","少年耳目冗，衰老不能虚。","安得鲁连子，从之泛江湖。"]},{"t":"送刘方伯东山先生","f":"五言律诗","c":["未别情何如，已别情尤邈。","岂无尺素书，远寄天一角。","江门卧烟艇，酒醒蓑衣薄。","明月照古松，清风洒孤鹤。"]},{"t":"蒋韶州书至代简答之","f":"五言古诗","c":["相别何悠悠，梅花十寒整。","音尘中断绝，窅若堕深井。","忽枉尺素书，开读喜不定。","庾岭秋正高，扬旌下松径。","君才足理郡，韶民日延颈。","古来水火喻，子产功在郑。","岁计谅有馀，愿闻下车令。"]},{"t":"秋夕偶成明日乡试揭榜","f":"五言律诗","c":["缺月不满帘，南窗聊隐几。","犹闻户外舂，断续秋风里。","犬子试初毕，老妻浪惊喜。","滔滔中夜心，四海皆名利。"]},{"t":"自伍光宇墓还登蓬莱绝顶","f":"古风","c":["故人坟前浇我酒，白日欲西回马首。","磴危道险不可跻，下马长须扶两肘。","三步一噫五步停，引吭出舌肺肠鸣。","此时平地虑颠踣，昂首十丈梯峥嵘。","以手捉仆肩，以足踏崖颈。","跻攀欲上分寸难，又恐翻身落深阱。","山北鸣鸺鹠，山南叫?辀，豺虎伏莽狐狸游。","天地衮衮令人愁，小童鱼贯上复休。","绝顶始得岩峦幽，开颜一望隘九州。","弱水涓涓扶桑樛，中覆一杯沧溟流。","穹然青者吾罗浮，神仙葛白俱蜉蝣。","湖西先生去十秋，五羊诗客徒淹留。","数公陈迹或可搜，死者已矣吾何忧。","后来诸生继前修，努力莫倦蓬莱游。"]},{"t":"题马默斋壁","f":"七言古诗","c":["屋后青山屏翳合，檐前绿树烟花匝。","主人闭门履不纳，跏趺明月光绕榻。","客来问我笑不答，但闻山莺啼恰恰。","橙橘盈园野芳杂，门外一江深映閤。","四时八风谁管押，烟飞雾走龙腾甲。","拙者孤舟持酒榼，成化十年甲午腊。"]},{"t":"送客","f":"五言律诗","c":["浓绿新春酒，疏红隔水花。","官人坐马醉，江路绕山斜。","桃李成春径，牛羊散暮沙。","林泉无宿客，兴尽且还家。"]},{"t":"悦城","f":"五言律诗","c":["山作旌幢拥，江絣镜面平。","舟航乘晓发，云物入冬晴。","鼓到江心绝，槎冲石角横。","经过悦城曲，无语笑浮生。"]},{"t":"四月 其一","f":"古风","c":["四月阴晴里，山花落渐稀。","雨声寒月桂，日色暖?醾。","病起初持酒，春归尚掩扉。","午风吹蛱蝶，低趁乳禽飞。"]},{"t":"闻方伯彭公上荐剡 其一","f":"五言律诗","c":["当时尊孔孟，用世必诗书。","夫我何为者，先生非过欤。","长歌扶晚醉，短发向秋疏。","坐惜篱前水，垂竿试钓鱼。"]},{"t":"古椰寄周京","f":"五言律诗","c":["西来何处水，千里不平流。","入海鱼龙喜，怀山草木愁。","雨边明落日，石角上孤舟。","寄语周京道，劳生不自由。"]},{"t":"晚步 其一","f":"古风","c":["水国秋先至，江村晚更幽。","泥筌收郭索，山网落?辀。","凉入社门树，阴连渡口舟。","独怜经略地，吾得放歌游。"]},{"t":"秋坐碧玉楼 其一","f":"五言律诗","c":["造次中秋过，商量九日来。","诗将秋景淡，菊共老人开。","时节陶潜醉，江山宋玉哀。","平生沧海意，不受白鸥猜。"]},{"t":"病疥用后山韵写怀 其四","f":"五言律诗","c":["病枕愁更永，笼灯对夜长。","千年无鲍叔，一懒有柴桑。","儿请栽瓜地，妻评作曲方。","花时呼酒伴，酩酊出扶墙。"]},{"t":"秋中寄兴同前感事韵录寄东所兼呈云谷老隐一笑","f":"五言律诗","c":["山人无外事，白首稚儿同。","弄水溪堂背，争棋纸局中。","盆池秋见月，竹院夜呼风。","触事成唐句，狂歌向碧空。"]},{"t":"题新村书斋壁","f":"五言律诗","c":["日色催江渡，潮痕上石梯。","趁墟村妇出，索哺襁儿啼。","树接黄村坞，船移白石溪。","落花谁省记，何必武陵迷。"]},{"t":"再题","f":"五言律诗","c":["茅栋依岩静，柴门斫竹通。","桑榆巷南北，烟火埭西东。","一径渔樵入，孤村井臼同。","邻家得美酒，吹笛月明中。"]},{"t":"南归寄乡旧 其一","f":"五言律诗","c":["家在桃源里，龙溪是假名。","蕉衫溪女窄，木屐市郎轻。","生酒鲟鱼脍，边垆蚬子羹。","行窝堪处处，只少邵先生。"]},{"t":"南归寄乡旧 其四","f":"五言律诗","c":["碧草东西埭，黄鹂远近山。","岩春花气足，檐日鸟声閒。","文字虚堆几，园林不设关。","一条烟际路，朝往暮来还。"]},{"t":"南归寄乡旧 其五","f":"五言律诗","c":["江边逢野叟，叉手问官名。","立雀黄牛近，衔鱼白鹭腥。","西田馀故宅，北崦多新茔。","驻马斜阳外，悽然感废兴。"]},{"t":"南归寄乡旧 其七","f":"五言律诗","c":["自爱愚公谷，谁过野老家。","时依当户竹，閒数上墙花。","鸟立溪槎静，牛争崦路斜。","怀中娇小女，学语解呼爷。"]},{"t":"南归寄乡旧 其二","f":"五言律诗","c":["居士旧茅斋，萧然倚玉台。","独寻寺里去，每到日西回。","鱼跃水萍破，风推岩户开。","小桥残板在，长讶有人来。"]},{"t":"南归寄乡旧 其三","f":"五言律诗","c":["省事除烦恼，端居养静虚。","栽花终恨少，饮酒不留馀。","山径儿吹笛，村田妇把锄。","殷勤谢闾里，胜事莫相疏。"]},{"t":"南归寄乡旧 其六","f":"五言律诗","c":["山童呼犬出，狂走狺诸孙。","乳鸭争嬉水，寒牛不出村。","墟烟浮树杪，田水到桑根。","邻叟忻相遇，笑谈忘日曛。"]},{"t":"社西村 其二","f":"五言律诗","c":["结茅依里社，村以社西名。","客至惟谈稼，年衰不入城。","邻鸡上树宿，水鹤傍人鸣。","向晚寻牛去，前冈笛又轰。"]},{"t":"社西村 其三","f":"五言律诗","c":["君家里社西，我家里社东。","平分社公雨，不隔马牛风。","瓜地妻能种，衣巾俗与同。","云边采芝径，高尽玉台峰。"]},{"t":"社西村 其四","f":"五言律诗","c":["社主对诸阡，居庐散百烟。","共来乡社会，同乐帝尧年。","折花潮没屐，吹笛月随船。","偶寻社西去，又赋社西篇。"]},{"t":"社西村 其五","f":"五言律诗","c":["社西逢酒伴，埭北有花枝。","讵识愚公意，聊同牧竖嬉。","围棋松崦久，度马板桥迟。","袖有葳蕤草，还家不告饥。"]},{"t":"寄马默斋 其二","f":"古风","c":["倒载轻骈驾，徒行谢众扶。","无钱欺老杜，失策问长须。","山雨?醾病，林风枳壳疏。","待君君不至，春尽又何如。"]},{"t":"次韵秋兴感事录寄东所 其一","f":"五言律诗","c":["醉眠山影里，恨不与君同。","松下泉来冷，鸡鸣日过中。","就床梳白发，开户纳清风。","起视沧溟暮，孤鸿没远空。"]},{"t":"春日江村 其一","f":"五言律诗","c":["时候花先觉，阴晴鸟自知。","登山嫌避客，得句乐呼儿。","蔓草披香径，垂杨覆浅漪。","美人期未至，江月几盈亏。"]},{"t":"春日江村 其二","f":"五言律诗","c":["草带篱腰绿，花簪石顶红。","林园开昼景，莺燕语春风。","山霭霏霏合，江流渺渺东。","独来桥畔路，高拄过眉筇。"]},{"t":"春阴偶作寄定山","f":"五言律诗","c":["浩浩川流疾，冥冥岭树阴。","共怜春错莫，更觉老侵寻。","宿雨衰花气，朝阳绝鸟吟。","谁能尽天道，俛仰此怀深。"]},{"t":"次韵寄廷实 其二","f":"五言律诗","c":["无才佣作吏，有酒喜留宾。","老更耽高卧，时还近俗人。","钟鸣山寺远，月出土床亲。","何处期吾子，笙歌玉洞春。"]},{"t":"喜梁文冠至","f":"五言律诗","c":["驻桨梅村夜，风光胜早春。","直知花是路，不觉月随身。","草木皆知旧，江湖多贱贫。","短蓑来往数，等是最閒人。"]},{"t":"中秋拨闷用旧韵 其一","f":"五言律诗","c":["疏星围碧玉，秋气正平分。","共持今夕酒，又减去年人。","白发来千丈，青山忽数坟。","年光付流水，万物信乾坤。"]},{"t":"中秋拨闷用旧韵 其二","f":"五言律诗","c":["晚有悲秋意，秋来此夜分。","可怜清夜酌，尽是白头人。","紫盖终携病，朱陵愿卜坟。","谁能天地外，别去觅乾坤。"]},{"t":"旌节亭瓦雀","f":"五言古诗","c":["瓦雀喜亭栖，丹青意自迷。","雨馀穿丽日，花底啅香泥。","并语声全碎，追飞羽忽低。","悠悠去缯缴，款款恋榱题。","卵育非无地，儿群或引梯。","惯行书案上，渐满井栏西。","不羡雕笼养，真堪画卷携。","由来亲白首，那更避青藜。","狎久如私眤，喧多类滑稽。","行藏非社燕，饮啄溷家鸡。","度岭千回歇，排风几寸跻。","冥鸿于汝辈，沧海一涔蹄。"]},{"t":"西山驿晚望","f":"七言律诗","c":["晚来花雨湿诗囊，独上邮亭望大荒。","南尽海邦诸郡浅，西来天上一江长。","渔歌落日还孤艇，树隔啼莺背短墙。","料理凭高非一事，樽前谁与共平章。"]},{"t":"对酒 其一","f":"七言律诗","c":["竹杪风轻瓦雀哀，葛巾萧散步阶苔。","放怀自对溪花笑，好事谁撑酒舫来。","白发惊看今日老，青春刚到隔年回。","狂心被酒如飞鹤，又逐红云上玉台。"]},{"t":"荼?花开有怀同赏","f":"古风","c":["看花何处发孤吟，墙角荼?又破金。","紫艳照人今日态，香风吹梦隔年心。","多情酒伴来何晚，得意游蜂入每深。","病起南窗坐终日，独怜涓滴未成斟。"]},{"t":"与谢胖","f":"七言律诗","c":["风波来往十年身，旧事凄凉不可陈。","当道岂非钩距手，青山不问打眠人。","酒醒旅馆城南月，梦破茆茨海角春。","何日定携妻子去，水田稼好最娱亲。"]},{"t":"南归途中先寄诸乡友 其二","f":"七言律诗","c":["不分宾主共林塘，脱下朝衫作道装。","酒为老夫开瓮盎，茗和春露滴旗鎗。","津头水满鸳鸯下，墙背风来枳壳香。","何处与君拚坐久，万株花里小藜床。"]},{"t":"晚酌示藏用诸友 其一","f":"七言律诗","c":["何处氤氲到此溪，香林高树望中迷。","瘦藤拄月秋山远，破褐随风晚袖低。","庐阜亦开新洞府，玉台还是古招提。","黄柑白酒谁宾主，不放今朝醉似泥。"]},{"t":"晚酌示藏用诸友 其三","f":"七言律诗","c":["四人把手过龙溪，一路梅花了不迷。","沧海月明三岛近，白龙天迥众山低。","客携卷子抄诗草，儿上松枝挂酒提。","尽日醉眠崖石上，莓苔茵厚不沾泥。"]},{"t":"晚酌示藏用诸友 其六","f":"七言律诗","c":["东溪牵犬过西溪，短屐冲烟步步迷。","秋竹苔深人语静，古坛松冷鹤巢低。","山花折去空盈把，春酒沽来不满提。","笑把长竿弄江月，草间郭索尚蟠泥。"]},{"t":"晚酌示藏用诸友 其九","f":"七言律诗","c":["丹青不写武陵溪，只记桃花也著迷。","芳草独行山路僻，白云相送洞门低。","笑呼竹笠前头拜，交付诗囊右手提。","风月满山关不住，他时须用一丸泥。"]},{"t":"太子少保诚庵朱公归葬郴阳适会宪长陶公遣生员陈谏偕景旸往祭其墓遂并以公意作诗赠之 其一","f":"七言律诗","c":["铭旌前日别金台，故吏门生安在哉。","黄叶孤村荆桂老，青山连骑越香来。","人思旧德闻吹笛，鸟避新阡下啄苔。","欲了平生功德状，到时须打墓碑回。"]},{"t":"太子少保诚庵朱公归葬郴阳适会宪长陶公遣生员陈谏偕景旸往祭其墓遂并以公意作诗赠之 其二","f":"古风","c":["黄金谁问买端溪，羊祜残碑我解题。","一饭可忘公吐握，千秋遗爱广东西。","寒泷急雨飞涛恶，夜峡啼?哭月低。","不为高堂兼卧病，天涯絮酒肯教携。"]},{"t":"六十一自寿 其一","f":"七言律诗","c":["世间甲子是何年，母鬓双皤子亦然。","十数曾孙罗膝下，两三杯酒笑灯前。","寻僧野寺花迷路，吹笛江门月满船。","圣主万年歌不足，黄河清了凤翩跹。"]},{"t":"元旦试笔 其一","f":"七言律诗","c":["六载虚叨供奉恩，白头吾亦两朝臣。","闾阎击壤今弘治，简册编年又戊申。","日色小薰秾李昼，风光欲醉乳莺春。","庐冈此景谁分付，也到江门不属人。"]},{"t":"元旦试笔 其二","f":"七言律诗","c":["天上风云庆会时，庙谟争遣草茆知。","邻墙旋打娱宾酒，稚子齐歌乐岁诗。","老去又逢新岁月，春来更有好花枝。","晚风何处江楼笛，吹到东溟月上时。"]},{"t":"吊崖","f":"七言律诗","c":["天王舟楫浮南海，大将旌旗仆北风。","义重君臣终死节，时来胡虏亦成功。","身为左衽皆刘豫，志复中原有谢公。","人众胜天非一日，西湖云掩鄂王宫。"]},{"t":"饮酒 其二","f":"七言律诗","c":["君莫停杯我为歌，我今忘我是谁何。","避人懒弄船头笛，对影非无月下蓑。","庐阜春云眠华岳，江门秋水钓银河。","竹弓挽住閒人手，渐觉年来射鸭多。"]},{"t":"次韵李子长至白沙","f":"七言律诗","c":["山转黄云信脚行，西风吹袂五铢轻。","胜游自喜多閒日，衰病还堪逐后生。","白发我因何事笑，黄河人见几回清。","看君合伴庐冈睡，不独能诗一技成。"]},{"t":"邀马玄真用前韵 其一","f":"七言律诗","c":["閒眠閒坐或閒行，身老溪云病亦轻。","客至正当秋酿熟，船来莫待晚潮生。","江山偶得三人对，风月还添一榻清。","昨日书来张主事，头颅空讶老无成。"]},{"t":"次庄定山清江杂兴韵","f":"七言律诗","c":["家学华山一觉眠，图书亦在枕头边。","傍花随柳我寻句，剩水残山天赐年。","竹径旁通沽酒市，桃花乱点钓鱼船。","平生我爱孙思邈，自古高人方又圆。"]},{"t":"次韵定山先生种树 其三","f":"七言律诗","c":["花时风日美新晴，北沜南垞迤逦行。","春色酣酣薰我醉，年光衮衮叹人生。","竹林背水题将遍，石笋穿沙坐欲平。","客问定山何所有，满山红紫数声莺。"]},{"t":"春日偶成","f":"七言律诗","c":["蛱蝶飞飞花映窗，流莺恰恰柳垂江。","出墙老竹青千个，泛浦轻鸥白一双。","暖日暄风酣独卧，来牛去马乱相撞。","江山指点非无句，谁致先生酒百缸。"]},{"t":"赠张叔亨侍御","f":"五言绝句","c":["天下元无事，劳劳我有心。","相携沙上语，山月二更深。"]},{"t":"访客舟中","f":"五言绝句","c":["船头酒多少，船尾阁春沙。","恰到溪穷处，山山枳壳花。"]},{"t":"初晴","f":"七言绝句","c":["初晴楼上燕飞飞，楼下歌人白苧衣。","一曲未终花落去，满林啼鸟送春归。"]},{"t":"赠钓伴","f":"七言绝句","c":["短短蒌蒿浅浅湾，夕阳倒影对南山。","大船鼓枻唱歌去，小艇得鱼吹笛还。"]},{"t":"偶成","f":"七言绝句","c":["墙角经春卧短筇，千秋塔骨不如公。","科头坐转茅檐日，閒看蛛丝荡午风。"]},{"t":"歇马大径山","f":"七言绝句","c":["数家烟火隔林塘，一树寒花晚自香。","黄叶冢头聊歇马，鹧鸪声里近斜阳。"]},{"t":"古有所思","f":"七言绝句","c":["采采红芳日欲斜，盈盈珠泪落天涯。","东风忽搅篱前树，恼乱春愁只为花。"]},{"t":"社中 其一","f":"七言绝句","c":["桑林伐鼓酒如川，秋社钱多春社钱。","尽道升平长官好，五风十雨更年年。"]},{"t":"社中 其二","f":"七言绝句","c":["社屋新成燕子来，山丹未落野棠开。","三三两两儿童戏，弄水扳花日几回。"]},{"t":"社中 其三","f":"七言绝句","c":["社酒开颜一百家，春风先动长官衙。","东君也解游人意，红白交开树树花。"]},{"t":"社中 其四","f":"七言绝句","c":["社日年年会饮同，东原西埭鼓鼕鼕。","无人不是桃花面，笑杀河阳树上红。"]},{"t":"秋江唤渡","f":"七言绝句","c":["何处渡头风浪喧，隔波仙境似桃源。","瘦藤倦向人间去，唤得船来便上船。"]},{"t":"桃花 其一","f":"七言绝句","c":["云锁千峰午未开，桃花流水更天台。","刘郎莫记归时路，只许刘郎一度来。"]},{"t":"元夕","f":"七言绝句","c":["村南村北此宵同，好景难消一老翁。","在处恐妨年少乐，踏歌归去月明中。"]},{"t":"喜晴","f":"七言绝句","c":["西林收雨鹁鸠灵，卷被开窗对晓晴。","风日醉花花醉鸟，竹门啼过两三声。"]},{"t":"偕一之世卿诣楚云台偶作呈世卿 其一","f":"七言绝句","c":["小立三人静楚云，水田漠漠向秋分。","千峰笑指来时路，黄鹤楼前月是君。"]},{"t":"次韵柳渡头答乡友 其二","f":"七言绝句","c":["饭罢雕胡坐石矶，白云閒与鹤同飞。","神仙若道吾无分，那得身轻减带围。"]},{"t":"对酒","f":"七言绝句","c":["半开半谢花相催，江水东流不复回。","扶杖江头看花树，不知笑向酒家来。"]},{"t":"杂诗三首 其三","f":"七言绝句","c":["平生交态如兄弟，此日悲歌不忍闻。","欲寄秋风两行字，九原无雁独怜君。"]},{"t":"悼周镐 其五","f":"七言绝句","c":["里巷三年六七坟，老年无泪哭交亲。","数声愿借辽阳鹤，唤醒人间未死人。"]},{"t":"林缉熙县博张廷实进士何孝子子完先后见访既而缉熙往平湖廷实归五羊子完还博罗因赋四绝 其一","f":"七言绝句","c":["春水江门一叶舟，几人来此看垂钩。","浮云一散无踪迹，飞尽桃花江水流。"]},{"t":"宿云卧轩 其一","f":"七言绝句","c":["世间何喜复何悲，风雨萧萧过短篱。","小睡正酣童子问，公今是梦是醒时。"]},{"t":"宿云卧轩 其二","f":"七言绝句","c":["不妨到处与人群，借宿山斋酒半醺。","我得五龙传睡法，枕痕犹带华山云。"]},{"t":"宿云卧轩 其三","f":"七言绝句","c":["了无意绪向诸缘，到处茅椒可借眠。","白日与人同在梦，不应疑我是神仙。"]},{"t":"谒邓家山墓","f":"七言绝句","c":["掷谷莺声向此沉，绕坟春色为谁深。","纸钱灰冷桐花落，已被愁风捲到心。"]},{"t":"即事","f":"七言绝句","c":["照眼春光烂不收，江亭一雨欲成秋。","道人不是閒莺蝶，肯为阴晴一日愁。"]},{"t":"闻东山先生领都宪之命修理黄河以诗寄之","f":"七言绝句","c":["疏凿分更日已多，乾坤无奈一黄河。","天生会有龙门手，人世空传《瓠子歌》。"]},{"t":"得世卿永兴书","f":"七言绝句","c":["山堂见月自钩帘，一榻秋光中酒眠。","何处博舟来岳下，晚摇山影过湘川。"]},{"t":"悼陈冕 其一","f":"七言绝句","c":["不饮亦狂饮亦狂，醒中说梦醉中忘。","乾坤早暮蜉蝣化，不是芙蓉不耐霜。"]},{"t":"新年田家","f":"七言绝句","c":["古田同井今同村，同坐杯盘到子孙。","合是田家爱元日，白头拄杖拜人门。"]},{"t":"春中杂兴 其二","f":"七言绝句","c":["小雨如丝落晚风，东君无计驻残红。","野人不是伤春客，春在野人杯酒中。"]},{"t":"梅花下感事","f":"七言绝句","c":["桃李村村待发蒙，孤芳憔悴不成丛。","天涯一寸肠如结，吹断江城晓角风。"]},{"t":"月夜与何子有饮梅村社赠之 其一","f":"七言绝句","c":["溪北溪南踏月游，梅花村落似罗浮。","东风夜卷残潮去，留得何郎半日舟。"]},{"t":"月夜与何子有饮梅村社赠之 其二","f":"七言绝句","c":["人日今年又共君，他人交态白头新。","开怀一夜梅村酒，时复停杯问故人。"]},{"t":"玉枕山和南安太守张汝弼","f":"七言绝句","c":["一枕秋横碧玉新，金鳌阁上见嶙峋。","使君得此元无用，卖与江门打睡人。"]},{"t":"悼彦昭","f":"七言绝句","c":["泪尽西风草木间，游魂暗逐《薤》歌残。","千秋只有无情月，遍照松楸处处山。"]},{"t":"鸲鹆育雏于贞节堂东壁壁高且危二雏堕地下乃就而哺之悲鸣徬徨如在无人之境予怜之取雏纳之巢纪以是作 其一","f":"七言绝句","c":["将雏无力上榱题，声断残阳翅忽低。","高栋托身君亦误，鹪鹩安稳只卑栖。"]},{"t":"午睡起","f":"七言绝句","c":["道人本自畏炎炎，一榻清风捲昼帘。","无奈华胥留不得，起凭香几读《楞严》。"]},{"t":"和杨龟山此日不再得韵","f":"五言古诗","c":["能饥谋艺稷，冒寒思植桑。","少年负奇气，万丈磨青苍。","梦寐见古人，慨然悲流光。","吾道有宗主，千秋朱紫阳。","说敬不离口，示我入德方。","义利分两途，析之极毫芒。","圣学信匪难，要在用心臧。","善端日培养，庶免物欲戕。","道德乃膏腴，文辞固秕糠。","俯仰天地间，此身何昂藏。","胡能追轶驾，但能漱馀芳。","持此木钻柔，其如磐石刚。","中夜揽衣起，沉吟独徬徨。","圣途万里馀，发短心苦长。","及此岁未暮，驱车适康庄。","行远必自迩，育德贵含章。","迩来十六载，灭迹声利场。","闭门事探讨，蜕俗如驱羊。","隐几一室内，兀兀同坐忘。","那知颠沛中，此志竟莫强。","譬如济巨川，中道夺我航。","顾兹一身小，所系乃纲常。","枢纽在方寸，操舍决存亡。","胡为谩役役，斲丧良可伤。","愿言各努力，大海终回狂。"]},{"t":"答张内翰廷祥书括而成诗呈胡希仁提学","f":"五言古诗","c":["古人弃糟粕，糟粕非真传。","眇哉一勺水，积累成大川。","亦有非积累，源泉自涓涓。","至无有至动，至近至神焉。","发用兹不穷，缄藏极渊泉。","吾能握其机，何必窥陈编。","学患不用心，用心滋牵缠。","本虚形乃实，立本贵自然。","戒慎与恐惧，斯言未云偏。","后儒不省事，差失毫釐间。","寄语了心人，素琴本无弦。"]},{"t":"代简答罗一峰殿元","f":"五言古诗","c":["台城一挥袂，忽忽星周五。","路永消息断，年深别离苦。","思君发为白，始白数茎许。","今晨对书尺，白者不可数。","先生天下士，讵肯顾衡宇。","怅望曹溪约，独与光也语。"]},{"t":"赠张叔亨知县","f":"五言古诗","c":["栖栖白沙舫，影弄寒江月。","夫君沙阳令，胡事顾微劣。","我祖在九冥，愿君为墓碣。","三夜茆檐下，寒灯坐来灭。","感子心意勤，愧我言词拙。","明发江上舟，踟蹰与君别。"]},{"t":"戏赠馆宾","f":"五言律诗","c":["迟迟岁将暮，戚戚怀故里。","馆中饥鼠多，旅食驴儿尾。","垂德于不报，世间宁有此。","行李无一钱，还家对妻子。"]},{"t":"冬夜二首 其二","f":"五言古诗","c":["我从省事来，过失恒十九。","喜怒朝屡迁，言为夕多苟。","平生昩慎独，即事甘掣肘。","孔子万世师，天地共高厚。","颜渊称庶几，好学古未有。","我才虽卤莽，服膺亦云久。","胡然弗自力，万化脱枢纽。","颓颜无复少，此志还遂否。","岁月岂待人，光阴隙中走。","念此不成眠，晨星灿东牖。"]},{"t":"经鳄洲","f":"五言律诗","c":["夕舫淩大波，北风吹我席。","冥冥鳄州烟，宛对君山碧。","来雁知天寒，归人看月色。","超超尘外心，浩矣周八极。"]},{"t":"厓山看大忠祠竖柱阻风七日后发舟用旧韵","f":"五言古诗","c":["青青奇石草，上有牛羊躅。","汹汹厓门水，远带汤瓶绿。","浮云散孤屿，初日明村曲。","言归辄风涛，无乃疑张陆。","迟迟重迟迟，畏此波心木。"]},{"t":"自策示诸生","f":"五言古诗","c":["贤圣久寂寞，六籍无光辉。","元气五百年，一合又一离。","男儿生其间，独往安可辞。","邈哉舜与颜，梦寐或见之。","其人天下法，其言万世师。","顾予独何人，瞻望空尔为。","年驰力不与，抚镜叹以悲。","岂不在一生，一生良迟迟。","今复不鞭策，虚浪死勿疑。","请回白日驾，鲁阳戈正挥。"]},{"t":"湖西八景为罗修撰作 其一 太极丸春","f":"五言律诗","c":["天城列两仪，其中位太极。","不悟名象生，焉知画前易。","伏羲古已亡，图书久晦蚀。","寄语山中人，妙契在端默。"]},{"t":"湖西八景为罗修撰作 其二 翠玄洞天","f":"五言律诗","c":["翠玄在何许，乃在金鳌麓。","石门俯深幽，来者秉明烛。","绣壁谁可缘，丹房我当宿。","呼童烹金鳌，膏此千丈木。"]},{"t":"湖西八景为罗修撰作 其三 一峰来秀","f":"五言律诗","c":["西湖有一峰，天地得撑拄。","旁有龙塘峡，北有浮香坞。","我行昆崙丘，一望一延伫。","归来二三子，抵掌太极语。"]},{"t":"湖西八景为罗修撰作 其四 三峡回清","f":"五言律诗","c":["一峡蟠一龙，群山莽回互。","武夷虽九曲，三峡谁胜负。","澄澄水上月，历历谷中树。","焉得千丈筇，坐弄潺湲处。"]},{"t":"湖西八景为罗修撰作 其五 金鳌霁雪","f":"五言律诗","c":["一鳌海上来，头戴雪花白。","诸鳌起相拒，千秋归不得。","仙人罗一峰，永戏金鳌侧。","借问别离时，西佛生弥勒。"]},{"t":"湖西八景为罗修撰作 其六 玉冕晴云","f":"五言律诗","c":["玉冕臣诸峰，左右罗络之。","云来巾其颠，得雨不复疑。","岂无泽物功，云覆在何时。","怅望百谷春，广济苍生饥。"]},{"t":"湖西八景为罗修撰作 其七 飞舆横翠","f":"五言律诗","c":["我昔游太空，太空云冥冥。","归来控翠虬，力与金鳌争。","巍巍太极尊，挥置东西行。","如何千载下，空儗飞舆名。"]},{"t":"湖西八景为罗修撰作 其八 大流垂玉","f":"五言律诗","c":["大流无此奇，偶置银河倾。","愿回银河流，免与世浊并。","一洗日月光，再洗天地清。","何止天地清，万世无甲兵。"]},{"t":"题冷庵","f":"五言古诗","c":["举世好近热，子独畏之猛。","投身向壑雪，永谢白日影。","玉壶贮清冰，秋露滴金井。","是以冷自胜，于世非绝屏。","假令务绝屏，过与近热等。","我以道眼观，天下方首肯。","寒暑两推移，正中太和境。","寄语庵中人，不热亦不冷。"]},{"t":"扶南访黄岩尹邝载道适来顾白沙两不值赋三侧韵 其一","f":"五言律诗","c":["行舟石门浪，不识扶溪口。","时时闻来往，日入丧水手。","昨暮黄岩马，来嘶白沙柳。","惜哉两不遇，独坐空搔首。"]},{"t":"扶南访黄岩尹邝载道适来顾白沙两不值赋三侧韵 其二","f":"五言律诗","c":["我有一斗酒，愿与子秉烛。","子来复空去，值我不在屋。","稚子呼不至，踉跄走入竹。","明旦归我艇，先后迓以告。"]},{"t":"扶南访黄岩尹邝载道适来顾白沙两不值赋三侧韵 其三","f":"五言律诗","c":["閒居不儗出，偶出负佳客。","问客来何许，来自黄岩谪。","长安接笑语，中道有暌隔。","悠悠百年内，与子异显默。"]},{"t":"感事","f":"五言律诗","c":["君心如逝水，一往不复旋。","谁能万里浪，安坐驾此船。","伤哉一何愚，由我不由天。","仁者固有矜，智士乃自全。"]},{"t":"梦观化书六字壁间曰造物一场变化","f":"五言古诗","c":["孔子曳杖歌，逍遥梦化后。","我梦已逍遥，六字书在牖。","圣愚各有尽，观化一遭走。","问我年几何，春秋四十九。","死生若昼夜，当速何必久。","即死无所怜，乾坤一刍狗。"]},{"t":"贪泉","f":"五言律诗","c":["藜藿可养生，柏棺可送死。","瓦砾是黄金，贪泉亦清泚。","饮水心不易，岂独夷齐尔。","山鬼笑侬家，侬家笑山鬼。"]},{"t":"九日诸友会饮白沙得雁字","f":"五言古诗","c":["黄菊有佳辰，良朋乐呼唤。","争持渊明杯，来接子桑饭。","落叶迎马鞭，斜晖转沙岸。","雨声静秋竹，池影入江雁。","酒酣独高歌，呼儿续我断。","诸君极留恋，十觞亦不算。","虽无孟嘉量，且免落帽乱。","百年能几何，去者已强半。","来会安可期，细把茱萸看。"]},{"t":"赠林汝和通判","f":"五言古诗","c":["在昔黄金台，与子初周旋。","萍逢忽相失，不见垂十年。","昔为礼曹官，今摇庆阳鞭。","常闻太华峰，峻绝峙中天。","雅志在登陟，矫如孤鹄鶱。","适来南海旁，问讯沧洲廛。","语旧未终日，栖栖有所牵。","丈夫重出处，富贵如浮烟。","行则为在田，止则为在渊。","劳劳夫何为，赠子千金言。"]},{"t":"赠马龙如湖西奠一峰先生","f":"五言古诗","c":["晨兴坐扪虱，有客窥我床。","客来问何许，颜色惨不光。","去岁秋在季，文星坠西江。","而师罗一峰，幸视我弟兄。","相见不得语，失声泪滂滂。","子行诣湖西，问讯我有将。","夙昔梦见之，恍若芙蓉城。","觉来索苦句，句就涕未停。","何以告一峰，寄意于瓣香。","索火化奠文，一峰其洋洋。","我病久南海，欲往未得行。","送子出门去，目极秋天长。"]},{"t":"赠陈秉常 其一","f":"五言律诗","c":["远色霁初景，清风振遥林。","子来入我室，弄我花间琴。","正声一何长，幽思亦已深。","愿留一千岁，赠子瑶池音。"]},{"t":"赠陈秉常 其二","f":"五言律诗","c":["黍稷杂萑苇，邪思乱正性。","人为一卤莽，诿曰天之命。","白日朝出东，须臾复西暝。","良时诚可惜，逝矣悲莫竞。"]},{"t":"赠陈秉常 其三","f":"五言律诗","c":["大舜卷娄之，庄周竟奚取。","人生贵识真，勿作孟浪死。","谁能去中土，僦舍朝鲜里。","白首金石交，视我南川子。"]},{"t":"赠陈秉常 其四","f":"五言律诗","c":["我否子亦否，我然子亦然。","然否苟由我，于子何有焉。","人生寄一世，落叶风中旋。","胡为不自返，浊水迷清渊。"]},{"t":"藤蓑五首 其二","f":"五言律诗","c":["人好蓑亦好，月光水亦光。","水南有酒媪，酒热唤我尝。","半酣独速舞，舞罢还举觞。","所乐在知止，百年安可忘。"]},{"t":"藤蓑五首 其三","f":"五言古诗","c":["挽蓑欲何为，新月出东岭。","独速舞不休，凌乱何由整。","旷哉漆园吏，自形还自影。"]},{"t":"藤蓑五首 其五","f":"五言律诗","c":["朽生何所营，东坐复西坐。","搔头白发少，摊地青蓑破。","千卷万卷书，全功归在我。","吾心内自得，糟粕安用那。"]},{"t":"赛兰","f":"五言古诗","c":["南有赛兰香，名花人未识。","光风散微馨，甘露洗新碧。","一月薰蒸来，氤氲在肝膈。","乃知方寸根，中禀天地塞。","谁为续骚手，俯仰空悽恻。","窗户悄无人，图书共昕夕。"]},{"t":"天人之际","f":"五言律诗","c":["天人一理通，感应良可畏。","千载陨石书，春秋所以示。","客星犯帝座，他夜因何事。","谁谓匹夫微，而能动天地。"]},{"t":"答梅侍御见寄","f":"五言古诗","c":["群龙盛朝野，弱羽聊山林。","行春忽倾盖，对榻山花深。","引我一杯水，写君龙唇琴。","永言歌大篇，风雅有遗音。","乃知鹰鹯气，未惬鸾凤心。","王事有驱迫，暮雨别江浔。","离情落晚趣，再往三洲吟。","何以舒我怀，青天盼遥岑。"]},{"t":"寄题三洲岩","f":"五言古诗","c":["我行苍梧道，息桨荒江湄。","连冈一以眺，石室涵晚晖。","前哲有题字，执炬往读之。","迟回北壁下，目击元公遗。","今古一相感，光风吹我衣。","虫鸣丹灶中，葛仙胡不归。","对之发长啸，宇宙今何时。","圆蟾夜囧囧，蝙蝠秋飞飞。","愿言托高栖，行矣无是非。"]},{"t":"病中写怀寄李九渊","f":"五言古诗","c":["出门见斋颜，十日不一逢。","以我腹中满，忆君头上风。","头风尚可炙，腹满何由通。","受气我亦薄，况乃疾病攻。","五十去始衰，三四谢春冬。","鬓颜忽已彫，血气少复充。","客来索我书，颖秃不能供。","茅君稍用事，入手称神工。","以兹日衮衮，永负全生功。","长揖谢茅君，安静以待终。"]},{"t":"和梅侍御见寄","f":"五言古诗","c":["飞盖凌沧溟，高台拂朱鸟。","乾坤一水浮，日月双轮绕。","尘埃纷局促，正坐眼孔小。","景山千丈松，慰我冰雪皎。","万里一春风，东西逐騕袅。","故人子罗子，仙鹤归华表。","暮雨江门舟，含悽问封草。","假令鲍叔在，一士亦不少。","谁云越台近，举目河山杳。","冥冥白沙坞，云烟共昏晓。"]},{"t":"题刘氏双节卷二首 其一","f":"五言古诗","c":["阿姑与阿妇，守此芳岁阑。","三十寡且贫，纺绩供朝餐。","孤儿泣长夜，秉烛更抱看。","苦心两咽绝，芳颜亦彫残。","持此双白璧，辉映天地间。"]},{"t":"题刘氏双节卷二首 其二","f":"五言律诗","c":["圣皇重民极，门闾合施丹。","煌煌东白碑，终古埋空山。","我母寡更早，赋诗涕氿澜。","弱草因风靡，颓波良独难。"]},{"t":"漫题二首 其二","f":"五言古诗","c":["仕者必期通，隐者必期高。","麋鹿或可群，肉食安可饕。","圣人履中正，白首济川舠。","悠悠荷篑者，果识圣心劳。","浮云驰白日，黍稷生蓬蒿。","饭蔬食饮水，曲肱谢游遨。","汶上去不顾，陋巷贫绝交。","徒闻武城宰，割鸡以牛刀。"]},{"t":"拉马玄真看山","f":"五言古诗","c":["官府治簿书，倥偬多苦辛。","文士弄笔砚，著述劳心神。","而我独无事，隐几忘昏晨。","南山转苍翠，可望亦可亲。","岁暮如勿往，枉是最閒人。","近来饮酒者，惟我与子真。","能移柳间舫，同泛江门津。"]},{"t":"感刘琨与卢谌事","f":"五言古诗","c":["越石信英臣，子谅亦文雅。","生遭晋运微，奔走风尘下。","晋阳笑明月，胡雏夜回马。","并州困石勒，从事为别驾。","成败非所论，吾怜凿抔者。"]},{"t":"和陶 其一 移居","f":"五言古诗","c":["万金论买邻，千金论买宅。","岂不念子孙，而以营朝夕。","长揖都会里，来趋白沙役。","壤地何必广，吾其寄一席。","邻曲弥乐今，园林尚怀昔。","吾志在择善，无然复离析。"]},{"t":"和陶 九日閒居","f":"五言古诗","c":["无钱抚秋菊，向夕凉风生。","谁为白衣者，颇识江州名。","映杯碧水净，曜日丹葩明。","天际雁孤去，草根虫一声。","荏苒委时节，裴徊阅年龄。","兴来发长叹，意尽还一倾。","俭德苟不惭，厚禄安可荣。","白首希高贤，清谣渺遗情。","人生亦易足，何必勤无成。"]},{"t":"和刘柴桑寄袁道见怀一峰之意","f":"五言古诗","c":["当年台城会，执手多踟蹰。","四海一为别，寒暑逝不居。","远意属罗浮，举头望匡庐。","胡然金牛谷，奄忽成丘墟。","蜕骨归复土，灵衿存为畬。","庶几百代下，攀驾以忘劬。","袁侯西江英，好德眼中无。","尺素每欲近，十年不作疏。","磨剑患不快，快则随所须。","永愿磨此心，恢恢快剑如。"]},{"t":"和郭主簿寄庄定山","f":"五言古诗","c":["青松出乔木，遥望十里阴。","少年不结友，岁暮怀同襟。","同襟问为谁，定山携一琴。","悠然一鼓之，不辩古与今。","在昔经江东，多士予所钦。","论交一觞酒，惟我与子斟。","岂意千载下，复此闻韶音。","我病不出户，何时还盍簪。","茫茫宇宙内，与此契其深。"]},{"t":"赠羊长史寄辽东贺黄门钦","f":"五言古诗","c":["此心自太古，何必生唐虞。","此道苟能明，何必多读书。","寂寂委山泽，于于来京都。","斯人各有分，彼此何能踰。","杪秋风日清，呼儿理肩舆。","聊为玉台游，言笑谁与俱。","屈指意中人，一坐一踟蹰。","归来看四壁，四壁光如如。","圣道日榛塞，谁哉剪其芜。","夫子久不见，吾生何以娱。","常恐岁月晚，况与音问疏。","申以伐木章，一日三卷舒。"]},{"t":"庚戌岁九月中于西田穫早稻","f":"五言古诗","c":["迟明向南亩，疏星在檐端。","夫出妇亦随，无非分所安。","道旁往来人，下车时一观。","问津津不知，仰视飞鸟还。","逻苗远峙夕，濯足荒沟寒。","吾惜耦耕好，焉知世路难。","伐鼓收西畬，黄云被江干。","聊周代糟糠，作粥欢宾颜。","邻叟携儿来，嬉戏松下关。","齐声鼓腹讴，永谢攒眉欢。"]},{"t":"制布裘成偶题寄黎雪青","f":"五言古诗","c":["海布剪黄云，岭绵庄白雪。","制为道人衣，方直无周折。","吾老不出门，躬耕慕冀缺。","黄昏披此裘，坐望梅村月。","美人遗我酒，小酌三杯烈。","半酣发浩歌，声光真朗彻。","是身如虚空，乐矣生灭灭。"]},{"t":"紫菊吟寄林时嘉","f":"五言古诗","c":["严霜百卉枯，三径挺秋菊。","绿叶明紫英，微风递寒馥。","芳情谢桃李，雅望联松竹。","怀哉种花人，杳在江一曲。","遗我盎中金，南窗伴幽独。","时无续骚手，憔悴谁当录。","且脱头上巾，茅柴今可漉。"]},{"t":"感鸟","f":"五言古诗","c":["有鸟不知名，皎然闺中清。","育雏上庭竹，众鸟不敢凌。","暮雨衔虫归，唤雏雏不应。","以翼覆雏宿，夜久巢屡惊。","小仆极残忍，不眠伺东荣。","扳巢袭其母，母去巢亦倾。","一雏堕地死，二雏尚咿嘤。","平明视竹根，群蚁正经营。","子弱母护之，无母何以生。","呜呜号者死，宛有雌雄情。","入帘逼我枕，为我再三鸣。","此鸟初来巢，卑卑近前楹。","我无害鸟心，人谓此鸟灵。","终焉失所托，此祸将孰惩。","吾甚愧此鸟，感之欲沾缨。","呼奴挞其背，流血非所矜。","再拜谢此鸟，此意何由平。"]},{"t":"宾阳楼八景 其一 谷城呼月","f":"五言律诗","c":["微月瞰高楼，楼中酒初泻。","旁见谷城山，孰为呼月者。","腾腾露光景，寂寂开迥野。","笑问圯上翁，何如此山下。"]},{"t":"宾阳楼八景 其二 牌山樵唱","f":"五言律诗","c":["日夕楼上饮，瞻望南山阿。","樵夫睨林木，会意岂在多。","白云满山径，负薪行复歌。","人生异出处，贫贱奈尔何。"]},{"t":"宾阳楼八景 其三 罗水渔歌","f":"五言律诗","c":["有月来照人，沉竿坐罗水。","意与罗水深，夜静歌亦起。","江湖虽云乐，天地惧终否。","豪哉宾阳子，发积异姜吕。"]},{"t":"题万硕司训风木图","f":"五言古诗","c":["把君风木图，识君风木心。","贤者不易贵，远者宁务今。","嗟哉鼎与茵，充足时所钦。"]},{"t":"筑室","f":"五言古诗","c":["辛勤结吾庐，经始算一策。","广狭更度量，卑高在平秩。","堂以备荐享，阁以邀风日。","前榜贞节门，后治渭川室。","四垣谢粉饰，牡蛎高为骨。","仰瞻势微峻，其间仅容膝。","既以储简编，犹堪敛袍笏。","是年秋在仲，筮日欣得吉。","良友交助余，众工告易毕。","把酒对梅花，浩歌新突兀。"]},{"t":"读林缉熙近诗时缉熙典文衡闽中欲便道还家数夕前尝梦见之故有是作","f":"五言古诗","c":["言笑不可亲，中宵驰梦想。","君行几千里，道路轻闽广。","忽见囊中诗，区区谢官长。","深渊或遗珠，努力试一往。","微官亦何事，感激章欲上。","行止各有时，姓名忌标榜。","此言谁为傅，聊以慰俯仰。"]},{"t":"将如外海看山先寄道傍诸友","f":"五言古诗","c":["吾衰何所如，俯仰在一席。","舍傍有小水，相望渺南北。","静久动乃宜，住多行亦得。","朝往暮南还，路旁事旧识。","故人邀我饭，半饷吾未惜。","东老对回公，神仙无恶客。"]},{"t":"谢琴月惠荔枝","f":"五言古诗","c":["长夏风雨过，西良荔枝熟。","晚有好事人，提筐归我屋。","老母不肯尝，馨香闻隔宿。","上以荐祖考，交分及僮仆。","第令筐中有，不畏稚儿哭。","尔惠良足嘉，吾亲素多淑。","在德不在物，岂谓穷口腹。","东坡三百颗，日啖不知足。","长为岭南人，千载披心曲。"]},{"t":"赠李世卿六首 其三","f":"五言古诗","c":["进亦人所忧，退亦人所忧。","得亦人所忧，失亦人所忧。","所忧非忧道，所忧其可留。","所忧非忧贫，所忧其可休。","古来向道人，能辩忧所由。","去去凌九霄，行行戒深沟。","敬此之谓修，怠此之谓流。"]},{"t":"赠李世卿六首 其四","f":"五言律诗","c":["元神诚有宅，灏气亦有门。","神气人所资，孰谓老氏言。","下化囿其迹，上化归其根。","至要云在兹，自馀安足论。"]},{"t":"赠李世卿六首 其五","f":"五言古诗","c":["可以参两间，可以垂万世。","圣人与人同，圣人与人异。","尧舜于舞雩，气象一而已。","大者苟不存，翩翩竟奚取。","老夫尝用力，兹以告吾子。","文字费精神，百凡可以止。","一落永不收，年光建瓴水。"]},{"t":"赠李世卿六首 其六","f":"五言律诗","c":["上上昆崙峰，诸山高几重。","望望沧溟波，百川大几何。","卑高入揣料，小大穷多少。","不如两置之，直于了处了。"]},{"t":"容圭挽诗三首 其一","f":"五言古诗","c":["师友道久衰，穷乡无可者。","是非真妄间，彼此不相假。","所适一以偏，较然见趋舍。","滔滔复滔滔，风俗日益下。","圭也何所之，终身在陶冶。"]},{"t":"容圭挽诗三首 其二","f":"五言古诗","c":["四雏一母乳，衎衎东山岑。","二雏羽翼长，一去无遗音。","母哀二雏小，中夜哀莫任。","感此骨肉别，悄然伤我心。","萧萧暮色起，脉脉春江深。","百年会有尽，泪下雍门琴。"]},{"t":"容圭挽诗三首 其三","f":"五言律诗","c":["容氏多兄弟，西良此白眉。","源源来讲席，稍稍树头篱。","行可乡人敬，心惟我辈知。","临危仆且至，忍死待斯须。"]},{"t":"观自作茅笔书","f":"五言律诗","c":["神往气自随，氛氲觉初沐。","圣贤一切无，此理何由瞩。","调性古所闻，熙熙兼穆穆。","耻独不耻独，茅锋万茎秃。"]},{"t":"益母草","f":"五言古诗","c":["有草人不识，弃之等蒿莱。","时来见任使，到口生风雷。","溲也佐未足，益以蜜与醅。","生者得其养，死者无遗胎。","岐黄开本草，夭札人所哀。","一物具一周，神功不可猜。","佳名夙所慕，广济真天才。"]},{"t":"游圭峰同世卿作","f":"五言古诗","c":["穷居无岁年，老梦得迂朽。","永托山水间，东西事游走。","幽幽铁桥花，怅望未得手。","杖履聊此跻，微霜正疏柳。","敛襟欲无言，会意岂在酒。","沧海当我前，昆崙卓我后。","但谈孔氏规，坐失微生亩。"]},{"t":"示李孔修近诗","f":"五言古诗","c":["昔别秋未深，今来岁方晏。","吾衰忘笔砚，月记诗半板。","或疑子美圣，未若陶潜淡。","习气移性情，正坐闻道晚。","为我试读之，如君当具眼。"]},{"t":"八月二十四日?作多溺死者","f":"五言古诗","c":["坐忘一室内，天地极劳攘。","颠浪雷殷江，流云墨推障。","高田水灭顶，别坞风翻舫。","大块本无心，纵横小儿状。","江门三两诗，饶舌天机上。"]},{"t":"读张廷实主事近稿","f":"五言律诗","c":["世惟识宝人，惜宝如惜子。","宝为物所掩，念之容色悴。","一朝此宝来，辄复喜不已。","喜戚由宝故，以识为心累。"]},{"t":"赠针灸杨飞","f":"五言古诗","c":["昔吾见尔翁，卖药金陵市。","手持一寸针，针落病者起。","我主大行人，翩翩酒相值。","京中多异客，飞盖若流水。","一峰挟一囊，有药能医世。","时当引疾去，东西各飘逝。","岁月忽复多，囊括针亦废。","君来还见予，俯仰相悲喜。","何期二纪下，重睹无双技。","瞻彼老定山，风波五千里。","金陵多旧游，存殁宁复记。","人生若浮烟，为君语如是。"]},{"t":"正月二日雨雹","f":"五言古诗","c":["雨水不雨水，雨雹胡乃然。","小者如莲实，大者如弹丸。","仍闻隔江言，有雹大如拳。","吾君古帝尧，神功格皇天。","雹往而霰来，无乃为丰年。"]},{"t":"五日雨霰","f":"五言古诗","c":["北风卷长云，晨光坐来灭。","映空絮忽飞，谁谓越无雪。","元气塞天地，万古常周流。","闽浙今洛阳，吾邦亦鲁邹。","星临雪乃应，此语非谬悠。"]},{"t":"读张地曹偶拈之作","f":"五言古诗","c":["拈一不拈二，乾坤一为主。","一番拈动来，日出扶桑树。","寂然都不拈，江河自流注。","濂洛千载传，图书乃宗祖。","昭昭圣学篇，授我自然度。"]},{"t":"不习书绢殊失故态已付染师作碧玉老人卧帷矣呵呵拙诗纪兴录上顾别驾先生以博一笑","f":"五言古诗","c":["用绢不用里，下笔无神气。","何况辟其行，大小难更置。","能书法本同，万物性各异。","茅君疏而野，拘拘用乃废。","我且毛颖之，安能免濡滞。","书成始大惭，未忍水火弃。","持以付染师，经营卧帷事。","作诗告先生，其契茅君理。"]},{"t":"赠黎秀才","f":"五言律诗","c":["月行在青天，月影沉碧水。","谁为弄影人，吾与黎生耳。","黎生青云彦，偶值薇垣使。","明日还端阳，赠君惟有此。"]},{"t":"寄李子长 其一","f":"五言律诗","c":["仙城李子长，短发不及寸。","家有觅粟儿，时无郭元振。","经年断往还，使我勤问讯。","宁知造化心，天地无情尽。"]},{"t":"寄李子长 其二","f":"五言律诗","c":["祝融我当往，往处还自然。","未往亦由我，安知不是仙。","是身元有患，天道岂无缘。","难逢俗人说，可为知者传。"]},{"t":"卧游罗浮 其一 登飞云","f":"五言律诗","c":["马上问罗浮，罗浮本无路。","虚空一拍手，身在飞云处。","白日何冥冥，乾坤一风雨。","蓑笠将安之，徘徊四山暮。"]},{"t":"卧游罗浮 其二 度铁桥","f":"五言律诗","c":["一度一万丈，飞空本无铁。","何名为飞空，道是安排绝。","夜久天宇高，霜清万籁彻。","手持青琅玕，坐弄碧海月。"]},{"t":"卧游罗浮 其三 下黄龙","f":"五言律诗","c":["天风吹我笠，吹下黄龙顶。","两手捉笠行，不知白日暝。","赤松见我笑，却立千丈影。","童子问赤松，云深各不领。"]},{"t":"卧游罗浮 其四 望罗浮","f":"五言律诗","c":["山大必有灵，土高岂无异。","翠浮几千丈，日月东南翳。","我寻五岳来，未问仙家事。","绝顶望九州，衡山正西峙。"]},{"t":"赠周文都","f":"五言律诗","c":["十年两别君，一别一回老。","问药朱陵游，吾兹恨不早。","平生忧乐心，相对各倾倒。","远别望眼昏，浮云不堪扫。"]},{"t":"寄题严州严先生祠壁","f":"五言律诗","c":["既上桐江台，复弄桐江钓。","不食桐江鱼，不怕严光笑。","衣巾人笑侬，羊裘终未了。","堂堂范公碑，千古称独妙。"]},{"t":"寒菊","f":"五言律诗","c":["菊花正开时，严霜满中野。","从来少人知，谁是陶潜者。","碧玉岁将穷，端居酒堪把。","南山对面时，不取亦不舍。"]},{"t":"寄贺柯明府","f":"五言古诗","c":["世乱隳节义，临危忘大伦。","此风何可长，此恨何由申。","仲尼忧万世，作经因感麟。","往者宋元间，适逢大运屯。","仰天泣者谁，屈指张陆文。","临事诚已疏，哀歌竟云云。","一正天地纲，我祖圣以神。","缺典谁表章，厓山莽荆榛。","寥寥二百年，大忠起江濆。","慈元庙继作，烂映厓山云。","近者阳江尹，一念何精勤。","作祠比厓山，两庙存三仁。","大封赤坎墓，昭昭惬众闻。","深悲鱼腹冷，一跃海门春。","厓海风波隔，阳江面目新。","自然声气应，坐使风俗淳。","短卷心先贺，神交梦每亲。","琢词告万世，老病敢辞君。"]},{"t":"偶书所见","f":"五言古诗","c":["厓倾百丈泉，直下注东川。","翳流起大舂，覆茅于其巅。","一为利所驱，取便世争先。","汉阴喻桔槔，所见无不然。","嗟哉抱瓮心，古道何由全。"]},{"t":"谢邓督府惠交藤酒至","f":"五言古诗","c":["使来遗一樽，百金不愿易。","遇药如遇仙，奇方闻在昔。","卓哉李文公，作传甚详悉。","感公嘉惠心，何以酬公德。","但恐命不齐，服药也无益。"]},{"t":"晓枕","f":"五言古诗","c":["天地无穷年，无穷吾亦在。","独立无朋俦，谁为自然配。","舂陵造物徒，斯人可神会。","有如寿厓者，乃我之侪辈。","永结无情游，相期八纮外。"]},{"t":"题端阳李太守甘霖重应卷","f":"五言古诗","c":["岭南名刺史，端阳有成绩。","端阳问为谁，长沙垂令德。","曰惟长沙公，善非一代积。","去年苗欲槁，公寝不安席。","手拈一炷香，须臾见昭假。","今年事复然，斯民忻目击。","甘霖雨下土，郊野望四塞。","滂沱及邻壤，秋田足民食。","公惠宁有心，斯民感公德。","口颂遂成碑，举手还加额。","安得长沙公，为我大邦伯。","坐令十郡内，广布阳春泽。","闾阎兴孝悌，四野无盗贼。","共育太和春，絪缊谢反侧。"]},{"t":"偶得寄东所二首 其一","f":"五言律诗","c":["知暮则知朝，西风涨暮潮。","千秋一何短，瞬息一何遥。","有物万象间，不随万象凋。","举目如见之，何必穷扶摇。"]},{"t":"偶得寄东所二首 其二","f":"五言古诗","c":["登高未必高，老脚且平步。","平步人不疑，东西任四顾。","岂无见在心，何必拟诸古。","异体骨肉亲，有生皆我与。","失之万里途，得之咫尺许。","得失在斯须，谁能别来去。","明日立秋来，人方思处暑。"]},{"t":"和罗服周对菊见寄","f":"五言律诗","c":["春来苦不早，春去常愿迟。","嗟哉造化机，万物安得知。","岁晏菊始吐，鲜鲜在东篱。","不污桃李尘，永续徵君诗。"]},{"t":"龟山夜月","f":"五言古诗","c":["万古此龟山，万古此明月。","开帘望龟山，岱宗固无别。","但恐山多云，风吹乱人睫。"]},{"t":"马牙香","f":"五言古诗","c":["炉中煨白术，坐上有青天。","绮季奕未毕，夷齐上西山。","沉檀皆下品，欲语不同年。"]},{"t":"题心泉赠黄叔仁","f":"五言古诗","c":["夜半汲山井，山泉日日新。","不将泉照面，白日多飞尘。","飞尘亦无害，莫弄桔槔频。"]},{"t":"赠伍弼归觐","f":"五言律诗","c":["诸生胡不归，九月望庭闱。","山北山南道，纷纷落叶飞。","呼儿巾木榻，谢客掩荆扉。","不尽来时约，堪沾别处衣。"]},{"t":"真乐吟效康节体","f":"五言古诗","c":["真乐何从生，觉者不复言。","或疑诗语工，或云饮者贤。","或书役心情，或琴以自宣。","真乐生于心，乃在至和间。","行如云在天，止如水在渊。","静者识其端，此心当乾乾。"]},{"t":"得何时矩书","f":"五言古诗","c":["良友惠我书，书中竟何如。","上言我所忧，下述君所移。","开缄读三四，亦足破烦污。","丈夫立万仞，肯受寻尺拘。","不见柴桑人，丐食能欢娱。","孟轲走四方，从者数十车。","出处固有间，谁能别贤愚。","鄙夫患得失，较计于其初。","高天与深渊，悬绝徒嗟吁。"]},{"t":"晓起 其一","f":"五言绝句","c":["偶然风折木，村犬吠成群。","此事真难免，问君闻不闻。"]},{"t":"晓起 其二","f":"五言绝句","c":["辛苦南邻臼，远鸡方一鸣。","夜来风极急，吹断到窗声。"]},{"t":"晓起 其三","f":"五言绝句","c":["冬眠不觉晓，开门见白云。","云中何所有，童子两三人。"]},{"t":"湖西九岩为一峰题 其一 光霁岩","f":"五言绝句","c":["风月佳名在，乾坤浪迹空。","从来岩下客，祇与异人逢。"]},{"t":"湖西九岩为一峰题 其二 翠华岩","f":"五言绝句","c":["来说湖西者，不及华山顶。","谁知岩中仙，解作石柱屏。"]},{"t":"湖西九岩为一峰题 其三 清风岩","f":"五言绝句","c":["声从窦中来，可以塞天地。","借问采薇人，便知风动处。"]},{"t":"湖西九岩为一峰题 其四 府教岩","f":"五言绝句","c":["府教英灵在，虺蛇不敢居。","从来岩上月，只是照虚无。"]},{"t":"湖西九岩为一峰题 其五 极清岩","f":"五言绝句","c":["声名野老畏，草石贵人争。","刬却岩中有，悠悠是极清。"]},{"t":"湖西九岩为一峰题 其六 英公岩","f":"五言绝句","c":["翠掩千寻洞，青窥一窍天。","人间无绝境，不要问桃源。"]},{"t":"湖西九岩为一峰题 其七 扇和岩","f":"五言绝句","c":["山骨短圆棱，初疑削木成。","乾坤藏一柱，犹得镇岩扃。"]},{"t":"湖西九岩为一峰题 其八 卧龙岩","f":"五言绝句","c":["龙出潭水空，龙归潭水黑。","君从龙床来，谁在龙床侧。"]},{"t":"湖西九岩为一峰题 其九 月岩","f":"五言绝句","c":["闇闇月堕地，忽在天中央。","堕地人不觉，中天照四方。"]},{"t":"题慈元庙","f":"五言绝句","c":["慈元一片石，长留何处山。","厓门潮日至，雪浪飞天关。"]},{"t":"题画","f":"五言绝句","c":["金笼锁鹦鹉，山木纵斑鸠。","巧拙知谁是，天机不自由。"]},{"t":"题画松泉为张别驾","f":"五言绝句","c":["松乃木之雄，公亦人中龙。","何须看画本，千丈在胸中。"]},{"t":"对酒","f":"五言绝句","c":["放歌当尽声，饮酒当尽情。","门前乌桕树，夜半子规鸣。"]},{"t":"答丘侍御送酒","f":"五言绝句","c":["石斋书本拙，酒力巧相扶。","欲报霜台贶，山中一物无。"]},{"t":"雨后","f":"五言绝句","c":["久雨方行乐，花前望玉台。","人间见花树，不似玉台开。"]},{"t":"村步杂书所见 其一","f":"五言绝句","c":["疏花明委巷，细雨得今晨。","点缀非无意，红芳不是春。"]},{"t":"村步杂书所见 其二","f":"五言绝句","c":["公饭何曾接，衣冠不作人。","斋中有名酒，分尔一杯春。"]},{"t":"村步杂书所见 其三","f":"五言绝句","c":["晚食南山稻，堂堂愧野人。","平生无可说，一个白头亲。"]},{"t":"村步杂书所见 其四","f":"五言绝句","c":["村笛轰牛背，山花结帽头。","骑牛胜骑马，曲坂没郎愁。"]},{"t":"村步杂书所见 其五","f":"五言绝句","c":["趁罢江门市，商船夺港归。","溪山愁引望，城郭更须知。"]},{"t":"村步杂书所见 其六","f":"五言绝句","c":["日照南浦口，初喧江市人。","小奴性嗜酒，出饮畏吾嗔。"]},{"t":"戏赠求书饶大中还江右","f":"五言绝句","c":["书法一家成，风波几月程。","孤舟愁度险，荐福有雷声。"]},{"t":"代简答方伯彭公 其一","f":"五言绝句","c":["大贤望于人，往往非独守。","难将一人意，满足天下口。"]},{"t":"代简答方伯彭公 其二","f":"五言绝句","c":["氤氲复氤氲，东君欲放春。","梅花何太早，早报越城人。"]},{"t":"清晓乘驴出北风吹涧藤沉吟涧边道天意莫留行","f":"五言绝句","c":["行止皆前定，出门愁北风。","西郊不成往，昨夜梦途穷。"]},{"t":"赠邝知县云卿别","f":"五言绝句","c":["又送夫君别，芙容花可怜。","水深难折赠，留伴老夫眠。"]},{"t":"与诸友夜过贞节桥","f":"五言绝句","c":["人影荒桥下，虫声满月中。","连翩双大袖，聊得飐溪风。"]},{"t":"读张主事近稿","f":"五言绝句","c":["雨中月不见，雨霁月还多。","雨被风吹去，无风月奈何。"]},{"t":"对菊 其一","f":"五言绝句","c":["淅淅西风至，为秋未有涯。","江边聊一醉，信手得黄花。"]},{"t":"对菊 其二","f":"五言绝句","c":["不落龙山帽，何须九日风。","更烦将小雨，向晚洗花丛。"]},{"t":"对菊 其三","f":"五言绝句","c":["春事归桃李，西风响未休。","长官三径晚，丞相一坡秋。"]},{"t":"对菊 其四","f":"五言绝句","c":["好个重阳节，谁家酒不赊。","果然杀风景，吸茗对秋葩。"]},{"t":"对菊 其五","f":"五言绝句","c":["天地花无数，寒花色乃佳。","古诗拈未出，除是长官来。"]},{"t":"九月木犀花盛开偶成寄贺黄门克恭","f":"五言绝句","c":["香逐西风起，氤氲入杳冥。","不知从此去，几日到辽城。"]},{"t":"洗竹 其一","f":"五言绝句","c":["风引一丛竹，摇摇四五茎。","横斜今洗尽，道眼看圆成。"]},{"t":"洗竹 其二","f":"五言绝句","c":["洗竹洗荒枝，洗心洗狂驰。","老夫无可洗，抱膝洗吾诗。"]},{"t":"洗竹 其三","f":"五言绝句","c":["一洗一回疏，相将洗到无。","客来莫问我，北壁有团蒲。"]},{"t":"晓起 其一","f":"五言绝句","c":["篱头过井水，不打隔斋门。","手握南阳布，缠头数竹孙。"]},{"t":"晓起 其二","f":"五言绝句","c":["老不爱春华，一篱孤负花。","胡为聒我枕，稚子打朝鸦。"]},{"t":"晓起 其三","f":"五言绝句","c":["自有无情蝶，孤飞不傍花。","白头闻见少，閒动羽虫嗟。"]},{"t":"观群儿钓 其一","f":"五言绝句","c":["群儿齐弄钓，其一偏多遇。","馀三未得手，投竿来上树。"]},{"t":"观群儿钓 其二","f":"五言绝句","c":["仰面看垂钓，失脚堕危石。","若是谪仙人，水中眠亦得。"]},{"t":"阅丁知县传","f":"五言绝句","c":["模样从看拙，丹青只写真。","乾坤如许大，具眼岂无人。"]},{"t":"梦中作","f":"五言绝句","c":["翩翩复翩翩，天生我亦仙。","江山足风月，吟弄到何年。"]},{"t":"梦丁彦诚","f":"五言绝句","c":["与君生死别，三四岁星周。","梦语分明记，相悲各点头。"]},{"t":"对竹 其一","f":"五言绝句","c":["竹色上墙多，南薰绿几何。","时无分付处，野鸟自来歌。"]},{"t":"对竹 其二","f":"五言绝句","c":["窗外竹青青，窗间人独坐。","究竟竹与人，元来无两个。"]},{"t":"对竹 其三","f":"五言绝句","c":["北风卷顽云，阴晴安可卜。","海月出渐高，独照南窗竹。"]},{"t":"随笔 其一","f":"五言绝句","c":["苟能深积累，岂患无高誉。","如何世中人，甘心铁炉步。"]},{"t":"随笔 其二","f":"五言绝句","c":["一岁十匹衣，一日两杯饭。","真乐苟不存，衣食为心患。"]},{"t":"随笔 其三","f":"五言绝句","c":["人不能外事，事不能外理。","二障佛所言，吾儒宁有此。"]},{"t":"随笔 其四","f":"五言绝句","c":["断除嗜欲想，永撤天机障。","身居万物中，心在万物上。"]},{"t":"随笔 其五","f":"五言绝句","c":["小雨闭空斋，青青竹映阶。","道人终日静，一枕到无怀。"]},{"t":"随笔 其六","f":"五言绝句","c":["子美诗之圣，尧夫更别传。","后来操翰者，二妙少能兼。"]},{"t":"梅下杂诗 其一","f":"五言绝句","c":["朝凭曲栏西，暮凭曲栏东。","栏里梅花好，看花了病翁。"]},{"t":"梅下杂诗 其二","f":"五言绝句","c":["久共宽閒地，侬薰自在香。","折来何所寄，只是寄辽阳。"]},{"t":"赠人","f":"五言绝句","c":["萱亲垂九十，游子尚天涯。","莫舣仙城棹，南风夜引旗。"]},{"t":"读易偶成","f":"五言绝句","c":["南乎不可北，东乎不可西。","自从孔孟来，君子恒处暌。"]},{"t":"张克修别驾约游罗浮","f":"五言绝句","c":["重叠四百峰，铁桥在何处。","莫将别驾来，同到飞云去。"]},{"t":"张克修见访","f":"五言绝句","c":["沧溟几万里，山泉未盈尺。","到海观会同，乾坤谁眼碧。"]},{"t":"题刘鉴松","f":"五言绝句","c":["刘生于写松，能以酒力遣。","酩酊气正豪，苍龙自舒卷。"]},{"t":"题扇 其一","f":"五言绝句","c":["风樯拗欲折，五月瞿塘过。","何如此庵中，红日抱膝坐。"]},{"t":"题扇 其二","f":"五言绝句","c":["张帆海上回，帆挂铁桥树。","惊起白虾蟆，跳上飞云去。"]},{"t":"赠胡地官次韵吴明府献臣 其一","f":"五言绝句","c":["有一范仲淹，人将重名节。","马上地曹郎，翩翩起吾粤。"]},{"t":"赠胡地官次韵吴明府献臣 其二","f":"五言绝句","c":["引满花下杯，延缘坐中客。","醉不大袖歌，孰云此门窄。"]},{"t":"题林府尊寿家慈书后","f":"五言绝句","c":["马尾缘封事，鱼缄寿老亲。","古今诚一揆，藉用白茅人。"]},{"t":"题顾通府集古倡和卷后","f":"五言绝句","c":["满眼珠玉光，高才极雄骋。","对之不敢言，稚子来弄影。"]},{"t":"梦后作 其一","f":"五言绝句","c":["策杖独行游，青山一何深。","道逢采药人，问我松脂林。"]},{"t":"梦后作 其二","f":"五言绝句","c":["见月时一吟，夜凉天称心。","回头望东川，流水无古今。"]},{"t":"梦后作 其三","f":"五言绝句","c":["幻迹有去来，达观无古今。","长啸人不闻，山风吹罗襟。"]},{"t":"梦后作 其四","f":"五言绝句","c":["杨柳馀朽株，梧桐但疏阴。","小卧不出门，不知秋已深。"]},{"t":"赠邝筠巢","f":"五言绝句","c":["山中一夜秋，老屋居然别。","丈人不饮酒，共坐看明月。"]},{"t":"客乞题随时子轩","f":"五言绝句","c":["无雨笠且置，未晴蓑不舍。","蓑笠用不穷，我是随时者。"]},{"t":"题扇 其一","f":"五言绝句","c":["东艇拍西艇，小拍庸何伤。","夕风起惊涛，艇艇争低昂。"]},{"t":"题扇 其二","f":"五言绝句","c":["一夫眉正扬，一夫发尽秃。","日暮船正归，前江风拔木。"]},{"t":"蒋韶州世钦挽诗 其一","f":"五言绝句","c":["治郡声名远，如何是我诗。","青山韶石老，回首尽交期。"]},{"t":"蒋韶州世钦挽诗 其二","f":"五言绝句","c":["往事形骸外，如今一梦休。","曹溪分我茗，犹说蒋韶州。"]},{"t":"周京闻母丧归吊以是诗","f":"五言绝句","c":["万里无归耗，形将一木亲。","遗言入肝肺，真得太夫人。"]},{"t":"题南窗壁","f":"五言绝句","c":["南风吹面处，不省是南窗。","此意无人会，乾坤落酒缸。"]},{"t":"雨后示刘宗信林时嘉 其一","f":"五言绝句","c":["一雨变新凉，炎埃洗除尽。","庐山昨夜灯，已照刘宗信。"]},{"t":"雨后示刘宗信林时嘉 其二","f":"五言绝句","c":["秋来亦淫潦，日月閟其光。","乾坤丈夫事，千古空堂堂。"]},{"t":"漫笔","f":"五言绝句","c":["幅巾是秀才，袈裟是和尚。","伎俩人共知，长篇事标榜。"]},{"t":"神泉八景为饶鉴赋其四赠之 其一 太极涵虚","f":"五言绝句","c":["混沌固有初，浑沦本无物。","万化自流形，何处寻吾一。"]},{"t":"神泉八景为饶鉴赋其四赠之 其二 浮螺得月","f":"五言绝句","c":["道眼大小同，乾坤一螺寄。","东山月出时，我在观溟处。"]},{"t":"神泉八景为饶鉴赋其四赠之 其三 茶山分香","f":"五言绝句","c":["江门白藕花，我榻庐山顶。","君若去茶山，茶香复谁领。"]},{"t":"神泉八景为饶鉴赋其四赠之 其四 神泉漱玉神泉漱玉神泉漱玉","f":"五言绝句","c":["焦明亦是凤，萤焰只疑灯。","安得石上泉，为洗世中肓。"]},{"t":"神泉八景为饶鉴赋其四赠之 其五 九日","f":"五言绝句","c":["霜前淡淡花，瓢内深深酒。","今日陶渊明，庐山作重九。"]},{"t":"神泉八景为饶鉴赋其四赠之 其六","f":"五言绝句","c":["同俗不同俗，山杯映秋菊。","仍闻席上歌，不是人间曲。"]},{"t":"神泉八景为饶鉴赋其四赠之 其七","f":"五言绝句","c":["歌舞重阳酒，今年犹去年。","山中八石榻，榻榻是回仙。"]},{"t":"神泉八景为饶鉴赋其四赠之 其八 读李评事承芳文","f":"五言绝句","c":["著论必无同，乾坤孰此容。","人扶周孔教，用世且无功。"]},{"t":"一囊包宇宙到手问纲常所以东坡老嘐嘐薄武王","f":"五言绝句","c":["不薄论交意，因书稍稍知。","还将天下眼，照破老夫痴。"]},{"t":"送刘宗信还增城 其一","f":"五言绝句","c":["夜宿黄云坞，秋登碧玉楼。","归时一片石，见月过罗浮。"]},{"t":"送刘宗信还增城 其二","f":"五言绝句","c":["山到铁桥西，青天一角低。","送君高处望，天与帽檐齐。"]},{"t":"送刘宗信还增城 其三","f":"五言绝句","c":["菊花笑我前，梅花撩我后。","问花花不言，驻楫增江口。"]},{"t":"送刘宗信还增城 其四","f":"五言绝句","c":["山人偶出村，送客村南道。","江山风日佳，岁月乾坤老。"]},{"t":"赠张叔亨侍御出按云南","f":"五言绝句","c":["到治一万里，使君行莫迟。","梅花开树树，不是向南枝。"]},{"t":"碧玉楼晚望","f":"五言绝句","c":["楼远见诸山，目短意不尽。","天阴水怪兴，碧玉所以镇。"]},{"t":"赠克修别驾迁梧州守来别白沙赠之 其一","f":"五言绝句","c":["甲兵满一船，江门来访别。","赠君欲何言，笑把梅花折。"]},{"t":"赠克修别驾迁梧州守来别白沙赠之 其二","f":"五言绝句","c":["少年恣行游，老病徒拘缀。","送君今夜心，还到苍梧去。"]},{"t":"赠陈頀湛雨 其一","f":"五言绝句","c":["说到忘言处，无诗可赠君。","许将临别意，一点落黄云。"]},{"t":"赠陈頀湛雨 其二","f":"五言绝句","c":["君若问鸢鱼，鸢鱼体本虚。","我拈言外意，六籍也无书。"]},{"t":"送李子长往怀集取道谒张梧州 其一","f":"五言绝句","c":["春棹去江门，溯流焉汲汲。","点笔烟外山，归来看怀集。"]},{"t":"送李子长往怀集取道谒张梧州 其二","f":"五言绝句","c":["不闻端别驾，敬士如子长。","问道苍梧下，登歌刺史堂。"]},{"t":"赠范能用 其一","f":"五言绝句","c":["溽暑不可处，清风时满楼。","如何传别教，衲被坐蒙头。"]},{"t":"赠范能用 其二","f":"五言绝句","c":["阮籍见孙登，只闻孙登啸。","针在绣不传，绣传针不妙。"]},{"t":"西良容伦馈荔枝非桂州本色戏以是诗","f":"五言绝句","c":["口溢桂州浆，眼定西良色。","我是荔枝仙，何人解漫得。"]},{"t":"寿南山翁七十 其一","f":"五言绝句","c":["朝看亦南山，暮看亦南山。","南山长不老，聊以永君年。"]},{"t":"寿南山翁七十 其二","f":"五言绝句","c":["万株松上花，千日杯中酒。","儿孙戏膝前，一舞一回寿。"]},{"t":"赠太守黄公","f":"五言绝句","c":["水白端阳色，梅红岭上花。","春风迎度马，秋月候归槎。"]},{"t":"题宋丞相陈俊卿画像","f":"五言绝句","c":["御史铁为肝，张秦挂舌端。","至今湖峤月，犹作太师看。"]},{"t":"题宋状元陈文龙画像","f":"五言绝句","c":["文章甲天下，气节愧当时。","公母亦滂母，千秋名共驰。"]},{"t":"梁惟正邓德昌往来白沙途中遇盗惟正以舟泊浅奔于岸避之德昌抱书立船头盗不加害戏赠以诗","f":"五言绝句","c":["道逢恶少年，打破两生敬。","试问邓德昌，何如梁惟正。"]},{"t":"晓枕偶成 其一","f":"五言绝句","c":["采义非采薇，食薇不食粟。","遥遥望西山，千古嵯峨独。"]},{"t":"晓枕偶成 其二","f":"五言绝句","c":["西北多奇峰，云深香难认。","汉廷无谋臣，黄绮皆真隐。"]},{"t":"度危桥","f":"五言绝句","c":["事至绝安排，放脚踏高崖。","如何谢上蔡，旦旦习危阶。"]},{"t":"赠闵督府还升南京秋官 其一","f":"五言绝句","c":["司寇今欲行，病叟山中卧。","如闻经略忧，未向春风破。"]},{"t":"赠闵督府还升南京秋官 其二","f":"五言绝句","c":["吾闻用世心，中外无异等。","何由一送公，细话东西省。"]},{"t":"赠林府尊","f":"五言绝句","c":["彼曰春泥人，此曰人泥春。","晨朝出相送，向夕望归轮。"]},{"t":"赠李克常","f":"五言绝句","c":["桃花被东岸，江水日日深。","赠君岂无言，亦有花水吟。"]},{"t":"感事漫述与王乐用 其一","f":"五言绝句","c":["丁侯为县时，不与谒者通。","古称奉法吏，秉笔惟至公。"]},{"t":"感事漫述与王乐用 其二","f":"五言绝句","c":["留情重留情，狱事果难明。","无轻赤子命，为官急书程。"]},{"t":"感事漫述与王乐用 其三","f":"五言绝句","c":["士而未闻道，未免为物挠。","卓哉安心人，外事若无好。"]},{"t":"感事漫述与王乐用 其四","f":"五言绝句","c":["舍已莫委命，从人莫登山。","呜呼罗一峰，逐善如转圜。"]},{"t":"寄淮上秋官姜仁夫","f":"五言绝句","c":["问客淮南道，停舟过此无。","庐冈一端帛，为我谢仁夫。"]},{"t":"答王按治求乃翁挽四绝 其一 乐善堂","f":"五言绝句","c":["乐善机应熟，垂声教不穷。","江山无尽意，犹在典刑中。"]},{"t":"答王按治求乃翁挽四绝 其二 月湖别墅","f":"五言绝句","c":["水月非无主，长怀别墅秋。","湖光一万顷，端为此翁留。"]},{"t":"答王按治求乃翁挽四绝 其三 可怡亭","f":"五言绝句","c":["此地还成趣，庭柯几度扳。","亭中人不见，月照门前山。"]},{"t":"答王按治求乃翁挽四绝 其四 吴山寿藏","f":"五言绝句","c":["山隐一抔土，人思百代传。","无穷身后事，未若子孙贤。"]},{"t":"题丁长官庙","f":"五言绝句","c":["何时重借寇，此地一桐乡。","四海诸侯望，千年一炷香。"]},{"t":"会翠亭","f":"五言绝句","c":["东池久寂寞，会翠得佳名。","小诗拈未出，去寻王右丞。"]},{"t":"吴主簿诗主簿名则宣平人吴黄门仕伟之父也 其一 军门止杀","f":"五言绝句","c":["泣罪天应见，坑降地不知。","自然殃庆至，天道不须疑。"]},{"t":"吴主簿诗主簿名则宣平人吴黄门仕伟之父也 其二 过与弗取","f":"五言绝句","c":["百世高公绰，千金谢鲁连。","胸中无雅度，胜事竟谁传。"]},{"t":"吴主簿诗主簿名则宣平人吴黄门仕伟之父也 其三 卜筑西溪","f":"五言绝句","c":["主簿能经济，中年未乞身。","西溪看卜筑，知是宴眠人。"]},{"t":"寄严州林郡博缉熙","f":"五言绝句","c":["万紫千红外，如君故可人。","桐江都满树，海驿尚含春。"]},{"t":"寄东所","f":"五言绝句","c":["春江正满时，未具衡阳楫。","还携邓俊圭，江门与君别。"]},{"t":"梦林缉熙 其一","f":"五言绝句","c":["酒阑歌不起，老病无奈何。","梦满桐江雨，相对不成歌。"]},{"t":"梦林缉熙 其二","f":"五言绝句","c":["山楼本无梦，我自梦严州。","严州谁梦我，白云天际流。"]},{"t":"答柯明府","f":"五言绝句","c":["终秉循良笔，难逃俗吏媸。","不知三考绩，课最竟何须。"]},{"t":"赠雷少尹还汀州","f":"五言绝句","c":["桔槔满天地，抱瓮古来难。","哦松非俗吏，哦松不在山。"]},{"t":"觉后","f":"五言绝句","c":["马图不出河，铅刀不割痴。","上下几千年，掩卷一沾衣。"]},{"t":"谢姜大参惠酒","f":"五言绝句","c":["名公遗我酒，洗盏自开尝。","何以酬佳贶，商歌示不忘。"]},{"t":"武进八景为徐岭南纮作 其一 龙山春雨","f":"五言绝句","c":["长夏龙山晓，人间望忽开。","长风捲雨去，复送云归来。"]},{"t":"武进八景为徐岭南纮作 其二 笠泽烟波","f":"五言绝句","c":["何处烟波好，公乘笠泽槎。","我泛江门月，乾坤共一家。"]},{"t":"武进八景为徐岭南纮作 其三 龟山夜月","f":"五言绝句","c":["夜半龟山月，能开万顷秋。","试从开处望，照公湖上楼。"]},{"t":"武进八景为徐岭南纮作 其四 陈湾叠嶂","f":"五言绝句","c":["丹青工写似，陈湾叠嶂新。","我诗君莫笑，还属姓陈人。"]},{"t":"武进八景为徐岭南纮作 其五 薛堰通津","f":"五言绝句","c":["薛堰归何处，披图想具区。","古来探本论，无欠也无馀。"]},{"t":"武进八景为徐岭南纮作 其六 亭山夕照","f":"五言绝句","c":["亭山不可喻，华顶凌天台。","卑高本自形，夕照从西来。"]},{"t":"武进八景为徐岭南纮作 其七 庙墩灵迹","f":"五言绝句","c":["救溺如救火，造次遂捐生。","金陵人去远，拗鬼不来争。"]},{"t":"武进八景为徐岭南纮作 其八 板桥书屋","f":"五言绝句","c":["板桥蔼吾伊，名称已盖世。","谁云龟山月，不照新堂睡。"]},{"t":"答无锡诸友","f":"五言绝句","c":["碧玉通书久，青天感兴新。","江门动秋思，聊因寄远人。"]},{"t":"送米与何侃","f":"五言绝句","c":["野馔家禽小，村舂晚粒香。","莫言无厚馈，吾意在分尝。"]},{"t":"九日用旧韵","f":"五言绝句","c":["新篘压两壶，落英携满袖。","我非陶长官，庐山还九九。"]},{"t":"送黄希颜之太平推官","f":"五言绝句","c":["有官五马后，无官百揆前。","不将前后看，须著有无言。"]},{"t":"题高瑨诗集","f":"五言绝句","c":["神交倾盖上，心远著诗时。","无由向人道，人亦岂能知。"]},{"t":"纪梦","f":"五言绝句","c":["一别三十年，相逢不相识。","骨肉为路人，春风泪沾臆。"]},{"t":"寄潘留鹤","f":"五言绝句","c":["有时牛亦坐，何处鹤还留。","天台二万丈，谁踏紫冥讴。"]},{"t":"题伍光宇碑阴","f":"五言绝句","c":["松柏孤高处，春风更可寻。","如君有贤配，昭德在碑阴。"]},{"t":"答廷实有怀见寄","f":"五言绝句","c":["白云满中野，此地即衡山。","莫拟西来棹，须防失路难。"]},{"t":"谢孟芳遗腹生男","f":"五言绝句","c":["充闾人所喜，今日怆还深。","忆我初求乳，谁知母氏心。"]},{"t":"赠吴惠州绎思","f":"五言绝句","c":["皂盖朝天阙，青山道故乡。","高堂开寿斝，酩酊别莆阳。"]},{"t":"鸲鹆 其一","f":"五言绝句","c":["初日上茅檐，江边有画船。","八哥莫饶舌，有诏许归眠。"]},{"t":"鸲鹆 其二","f":"五言绝句","c":["鸲鹆能言鸟，能言我恨无。","白头书小楷，不及蔡君模。"]},{"t":"九日诸生携酒饮白沙醉中和答 其一","f":"五言绝句","c":["老病得狂痴，欢呼九日期。","自补登山屐，谁供把酒卮。"]},{"t":"九日诸生携酒饮白沙醉中和答 其二","f":"五言绝句","c":["诸君为饮会，老子不须期。","尽数篱前菊，一花拈一卮。"]},{"t":"九日诸生携酒饮白沙醉中和答 其三","f":"五言绝句","c":["九九八十一，去来无穷期。","元精为我酒，大块为我卮。"]},{"t":"对酒用九日韵 其一","f":"五言绝句","c":["秋花新气味，秋月旧襟期。","独唱花前曲，閒倾月下卮。"]},{"t":"对酒用九日韵 其二","f":"五言绝句","c":["行年三十许，已卜入山期。","处处开花径，床床是酒卮。"]},{"t":"对酒用九日韵 其三","f":"五言绝句","c":["饮酒何必多，醺酣以为期。","不辞亦不劝，三卮或五卮。"]},{"t":"对酒用九日韵 其四","f":"五言绝句","c":["作诗尚平淡，当与风雅期。","如饮玄酒者，器用瓦为卮。"]},{"t":"梅花 其一","f":"五言绝句","c":["水陆花无数，南枝爱杀人。","遥持一杯酒，江上酹花神。"]},{"t":"梅花 其二","f":"五言绝句","c":["逢人问除日，君得地曹郎。","此意凭谁寄，梅花隐石床。"]},{"t":"九日怀麦岐时往江东未返用前韵 其一","f":"五言绝句","c":["东西填脚债，已过一秋期。","今日拈花处，思君第一卮。"]},{"t":"九日怀麦岐时往江东未返用前韵 其二","f":"五言绝句","c":["茱萸何处酒，胜日与君期。","渔翁歌独钓，江月夜明卮。"]},{"t":"周镐送白菊乞诗 其一","f":"古风","c":["陶令黄金绕舍，君家白玉满园。","千古清风庐阜，几丛细雨江门。"]},{"t":"周镐送白菊乞诗 其二","f":"古风","c":["微醉不须酩酊，半开莫待离披。","安得季芳与语，相思欲寄一枝。"]},{"t":"周镐送白菊乞诗 其三","f":"古风","c":["白菊偏宜素发，青山只对苍颜。","咽罢秋香满腹，风吹不到长安。"]},{"t":"邀丁县主赏菊","f":"古风","c":["社会赋诗不就，公当酬我杯盘。","小酌倘寻旧雨，东篱还对长官。"]},{"t":"题枕","f":"古风","c":["太华峰头一枕，千秋万岁通灵。","不怕恶蛙惊睡，鼻端三月雷鸣。"]},{"t":"漫兴 其一","f":"古风","c":["风洒数茎白雪，月临一丈青筇。","馀事归诗卷里，残年放酒杯中。"]},{"t":"漫兴 其二","f":"古风","c":["景斜瓦碗方食，日晏柴门未开。","五柳前身处士，一瓢今日颜回。"]},{"t":"漫兴 其三","f":"古风","c":["晨光沼上鱼戏，夕阳村边鸟来。","东邻小儿识我，一日上树千回。"]},{"t":"漫兴 其四","f":"古风","c":["翠烟绿树歌鸟，青水红渠浴鸥。","笑问五湖范蠡，清风何处扁舟。"]},{"t":"伍光宇卜室白沙为读书之所 其一","f":"七言绝句","c":["君此卜居君亦足，空村无人山多木。","参差芭蕉丽晨旭，新叶新心递相续。"]},{"t":"伍光宇卜室白沙为读书之所 其二","f":"七言绝句","c":["竞晨登登闻隔竹，东邻老人事幽卜。","瓷瓯瓦盆不供俗，我不到门此翁独。"]},{"t":"答段锦衣惠药","f":"七言绝句","c":["药来诗往共谁忙，野老无金与段郎。","泉石旌旗俱在眼，不应泉石独膏肓。"]},{"t":"闻揽山近有车马之迹因赠缉熙并寄竹斋丈","f":"七言绝句","c":["白日传呼搅翠崖，谁家玉树碧云埋。","只疑冬酒开松径，定有山灵怨竹斋。"]},{"t":"夜坐与童子方祥庆话别偶成","f":"七言绝句","c":["晚饭跏趺竹几安，秋吟涕泪阁灯残。","一诗可送方童子，千炼不如庄定山。"]},{"t":"往潮连人事","f":"七言绝句","c":["独速蓑衣舞我航，数家烟树隔迷茫。","不将起倒供人事，祗为看花也未忙。"]},{"t":"柳渡月下承苕溪翁约赏中秋月于潮连","f":"七言绝句","c":["年颜欲比苕溪老，酒盏同挥夜月圆。","来共主人秋半醉，更回杨柳渡头船。"]},{"t":"次韵张叔亨侍御见寄","f":"七言绝句","c":["酒舫当年兴未涯，清宵人语白鸥沙。","如今纵有相思梦，不到长安御史家。"]},{"t":"看柳","f":"七言绝句","c":["浅塘低竹小坭村，黄土墙扃白板门。","望见西头杨柳树，行人都讶是桃源。"]},{"t":"杂兴 其一","f":"七言绝句","c":["曲肱深闭倚山阁，照眼不堪临路花。","一身老去何须出，两脚朝来只欲麻。"]},{"t":"杂兴 其二","f":"七言绝句","c":["倚槛才看一两花，不堪终日雨斜斜。","先生已结僧趺坐，还与人间管岁华。"]},{"t":"杂兴 其三","f":"七言绝句","c":["白日几时生羽翼，金丹负我不神仙。","东家茗碗频分啜，两腋清风也可怜。"]},{"t":"溪桥晚立示诸郎","f":"七言绝句","c":["溪边明月扫不去，竹下清风时一呼。","天与乃公供打睡，莫安桥板引樵渔。"]},{"t":"斋大父忌作旧居在道娘坟东","f":"七言绝句","c":["道娘坟西近官路，朝朝暮暮行人多。","世事百年浑不省，满堂宾客竹枝歌。"]},{"t":"得陈德雍书年九十馀矣犹有愿学之志","f":"七言绝句","c":["越客初披手翰新，天涯暮雨欲沾巾。","可怜一片长江水，日夜东流不待人。"]},{"t":"望顶湖山","f":"七言绝句","c":["客子正歌山鬼句，篙师欲进顶湖船。","遥看落日苍梧外，独立横槎古寨边。"]},{"t":"夜过三洲岩读濂溪题名示诸生","f":"七言绝句","c":["山容寂寞红叶老，江月照耀青天高。","题名夜半寻周子，秉炬相随爱尔曹。"]},{"t":"华盖仙踪为谢布政作时谢已物故","f":"七言绝句","c":["华盖山头云起时，群仙云里谢弹棋。","谢公不用登山屐，借得千秋一鹤归。"]},{"t":"东轩独坐","f":"七言绝句","c":["桃花寂寞梨花开，山中薄酒三五杯。","村西有客可人意，风雨今朝期不来。"]},{"t":"虎夜出","f":"七言绝句","c":["虎头缒渊雨即下，山中白额还遭打。","今年雨足汝不知，稍出人间食牛马。"]},{"t":"次韵赵提学见寄 其一","f":"七言绝句","c":["蒿莱封径不腰镰，长夏山斋睡正甜。","风送歌声满天地，惊回残梦雨廉纤。"]},{"t":"次韵赵提学见寄 其二","f":"七言绝句","c":["老大行藏敢不疑，晓川红日睡醒时。","昨宵共对崖山雨，如此乾坤那得知。"]},{"t":"卜日修外海赤泥岭祖墓值雨","f":"古风","c":["冬雨坟头蒿已生，年年披草祭清明。","晚风吹落携锄艇，又听?辀隔水声。"]},{"t":"与景星夜坐","f":"七言绝句","c":["拨闷无人致酒瓶，哦诗灯下一郎清。","夜深笑拍胡床语，忽乱阶前落叶声。"]},{"t":"西樵山下感旧 其一","f":"七言绝句","c":["西风吹老锦岩春，遗迹荒凉此水滨。","云气不遮西望眼，青山刚对独归人。"]},{"t":"西樵山下感旧 其二","f":"七言绝句","c":["西樵山前暝鹤归，缟衣双拂锦屏飞。","凄凉夜半孤舟客，一听遗音泪满衣。"]},{"t":"西樵山下感旧 其三","f":"七言绝句","c":["德孚先生留此眠，南山挥手白沙船。","江山此日三人别，谁道人生无百年。"]},{"t":"示建旌节亭役者","f":"七言绝句","c":["照曜乾坤功不小，此风此日更须扶。","泮宫畚土皆民力，不共城郎一例书。"]},{"t":"次韵赵提学留别白沙","f":"七言绝句","c":["列炬溪边树影斜，隔花遥迓使君车。","酒杯欲别微风起，吹动馨香下柳沙。"]},{"t":"蕉丽望罗浮","f":"七言绝句","c":["翠锦为山白锦云，画工传影不传神。","今朝蕉丽江头望，魂爽何由得傍身。"]},{"t":"黄连滘即事","f":"七言绝句","c":["青草桥边船未归，曲川微雨暗荆扉。","江村尽日无来往，夫在东皋妇给炊。"]},{"t":"上帆","f":"七言绝句","c":["蜻蜓翅短不能飞，款款随风堕客衣。","此是天人相合处，蒲帆高挂北风归。"]},{"t":"落花","f":"七言绝句","c":["落花半落流水香，鸣鸠互鸣春日长。","美人别我隔江浦，欲来不来空断肠。"]},{"t":"清晓","f":"七言绝句","c":["清晓有人来款扉，风吹衫袖白披披。","昨宵雨打山窗破，莫怪先生下榻迟。"]},{"t":"喜生侄","f":"七言绝句","c":["两翁筋力少翁衰，竹杖先堪付若儿。","只恐暮年诗更逸，出门须背锦囊随。"]},{"t":"新设纸帐轩中 其一","f":"七言绝句","c":["如云白纸罩方床，翠簟眠穿我固当。","世到葛天终不远，先生枕外即羲皇。"]},{"t":"新设纸帐轩中 其二","f":"七言绝句","c":["阶面苔侵牡蛎墙，小轩容易领年光。","只从今夜床头月，已照先生鬓脚霜。"]},{"t":"杂诗三首 其一","f":"七言绝句","c":["十年自汗不曾乾，枕上残书白首看。","莫道无心与君别，樽前更觉别君难。"]},{"t":"杂诗三首 其二","f":"七言绝句","c":["人间骨肉薄秋云，一事朝来不忍闻。","何处青山封宿草，欲将衰泪洒孤坟。"]},{"t":"宿倪麟所石榴花秋开","f":"七言绝句","c":["老蟾半影秋如水，曙色一声霜满街。","白发山人到城府，石榴花下借眠来。"]},{"t":"催诸友九日诗课","f":"七言绝句","c":["九日楼前客令新，黄花爱酒不饶贫。","劝君火急交诗课，才到明朝罚主人。"]},{"t":"题杜少陵小影次韵柳文肃","f":"七言绝句","c":["孟子诗肩高耸山，杜陵谈笑古风还。","世间还对忧时画，美酒花前已破颜。"]},{"t":"与旧童子","f":"七言绝句","c":["神药烧茶伴老夫，昔时童子今生须。","青春过眼如白水，白雪满头非故吾。"]},{"t":"谢惠酒","f":"七言绝句","c":["白发苍颜老石斋，出门秋思满天涯。","极怜紫酒逡巡有，不负黄花点缀佳。"]},{"t":"五月二十七夜?风作屋漏","f":"七言绝句","c":["灯残四壁漏痕斜，老屋回风落细沙。","乾坤更有晴明日，为报家人莫怨嗟。"]},{"t":"题画","f":"七言绝句","c":["赤壁矶头天欲曙，缟衣和梦掠舟西。","欲寻故处何由见，长恨今人画亦非。"]},{"t":"题月溪卷","f":"七言绝句","c":["月出东方白涨溪，溪翁行乐溪东西。","相思欲过隔溪去，南斗无光北斗低。"]},{"t":"赠周镐兄弟","f":"七言绝句","c":["周生两马齐两鞭，京指长安镐在山。","今夜尊前看秋月，明年秋月忆尊前。"]},{"t":"秋日 其一","f":"七言绝句","c":["山河一望仲秋前，枫叶初黄水半川。","路上行人不归去，北风吹尔过残年。"]},{"t":"秋日 其二","f":"七言绝句","c":["木犀未发奈莲空，小女来方剪綵工。","不信衰荣是天道，觅花无处怨西风。"]},{"t":"阅马氏均田文","f":"七言绝句","c":["王侯尚爱橐中装，何况田家弟与兄。","孟子未知人世事，独将仁义教齐梁。"]},{"t":"赠邓柏林其人貌似伍光宇 其一","f":"七言绝句","c":["南山面目偶然同，又向人间见此翁。","碧罗窗下一杯酒，犹胜良宵梦里逢。"]},{"t":"赠邓柏林其人貌似伍光宇 其二","f":"七言绝句","c":["此老若是石曼卿，此山便是芙蓉城。","高歌独控青骡去，是有风流万古情。"]},{"t":"喜雨","f":"七言绝句","c":["满眼珠玉不足珍，甘雨一洒万家春。","昨日苍头木洲至，又道木洲饥杀人。"]},{"t":"将如东莞闻途中盗发不果","f":"七言绝句","c":["扁舟东过扶胥口，一日二日之便风。","何故三旬不成往，仰船冈下贼旗红。"]},{"t":"题朴轩","f":"七言绝句","c":["葛洪亦号抱朴子，安知朴翁不是仙。","莫将甲子编年看，人道翁生大桡前。"]},{"t":"题应宪副真率卷","f":"七言绝句","c":["今古一杯真率酒，乾坤几个自由身。","春风回首黄岩会，醉插花枝少一人。"]},{"t":"茶园曲寄治香匮袁晖","f":"七言绝句","c":["峡东湾湾一水长，商船无日不苏杭。","千村万落无穷树，尽是袁郎匮里香。"]},{"t":"插花","f":"七言绝句","c":["岩前上马兴难拿，卯酒三钟帽半斜。","两鬓馨香齐插了，赛兰花间木犀花。"]},{"t":"访山家次韵 其一","f":"七言绝句","c":["樛枝径口郎迎马，语鸟篱前妾扫云。","笑杀主翁忙出户，手提筐果唤厨人。"]},{"t":"访山家次韵 其二","f":"七言绝句","c":["清泉煮蕨爱山家，夜饮西岩望月斜。","涧底白云留不住，半随红雨落天涯。"]},{"t":"萧黄门书来见责久无书用旧韵答之","f":"七言绝句","c":["谏官一字照天涯，南海年年问钓沙。","沧波不与黄门信，笑杀龙钟百姓家。"]},{"t":"平乡伯陈公以紫茄花绢为家慈寿诗以谢之","f":"七言绝句","c":["吴纨衫色紫茄花，老亲着时众口誇。","小儿奉酒歌七字，持献军门表拜嘉。"]},{"t":"景云偕范规海上割稻","f":"七言绝句","c":["犬子给炊海上舟，范生打浆两同游。","田中割稻家中望，逢著诸仙莫浪投。"]},{"t":"招讼者归","f":"七言绝句","c":["越王城里尘随马，刺史衙前吏喝人。","此日王孙不归去，旧游芳草可怜春。"]},{"t":"中秋期诸友不至","f":"七言绝句","c":["山妻有钱肯沽酒，诸友赋诗期不来。","范生也逐吾儿去，一夜清光对玉台。"]},{"t":"赠邝载道之淮阳别驾前御史谪黄岩","f":"七言绝句","c":["十年花县眼中人，别驾淮阳又几春。","曾共乌台高十仞，郑郎今著白纶巾。"]},{"t":"感事","f":"七言绝句","c":["齿本生来不著唇，呶呶众口剧鹅群。","鼻雷自炒元城耳，夜半钟声那得闻。"]},{"t":"木犀四绝寄倪麟 其一","f":"七言绝句","c":["正月山桃委地红，柳塘还捲落花风。","木犀一树浑堪赏，尽日相看烟雨中。"]},{"t":"木犀四绝寄倪麟 其二","f":"七言绝句","c":["风雨归来问小奴，药栏花架费人扶。","黄昏雨歇茅檐月，只有木犀对老夫。"]},{"t":"木犀四绝寄倪麟 其三","f":"七言绝句","c":["春城无日不思家，风雨经旬损物华。","竹色四时长不改，平安先报木犀花。"]},{"t":"木犀四绝寄倪麟 其四","f":"七言绝句","c":["风吹雨打只伤神，白首龙钟尚爱春。","花意未应嫌老丑，十年前是种花人。"]},{"t":"题两山居士卷","f":"七言绝句","c":["墨水翻腾作巨川，两山何处洒云烟。","醉中亦有临池兴，怅望名家不敢言。"]},{"t":"题东所卷","f":"七言绝句","c":["东所诗成月满衣，乾坤无语鬼神悲。","郎今欲到飞云去，说与两山居士知。"]},{"t":"问邝珙病","f":"七言绝句","c":["邝生病肺今何如，献岁初惊得手书。","我有丹方欲传与，小藜床上半跏趺。"]},{"t":"次韵陈冷庵佥宪见寄 其一","f":"七言绝句","c":["击壤声中酒国春，海风吹老石边身。","桃花几树衡门下，我是唐虞一辈民。"]},{"t":"次韵陈冷庵佥宪见寄 其二","f":"七言绝句","c":["乾坤画笔久荒芜，谁作临江五老图。","闻道远师将结社，华巅犹得照鄱湖。"]},{"t":"次韵陈冷庵佥宪见寄 其三","f":"七言绝句","c":["五十四年居海滨，偷将水月洗心尘。","今朝偶得西江使，溟海犹堪把赠人。"]},{"t":"别意","f":"七言绝句","c":["江阁醒眠秋正凉，西风残漏转离肠。","不知天道平分未，巳觉人间一夜长。"]},{"t":"悼林暕 其一","f":"七言绝句","c":["一日之雅亦为哀，钟淑相随入夜台。","此生未了男儿事，也向扶胥打坐来。"]},{"t":"悼林暕 其二","f":"七言绝句","c":["木犀开时江右李，士达刘希盂已去。","容贯范规江浦未，还因有独赏之叹。"]},{"t":"悼林暕 其三","f":"七言绝句","c":["岭北书生嗟去早，江东游子惜归迟。","重阳将近无风雨，正是木犀初发时。"]},{"t":"先子忌日作","f":"七言绝句","c":["生来只见山头土，祭讳惟闻月下螀。","五十四年天颇近，诸孙罗列拜成行。"]},{"t":"题画 其一","f":"七言绝句","c":["茅檐秋飐酒旗风，舟入蒹葭月半笼。","醉睡不知家远近，醒来依旧五湖东。"]},{"t":"题画 其二","f":"七言绝句","c":["寒山钟近不成眠，人在姑苏半夜船。","何处明朝正堪望，吴王宫苑草芊芊。"]},{"t":"题画 其三","f":"七言绝句","c":["金陵城西趁市郎，负戴不厌江路长。","百花桥头换美酒，归与渔父歌沧浪。"]},{"t":"古耶道中有怀","f":"七言绝句","c":["翠烟浮陇麦初齐，社树青青独鸟啼。","何处相思不相见，木棉花下水门西。"]},{"t":"小湘峡食嘉鱼","f":"七言绝句","c":["两山断处小湘峡，十月嘉鱼出水鲜。","引满阿侬生日酒，微吟空记属牛年。"]},{"t":"自三洲还至禄步村","f":"古风","c":["江流夹束午风桑，城郭归来禄步舟。","惆怅碧桃歌舞散，黄茅烟里一?辀。"]},{"t":"过清远峡","f":"七言绝句","c":["行人初上峡西头，已有心随下峡舟。","天下名山皆可爱，梦中慈母不来游。"]},{"t":"读鳄鱼文","f":"七言绝句","c":["刺史文章天下无，海中灵物识之乎。","如何皇甫兼逢吉，不及潮州一鳄鱼。"]},{"t":"食蚬","f":"七言绝句","c":["家住东南蚬子村，小铛风味胜侯门。","眼前下箸非无处，芹曝犹堪奉至尊。"]},{"t":"夜酌","f":"七言绝句","c":["侍子焚脂弄小孙，药炉分火暖残樽。","东风不管黄鹂怨，一夜飞红满树根。"]},{"t":"问李深之病","f":"七言绝句","c":["竹林花埭酒旗风，秋赏春游事事同。","伏枕六旬犹未起，相思红日满帘栊。"]},{"t":"沙上","f":"七言绝句","c":["村径西来入社松，北山终日白云封。","往来独把梅花笑，只有沙堆不负公。"]},{"t":"春寒 其一","f":"七言绝句","c":["清明天气如初腊，雨脚云头枉是春。","阶下荼蘼开自晚，不随红紫怨东君。"]},{"t":"春寒 其二","f":"七言绝句","c":["一春光景在花枝，三月殊非阴雨时。","只有木犀偏耐冷，小枝檐下对衰迟。"]},{"t":"春寒 其三","f":"七言绝句","c":["看花何处辗香轮，江上春寒著莫人。","衰病未堪供起倒，且便高枕过残春。"]},{"t":"题栖霞卷","f":"七言绝句","c":["红霞小坞地仙家，日出耶溪十里花。","秋竹垣低是何处，有人窗下读南华。"]},{"t":"杂兴","f":"七言绝句","c":["数行屋蚁下庭芜，墙角扶留绿映裾。","正是满楼山雨过，夕阳惟好鹁鸠呼。"]},{"t":"读朱晦庵注参同契","f":"七言绝句","c":["神仙不注参同契，火候工夫那得知。","千古晦庵拈一语，可怜无及魏君时。"]},{"t":"大水浮舟至七星岩顶题其上","f":"七言绝句","c":["七星岩下醉神仙，犹占龙床水底眠。","我有一樽延寿酒，月明今夜对南山。"]},{"t":"苍梧寄陈庸时馆浔州","f":"七言绝句","c":["山形西上水东流，独泛长江十日舟。","无翼可随飞鸟去，相思时复到浔州。"]},{"t":"题林良为朱都宪诚庵先生写林塘春晓图","f":"七言绝句","c":["烟飞水宿自成群，物性何尝不似人。","得意乾坤随上下，东风醉杀野塘春。"]},{"t":"出肇庆有怀马玄真","f":"七言绝句","c":["红尘白浪去来年，细雨秋江看木棉。","何处思君君不见，羚羊峡尾七星前。"]},{"t":"金州别陈冕","f":"七言绝句","c":["江上东风捲暮旗，木棉花下进舟迟。","金州未是穷途别，莫赠黄金只赠诗。"]},{"t":"漫兴","f":"七言绝句","c":["粉墙经雨旧成痕，青被扶留直到根。","俗吏款门教暂去，隔帘抛果戏诸孙。"]},{"t":"画鹰","f":"七言绝句","c":["落日平原散鸟群，西风爽气动秋旻。","江边老树身如铁，独立槎牙一欠伸。"]},{"t":"木犀枝上小鹊","f":"七言绝句","c":["翠裙白领眼中无，飞上木犀还一呼。","乾坤未可轻微物，自在天机我不如。"]},{"t":"赠周成","f":"七言绝句","c":["虚无里面昭昭应，影响前头步步迷。","说到鸢飞鱼跃处，绝无人力有天机。"]},{"t":"春中杂兴 其一","f":"七言绝句","c":["春寒著莫絮袍轻，游走何山更乞晴。","夜梦髯翁作人拜，安知不是白龙精。"]},{"t":"春中杂兴 其三","f":"七言绝句","c":["香烟袅入袖中蛇，读易山斋日未斜。","领取乾坤分付意，扶留生耳木犀花。"]},{"t":"端阳后一日里人送角黍酒至","f":"七言绝句","c":["荷瓢童子问谁家，老妇檐前驻纺车。","角黍唤回端午梦，还从艾盏得松花。"]},{"t":"九日木犀未开 其一","f":"七言绝句","c":["野径香沉舞蝶稀，柴门树老著花迟。","含章此日无穷意，只有阶前拄杖知。"]},{"t":"九日木犀未开 其二","f":"七言绝句","c":["菊来栗里何须酒，梅到孤山不欠诗。","老去未甘诗酒废，木犀其那放花迟。"]},{"t":"木犀花下待陈秉常","f":"七言绝句","c":["常疑楚客餐秋菊，不信唐人醉牡丹。","何处木犀香可爱，须君曾到玉台山。"]},{"t":"谢九江惠菊 其一","f":"七言绝句","c":["谁将此菊种江滨，物色当年漉酒巾。","若道渊明今我是，清香还属隔江人。"]},{"t":"谢九江惠菊 其二","f":"七言绝句","c":["紫菊移来紫水滨，白头对著白纶巾。","花前酌酒笑未足，酒后簪花笑杀人。"]},{"t":"谢九江惠菊 其三","f":"七言绝句","c":["故根迢递九江滨，岁晚相看此道巾。","不用诗流强分别，种花人是赏花人。"]},{"t":"谢九江惠菊 其四","f":"七言绝句","c":["鹤袖披翻野水滨，黄花簪破小乌巾。","腰间我有坡翁带，解与西邻卖酒人。"]},{"t":"夜梦见太母急呼诸孙前拜","f":"七言绝句","c":["欲觉未觉梦中梦，有形无形身外身。","喜逐悲来呼不得，曾孙前拜太夫人。"]},{"t":"马肇文惠油酒并录示哭一峰先生诗及送林缉熙掌教绝句复以香一束赋三绝见意 其一","f":"七言绝句","c":["谁以三年报一峰，舒刚盖有古人风。","一词亦到君亲地，何处无人覆马龙。"]},{"t":"马肇文惠油酒并录示哭一峰先生诗及送林缉熙掌教绝句复以香一束赋三绝见意 其二","f":"七言绝句","c":["清油浊酒慰家贫，老子山中但白云。","君欲看云须久坐，晴窗端为起炉熏。"]},{"t":"马肇文惠油酒并录示哭一峰先生诗及送林缉熙掌教绝句复以香一束赋三绝见意 其三","f":"七言绝句","c":["南川钓艇已横波，里水渔翁又放歌。","今日未知明日事，且倾君酒为君哦。"]},{"t":"赠周二仔入京","f":"七言绝句","c":["故人讶我久无书，只到长安梦亦疏。","万里周郎知此意，杖藜江上送长须。"]},{"t":"次韵张廷实东所寄兴见寄 其一","f":"七言绝句","c":["天边暝色将秋至，海上长风送月来。","何处无人识东所，夜分楼上了馀杯。"]},{"t":"次韵张廷实东所寄兴见寄 其二","f":"七言绝句","c":["明月清风放两头，一筇挑到古尼丘。","而今老去无筋力，独坐江槎看水流。"]},{"t":"次韵张廷实东所寄兴见寄 其三","f":"七言绝句","c":["扳缘千尺采松花，服食为仙未到家。","我得丹方欲传与，肯捐妻子入烟霞。"]},{"t":"次韵张廷实东所寄兴见寄 其四","f":"七言绝句","c":["路自飞云过阆壶，仙人迓我久趑趄。","相期汗漫归何处，独占烟波理钓鱼。"]},{"t":"次韵张廷实东所寄兴见寄 其五","f":"七言绝句","c":["放倒琼林半醉间，半留醒处著江山。","病来只有冠裳在，不带朱门一事还。"]},{"t":"次韵张廷实东所寄兴见寄 其六","f":"七言绝句","c":["不求老马在长途，谁道长安一马无。","伯乐未来忧蓟北，凭君传语到平湖。"]},{"t":"次韵张廷实东所寄兴见寄 其七","f":"七言绝句","c":["邯郸枕上看三台，谁撼藜床唤老来。","幽事不应全废却，夜来风吼涧中雷。"]},{"t":"次韵张廷实东所寄兴见寄 其八","f":"七言绝句","c":["西风吹老木兰花，水阁氛氲带晚霞。","溪上行人不相识，隔船对语问谁家。"]},{"t":"次韵张廷实东所寄兴见寄 其九","f":"七言绝句","c":["海上峰峦今属谁，携来四百布囊垂。","或嫌珠佩多遗恨，化作长髯未可知。"]},{"t":"次韵张廷实东所寄兴见寄 其十","f":"七言绝句","c":["门下诸生无一个，山童撤却皋皮坐。","与侬七尺青团蒲，今年换与张东所。"]},{"t":"沽酒","f":"七言绝句","c":["酒店无钱与酒迟，初晴天气菊残时。","乾坤不放閒人醉，也到江门酒盏知。"]},{"t":"题南浦送别图为蒋方伯","f":"七言绝句","c":["何人更卖云卿屦，我昔曾过孺子亭。","欲写别离非此日，西山南浦认丹青。"]},{"t":"对菊 其一","f":"七言绝句","c":["花开无酒醉江滨，莫笑人间破葛巾。","庐阜长官归未得，看花还共去年人。"]},{"t":"对菊 其二","f":"七言绝句","c":["餐香谁亦到湘滨，西崦东篱滥一巾。","去岁金英曾照我，今年玉蕊又惊人。"]},{"t":"对菊 其三","f":"七言绝句","c":["白雁南飞到海滨，吟边芳气袭衣巾。","门通水竹三丫路，坐对求羊一辈人。"]},{"t":"对菊 其四","f":"七言绝句","c":["秋英如雪照江滨，扳折须防小侍巾。","曲槛两头门尽掩，先生元是惜花人。"]},{"t":"对菊 其五","f":"七言绝句","c":["日日狂歌菊涧滨，花神应识玉台巾。","西风为扫繁华去，不遣红芳近老人。"]},{"t":"对菊 其六","f":"七言绝句","c":["花舫谁撑绿渚滨，道人醉脱碧方巾。","东篱不饮江州酒，彭泽当年未尽人。"]},{"t":"对菊 其七","f":"七言绝句","c":["精魄当归楚水滨，天涯闻讣忽沾巾。","西风吹醒蒲团梦，独对黄花忆故人。"]},{"t":"对菊 其八","f":"七言绝句","c":["扁舟何处剡溪滨，夜半归来雪满巾。","争似一瓢秋菊伴，漆园风暖蝶疑人。"]},{"t":"对菊 其九","f":"七言绝句","c":["我貌不如苏颍滨，秋风华发已盈巾。","有钱不买重阳醉，篱下黄花也笑人。"]},{"t":"对菊 其十","f":"七言绝句","c":["菊坡持酒越江滨，御笔亲题与醉巾。","丞相九回徵不起，碧虚长揖梦中人。"]},{"t":"对菊 其十一","f":"七言绝句","c":["知章投老鉴湖滨，还戴华阳羽士巾。","元亮也归三径去，至今人笑是痴人。"]},{"t":"对菊 其十二","f":"七言绝句","c":["陶家园里旧开丛，复入山窗对此翁。","一曲一杯花下醉，人生能得几回逢。"]},{"t":"种扶留用旧韵 其一","f":"七言绝句","c":["轻落藤梢浅打沟，种时须共小迟留。","浮生日月供眠外，付与携锄抱瓮休。"]},{"t":"种扶留用旧韵 其二","f":"七言绝句","c":["絜矩工夫但一沟，山中夜雨长扶留。","莫教看到诗人眼，千首鸢鱼也未休。"]},{"t":"漫兴","f":"七言绝句","c":["娉婷郑女著纤罗，能为襄王激楚歌。","一曲霓裳都扫尽，尊前无地舞阳阿。"]},{"t":"赠麦岐出游 其一","f":"七言绝句","c":["错教人意向花浓，万树香飘一夜风。","行过东津莫回首，一番春事又成空。"]},{"t":"赠麦岐出游 其二","f":"七言绝句","c":["我得无言赠麦岐，乾坤游走到何时。","千山万水无穷意，分付芙蓉杖一枝。"]},{"t":"八月八夜忽梦玉宇无瑕碧云灿烂南斗下大书八字云生生生德俊逸超全下有四人面西而行或隐或见觉后纪以绝句","f":"七言绝句","c":["八字光腾斗外天，碧云西去拥群仙。","乾坤此梦无人话，起步中庭月上弦。"]},{"t":"赠人","f":"七言绝句","c":["谁将儿女浪干情，春雨来时草又生。","梦亦是真真亦梦，石泉槐火对清明。"]},{"t":"悼周镐 其一","f":"七言绝句","c":["一封长夏寄京书，不遣归来待拜除。","谁与行人报消息，高堂今日要人扶。"]},{"t":"悼周镐 其二","f":"七言绝句","c":["一双玉树出东溟，岂意先随晓露倾。","三十六年惟一女，老夫垂泪写铭旌。"]},{"t":"悼周镐 其三","f":"七言绝句","c":["叔子还家定买碑，墓旁将刻老夫诗。","诗中不借閒言语，只写人间母子悲。"]},{"t":"悼周镐 其四","f":"七言绝句","c":["嗜好平生法帖诗，偶逢方士问刀圭。","何人摆脱浮生事，得似周郎易箦时。"]},{"t":"望白龙池 其一","f":"七言绝句","c":["西望不见昆崙池，白龙上天归何时。","望中心逐飞云去，半挂玉台松树枝。"]},{"t":"望白龙池 其二","f":"七言绝句","c":["涵虚数尺镜光悬，旧是头陀洗钵泉。","又有山人来洗耳，白龙休占水中眠。"]},{"t":"望白龙池 其三","f":"七言绝句","c":["云影天光共一池，池中消长白龙知。","仙翁骑龙上天去，只有明月照涟漪。"]},{"t":"梅花 其一","f":"七言绝句","c":["一枝低压坞篱斜，细路穿云竹半遮。","忽被暗香相引去，小塘诗景在西家。"]},{"t":"梅花 其二","f":"七言绝句","c":["老树眠江水齧之，茫茫水月浸花枝。","暗香捲入沧溟去，不是渔翁那得知。"]},{"t":"梅花 其三","f":"七言绝句","c":["沙笼寒月树笼烟，香彻龙溪水底天。","斜隔竹林窥未得，更寻西路上渔船。"]},{"t":"梅花 其四","f":"七言绝句","c":["南枝照水忽先开，渔父湾头有钓台。","罢钓归来溪路暝，暗香几度倩风媒。"]},{"t":"梅花 其五","f":"七言绝句","c":["孤山山下一枝梅，春到南枝尚未开。","酒醒西楼看月坐，清风湖上捲香来。"]},{"t":"梅花 其六","f":"七言绝句","c":["朝来溪上弄花丸，天地氤氲日月还。","无觅暗香疏影处，笑呼欧九问孤山。"]},{"t":"梅花 其七","f":"七言绝句","c":["梅花撩我又冬残，落日深山一凭阑。","病眼不知花妙处，只将花作野人看。"]},{"t":"梅花 其八","f":"七言绝句","c":["梅花如雪拥溪扉，渔父村南负酒归。","纵饮不知花落去，酒醒船上见花稀。"]},{"t":"梅花 其九","f":"七言绝句","c":["日日花边唤酒船，梅花开处酒家眠。","青山一片无人买，谁与先生办酒钱。"]},{"t":"梅花 其十","f":"七言绝句","c":["樵客入林闻曙鸦，梅梢残月暗溪沙。","沿溪路尽无人到，更说林逋住处赊。"]},{"t":"梅花 其十一","f":"七言绝句","c":["舍南朝见一枝梅，舍北桃花昨夜开。","笑问花开何太急，青春肯逐酒钱来。"]},{"t":"梅花 其十二","f":"七言绝句","c":["南北枝头月正悬，月中谁此弄溪船。","晚来吹入梅花去，吹到林逋木榻边。"]},{"t":"梅花 其十三","f":"七言绝句","c":["苍烟袅树溪冥冥，夜半江楼笛一声。","怅望错疑溪女折，满头只惯插金樱。"]},{"t":"桃花 其二","f":"七言绝句","c":["山中儿女不知秦，无赖渔郎最恼人。","溪上桃花君莫种，东风不贷武陵津。"]},{"t":"题袁氏知归卷 其一","f":"七言绝句","c":["鸟在苍岑鱼在渊，水深林密保生全。","秋风莫怨茅茨破，白首眠看榻顶天。"]},{"t":"题袁氏知归卷 其二","f":"七言绝句","c":["阴厓水必到沧溟，石罅涓涓势已成。","万古乾坤流不尽，望湖亭下更分明。"]},{"t":"题袁氏知归卷 其三","f":"七言绝句","c":["示我阴阳阖辟机，舂陵墨雨洒门扉。","直从罔象前头见，人与乾坤一处归。"]},{"t":"界江八景 其一 河桥柳色","f":"七言绝句","c":["庐阜清风长官宅，渭城朝雨王维诗。","束西绿遍河桥路，长与离人照酒卮。"]},{"t":"界江八景 其二 驿馆槐阴","f":"七言绝句","c":["槐阴覆庭日早午，小吏夜出迎当路。","长江阅尽往来人，淦水西边此槐树。"]},{"t":"界江八景 其三 芦渚晴烟","f":"七言绝句","c":["香芦紫烟生一缕，天风吹落芦花渚。","江东行客归去来，沾衣犹带金陵雨。"]},{"t":"界江八景 其四 古阜渔灯","f":"七言绝句","c":["埠头半点夜燃枯，钓得淞江一尾鲈。","渔父联舟向东岸，东岸人家有酒沽。"]},{"t":"界江八景 其五 界江霁月","f":"七言绝句","c":["玉宇蟾辉秋展鉴，界江水色夜磨铜。","乾坤好景谁无分，只问灵台得属公。"]},{"t":"界江八景 其六 西僧禅梵","f":"七言绝句","c":["竹径风传西梵声，隔墙深夜有人听。","山僧老去无功德，还倚禅门诵佛经。"]},{"t":"界江八景 其七 东阁书声","f":"七言绝句","c":["闭户书声午欲乾，夜阑灯烬落蒲团。","朝廷若问观风使，犹有书郎信长官。"]},{"t":"界江八景 其八 大桥牧笛","f":"七言绝句","c":["山花争插满头红，芦叶乌乌弄晚风。","桥大板平牛步稳，老牛差后不愁侬。"]},{"t":"读周朱二先生年谱 其一","f":"七言绝句","c":["千年几见南康守，叹息人间两谱开。","但使乾坤留一绪，圣贤去后圣贤来。"]},{"t":"读周朱二先生年谱 其二","f":"七言绝句","c":["一语不遗无极老，千言无倦考亭翁。","语道则同门路别，君从何处觅高踪。"]},{"t":"白洋潭鱼 其一","f":"七言绝句","c":["白洋风起钓丝飞，梦里渔蓑此夜归。","明日冷香桥上望，海鸥相对便忘机。"]},{"t":"白洋潭鱼 其二","f":"七言绝句","c":["白洋潭上浩烟波，何处渔归此放歌。","月下闻之开口笑，江门三尺有藤蓑。"]},{"t":"读定山集","f":"七言绝句","c":["千首莺花万蠹鱼，眼昏心乱意何如。","白头许我编摩不，活水源头洗砚书。"]},{"t":"寄张主事","f":"七言绝句","c":["从来妙处不传书，十梦人间久不如。","试问十洲三岛外，白云谁伴老仙居。"]},{"t":"赠邹汝愚吏目时馆壮哉亭","f":"七言绝句","c":["川云岳雨天模糊，万里山亭此客孤。","又借南风吹一月，酒葫芦打药葫芦。"]},{"t":"题伍氏双喜图","f":"七言绝句","c":["莫怪龙钟此葛巾，穿花入竹去频频。","秋风酒熟南山下，更与殷勤报主人。"]},{"t":"戊子秋开化吴廷介县博校文于我省念太夫人初度之辰在十月八日撤棘之后幸公程之便趋归为寿诗以送之","f":"七言绝句","c":["高下原从脚板分，江山富贵几般人。","吾家子弟官情薄，欲把行藏寿老亲。"]},{"t":"题伍光宇碑阴","f":"七言绝句","c":["几年沧海一碑成，身后何须叹不平。","天遣老兄生少子，千秋寒食祭公茔。"]},{"t":"喜黄在登科 其一","f":"七言绝句","c":["半醒半醉一儒巾，黄卷青灯二十春。","晚醉鹿鸣君莫讶，龙头还属老成人。"]},{"t":"喜黄在登科 其二","f":"七言绝句","c":["龙头还属老成人，夜半雷声己变春。","莫为晨昏留不去，安车扶上白头亲。"]},{"t":"喜黄在登科 其三","f":"七言绝句","c":["安车扶上白头亲，徐积当年也为贫。","忆昨扁舟淮上路，青山吾拜墓中人。"]},{"t":"题松雪图","f":"七言绝句","c":["元时有个赵松雪，松雪于今又属谁。","一幅丹青一瓢酒，廖公来乞老夫诗。"]},{"t":"半江十咏为谢德明赋 其一","f":"七言绝句","c":["江湖城市气交吞，谁放兰舟系柳根。","肯与渔翁通水界，白头破浪在江门。"]},{"t":"半江十咏为谢德明赋 其二","f":"七言绝句","c":["独速溪边舞短蓑，月明醉影共婆娑。","手中握得桐江线，钓破江天不要多。"]},{"t":"半江十咏为谢德明赋 其三","f":"七言绝句","c":["水面烟浓白鸟低，数峰青锁夕阳西。","隔波莫是仙源否，恰到波心路已迷。"]},{"t":"半江十咏为谢德明赋 其四","f":"七言绝句","c":["隔波晴色袅孤烟，万树桃花锦一川。","夜半天风吹海立，探花人在半江船。"]},{"t":"半江十咏为谢德明赋 其五","f":"七言绝句","c":["水到江心五百弓，白鸥双起雁孤冲。","竹篙点碎菰蒲月，如此风光我共公。"]},{"t":"半江十咏为谢德明赋 其六","f":"七言绝句","c":["画纸敲针一杜诗，水生花落两天机。","西风捲市尘高起，也到江心不解飞。"]},{"t":"半江十咏为谢德明赋 其七","f":"七言绝句","c":["溪槎汎汎月中眠，横占波间一半天。","何许少年三五辈，夜深邻舫叫摊钱。"]},{"t":"半江十咏为谢德明赋 其八","f":"七言绝句","c":["碧海云深鹤梦劳，人间无地著卢敖。","不知居士曾来否，试向波心问小舠。"]},{"t":"半江十咏为谢德明赋 其九","f":"七言绝句","c":["醉则高歌醒复悲，老仙那有独醒时。","江间波浪三千顷，都与回公入酒卮。"]},{"t":"半江十咏为谢德明赋 其十","f":"七言绝句","c":["半江秋水映斜阳，几个神仙坐水旁。","酒是逡巡花顷刻，一尊韩愈对韩湘。"]},{"t":"经陈氏家庙","f":"七言绝句","c":["牡蛎墙高一庙深，缘冈松柏昼阴阴。","我家俎豆茅茨下，只少黄金不少心。"]},{"t":"题万松庵壁","f":"七言绝句","c":["昔年曾赋万松轩，一饭松根有俗缘。","旋摘黄花傅白酒，真成东老对回仙。"]},{"t":"过东涌","f":"七言绝句","c":["乡曲论交大父馀，耳根狼籍病翁书。","小儿莫道无灵性，也傍寒塘望笋舆。"]},{"t":"经曝日台","f":"七言绝句","c":["何处猿声更断肠，夜闻孤女哭凄凉。","泪痕滴著台旁树，纵到春风亦少芳。"]},{"t":"寄袁晖林敬 其一","f":"七言绝句","c":["颇忆江湖林子翼，小斋留饭更袁晖。","人心人面人人异，贤辈如前共饭时。"]},{"t":"寄袁晖林敬 其二","f":"七言绝句","c":["南州香匮久流传，亦卖东湖草屦钱。","莫共诸贤理铅椠，只治香匮过年年。"]},{"t":"寄袁晖林敬 其三","f":"七言绝句","c":["岁首诗缄寄草梅，路傍先倩秉之开。","而今两眼西风泪，谁解传声到夜台。"]},{"t":"寄袁晖林敬 其四","f":"七言绝句","c":["若道鸱夷解了心，五湖何用更千金。","鲁连长揖平原去，风月无边碧海深。"]},{"t":"林缉熙县博张廷实进士何孝子子完先后见访既而缉熙往平湖廷实归五羊子完还博罗因赋四绝 其二","f":"七言绝句","c":["昨夜江门把春酒，满船明月唱阳关。","五羊城中消息断，君去东吴几日还。"]},{"t":"林缉熙县博张廷实进士何孝子子完先后见访既而缉熙往平湖廷实归五羊子完还博罗因赋四绝 其三","f":"七言绝句","c":["四百峰头白鹤知，老夫八月有幽期。","尔家正在罗浮下，莫向春风怨别离。"]},{"t":"林缉熙县博张廷实进士何孝子子完先后见访既而缉熙往平湖廷实归五羊子完还博罗因赋四绝 其四","f":"七言绝句","c":["长髯遗我一囊山，铁桥流水非人间。","我今决策山中去，踏断铁桥无路还。"]},{"t":"梦游天台","f":"七言绝句","c":["路入天台第八重，洞门刚与赤城通。","脚根点到虹桥下，一笑那知是梦中。"]},{"t":"伍伯饶送蜂窼至用韵答之 其一","f":"七言绝句","c":["独怜溪竹隐花丛，待得南山后到蜂。","昔日往来南谷口，如今只用一丸封。"]},{"t":"伍伯饶送蜂窼至用韵答之 其二","f":"七言绝句","c":["晚蜂队队过山房，何处归来嘴脚香。","辛苦奉君臣子分，可堪奴辈日偷尝。"]},{"t":"赛兰花开 其一","f":"七言绝句","c":["晴光三日转花枝，坐对微馨忽有诗。","涓滴未尝花上露，南风莫只报人知。"]},{"t":"赛兰花开 其二","f":"七言绝句","c":["曲栏砌下少人窥，戏蝶游蜂忽满枝。","君欲寻花须早计，只今犹是未开时。"]},{"t":"赛兰花开 其三","f":"七言绝句","c":["微风巾袂细氤氲，楚畹丛中别有春。","啜茗亦嫌风景杀，明朝载酒是何人。"]},{"t":"赛兰花开 其四","f":"七言绝句","c":["山花艳艳缀旒傍，君爱深红爱浅黄。","楚客见之挥不去，向人说是赛兰香。"]},{"t":"次韵南山送蜜 其一","f":"七言绝句","c":["万古西山朽骨丛，中有魂魄化为蜂。","饿死空窼不飞去，犹为君王守故封。"]},{"t":"次韵南山送蜜 其二","f":"七言绝句","c":["寒花索寞不成丛，口腹吾惭入腊蜂。","觅蜜娇儿啼夜半，未成新酿又开封。"]},{"t":"次韵南山送蜜 其三","f":"七言绝句","c":["知从何处宿花丛，清晓飞来又几蜂。","定有香魂招不返，远寻芳气落花封。"]},{"t":"次韵南山送蜜 其四","f":"七言绝句","c":["处处山花好蜜房，絪缊岩壑为谁香。","相思道远无由寄，此味年来只独尝。"]},{"t":"戏赠馆宾","f":"七言绝句","c":["松风和雨洒柴关，过午雕胡饭始餐。","今日华卿休怪讶，往年饥鼠齧陈山。"]},{"t":"读林进士信宜祭母墓文 其一","f":"七言绝句","c":["泪血今朝洒凤山，凤山元只在人间。","非关旅殡无寻处，不与皇华共载还。"]},{"t":"读林进士信宜祭母墓文 其二","f":"七言绝句","c":["天涯四尺不封坟，一去凤山三十春。","莫辞更向山前问，恐有渔樵是异人。"]},{"t":"袁侍御道龙川讣至 其一","f":"七言绝句","c":["何处龙川去不归，山南山北雨云飞。","晚风晴捲三千尺，好与歌筵作舞衣。"]},{"t":"袁侍御道龙川讣至 其二","f":"七言绝句","c":["忆昔青阳动海滨，隔年草木预知春。","如今行路无颜色，尽是青阳去后人。"]},{"t":"次韵柳渡头答乡友 其一","f":"七言绝句","c":["溪南溪北荔枝垂，五月荷花欲捲旗。","忽有酒船邀半路，三杯不记主人谁。"]},{"t":"题林进士廷玉继母陈氏挽卷","f":"七言绝句","c":["与儿酱姜儿勿号，前母生之后母劳。","大统冈头寒食酒，一杯和泪洒香茅。"]},{"t":"五月菊 其一","f":"七言绝句","c":["露饮霜餐不记秋，黄花三昧室中求。","区区形色多相似，争得先生为点头。"]},{"t":"五月菊 其二","f":"七言绝句","c":["小变春红作淡妆，山亭初见一枝黄。","醉中忽眩东篱眼，起视金钱著屐忙。"]},{"t":"五月菊 其三","f":"七言绝句","c":["二顷南风秫正青，督邮未到长官亭。","眼前虽有黄花在，不与陶公解醉醒。"]},{"t":"题梁景行天壶书屋 其一","f":"七言绝句","c":["打土编茅费几钱，白云深夜一灯悬。","知君未是壶山主，只借壶山过两年。"]},{"t":"题梁景行天壶书屋 其二","f":"七言绝句","c":["齑粥朝朝长白寺，衣冠夜夜百原山。","三年枕席何曾设，一纸家书亦不看。"]},{"t":"正月菊 其一","f":"七言绝句","c":["春到东篱花亦知，红桃白李更当时。","东风自领芳菲去，也为秋香作意吹。"]},{"t":"正月菊 其二","f":"七言绝句","c":["庐阜高歌九日杯，尽将秋意放花开。","谁教也向东风里，点破千红万紫堆。"]},{"t":"次韵吴县博别后见寄 其一","f":"七言绝句","c":["圣贤生处是中华，何处天涯何处家。","夫君认得幽栖处，江门月底钓鱼槎。"]},{"t":"次韵吴县博别后见寄 其二","f":"七言绝句","c":["昨夜江门咏月归，今朝又领衡山诗。","千仞冈头一振衣，乃见庐冈点化机。"]},{"t":"题一峰遗墨后","f":"七言绝句","c":["穆穆熙熙在眼中，君家卷里忽相逢。","苍烟绿树湖西路，何处金牛吊一峰。"]},{"t":"何生告还新喻因忆希仁先生平生故人不相见十有六年怅然有作附生它日见之为我道之","f":"七言绝句","c":["忽忽人间十六年，与公信息两茫然。","不知今日江门路，还到湖西是几千。"]},{"t":"渊明爱菊","f":"七言绝句","c":["白衣刚到黄花下，醒长官为醉长官。","社里新知僧酒主，门前高枕石蒲团。"]},{"t":"和靖爱梅","f":"七言绝句","c":["懊恼梅花未有诗，孤山马上又攒眉。","后人拈出前人句，作者元来自不知。"]},{"t":"茂叔爱莲","f":"七言绝句","c":["不枝不蔓体本具，外直中通用乃神。","我即莲花花即我，如公方是爱莲人。"]},{"t":"潘岳爱桃","f":"七言绝句","c":["潘郎本自爱桃花，种向河阳几万家。","世有长官如孟子，还除花地付桑麻。"]},{"t":"废宅逢梅","f":"七言绝句","c":["花间无主竹篱空，小径斜穿曲巷通。","赖是暗香能不息，短筇破帽得相逢。"]},{"t":"与客夜饮","f":"七言绝句","c":["击节歌声未出门，照书灯火已眠尊。","老妻唤醒蒲团梦，更与殷勤煮菜根。"]},{"t":"辞徵文者","f":"七言绝句","c":["平生语默鬼神知，破戒随人老可媸。","三日裹粮无此客，手携空卷下阶迟。"]},{"t":"崔潜送菊坡先生遗像至适乡人送紫菊一株遂以答之","f":"七言绝句","c":["高风千古镇浮华，儗酌寒泉荐菊花。","江上一株红带雨，丹青同日到山家。"]},{"t":"舫子","f":"七言绝句","c":["此身天地一虚舟，何处江山不自由。","六十一来南海上，买船吹笛共儿谋。"]},{"t":"木犀 其一","f":"七言绝句","c":["晓枕东窗睡不来，木犀造次隔篱开。","阿田拍手黄鹂到，写尽春风得意杯。"]},{"t":"木犀 其二","f":"七言绝句","c":["东风披拂满林塘，脚债东山也未偿。","扪虱不禁春意动，日华初吐木犀香。"]},{"t":"木犀 其三","f":"七言绝句","c":["茗碗朝朝怕侍儿，采花莫采称心枝。","床敷爱就东窗暖，分付东风敌面吹。"]},{"t":"木犀 其四","f":"七言绝句","c":["人间花草斗春肥，粉蝶黄莺接翅飞。","也爱白头肝肺好，木犀墙下咽朝晖。"]},{"t":"木犀 其五","f":"七言绝句","c":["名花得见太平年，击壤声高压管弦。","化日熙熙春荡荡，华夷何处不同天。"]},{"t":"木犀 其六","f":"七言绝句","c":["白头无酒不成狂，典尽春衫醉一场。","只许木犀知此意，晚风更为尽情香。"]},{"t":"书易隐求铭旌后感而有作 其一","f":"七言绝句","c":["一题八字八低回，满眼凄凉笔下来。","春社去年人不见，茅檐燕子又飞来。"]},{"t":"书易隐求铭旌后感而有作 其二","f":"七言绝句","c":["山林交分晚相投，诗在寒江紫菊舟。","君去落英还对我，独吟春雨看江流。"]},{"t":"书易隐求铭旌后感而有作 其三","f":"七言绝句","c":["半雨半晴莺乱啼，溪边丈人还杖藜。","不见旧时游走伴，白头冲雨更冲泥。"]},{"t":"移海棠花","f":"七言绝句","c":["小朵轻红带雨香，柔条深翠引风长。","道人不是看花客，肯把墙隈借海棠。"]},{"t":"晓饮忽醉拥禅衣坐睡","f":"七言绝句","c":["三杯过卯得瞢腾，坐拥禅衣问杀更。","下砌握刀山竹冗，开门负水海棠生。"]},{"t":"弄笔 其一","f":"七言绝句","c":["白日一醒尘土梦，青山谁计髑髅春。","时当可出宁须我，道不虚行只在人。"]},{"t":"弄笔 其二","f":"七言绝句","c":["弄水忘归真洒脱，看山扶步小逡巡。","等閒未许丹青手，搭飒平生画此中。"]},{"t":"鸲鹆育雏于贞节堂东壁壁高且危二雏堕地下乃就而哺之悲鸣徬徨如在无人之境予怜之取雏纳之巢纪以是作 其二","f":"七言绝句","c":["海鸥来往未忘机，鸲鹆能言掠砌飞。","母去巢危雏落尽，衔虫巢畔待雏归。"]},{"t":"江上","f":"七言绝句","c":["迟迟春日满花枝，江上群儿弄影时。","渔翁睡足船头坐，笑卷圆荷当酒卮。"]},{"t":"有怀故友张兼素 其一","f":"七言绝句","c":["穆穆熙熙只此风，今人未见古谁同。","意中我了牛医子，且放山斋水墨中。"]},{"t":"有怀故友张兼素 其二","f":"七言绝句","c":["长安风雨闭门间，陌上浮云没马鞍。","从此江西人勿论，夫君高只比庐山。"]},{"t":"有怀故友张兼素 其三","f":"七言绝句","c":["万里长安看我病，夜阑两马出携灯。","如今只有西涯在，宿草江边露满茔。"]},{"t":"何宇新赴南京，来白沙告别云：此行且复见定山，时秋已尽矣，以诗送之 其一","f":"七言绝句","c":["孝子已为人所称，世间留者乃何情。","故乡莫作多时别，阿母坟头草又生。"]},{"t":"何宇新赴南京，来白沙告别云：此行且复见定山，时秋已尽矣，以诗送之 其二","f":"七言绝句","c":["浦口柴扉几日开，江门烟艇暮秋回。","交情亦似长江水，南北年年送往来。"]},{"t":"阅光宇传","f":"七言绝句","c":["君艇君斋古所呼，忘年忘病舜之徒。","莫言外史无凭据，曾见当时拉背奴。"]},{"t":"戏题顾进士琼林宴图","f":"七言绝句","c":["黄屋门前缓辔行，上林花映赐衣明。","怪来老眼模糊甚，道是寻春杜少陵。"]},{"t":"梅花 其一","f":"七言绝句","c":["湖上诗仙骨已尘，江门半树复撩人。","携田拉畹朝朝去，江上田家秫酒新。"]},{"t":"梅花 其二","f":"七言绝句","c":["云隔溪扉水隔尘，梅花留月月留人。","江门半醉踏歌去，纱帽笼头白发新。"]},{"t":"梅花 其三","f":"七言绝句","c":["春风处处马蹄尘，岸北花神冷笑人。","二十四番红紫醉，一番零落一番新。"]},{"t":"梅花 其四","f":"七言绝句","c":["马蹄懒踏六街尘，閒忆当年拄颊人。","江海衣冠零落尽，梅花还对白头新。"]},{"t":"梅花 其五","f":"七言绝句","c":["精神交月不交尘，看到黄昏故可人。","拈出孤山难状处，一年诗债又从新。"]},{"t":"梅花 其六","f":"七言绝句","c":["桃李安能踵后尘，玉妃全是耐寒人。","瘦筇拄破梅村月，要看南枝出格新。"]},{"t":"梅花 其七","f":"七言绝句","c":["梅坞风高不起尘，短筇聊立探花人。","山塘水浅时窥影，喜与年光不斗新。"]},{"t":"梅花 其八","f":"七言绝句","c":["风递微香洗渴尘，独行山路不逢人。","梅花岁岁还依旧，只看何人著句新。"]},{"t":"梅花 其九","f":"七言绝句","c":["诗思梅花两绝尘，破窗残月夜窥人。","明朝走马东西去，壁上空留醉墨新。"]},{"t":"梅花 其十","f":"七言绝句","c":["雪崖江畔杳香尘，天与孤高远俗人。","不忘沧波别时意，一枝还遣到图新。"]},{"t":"次韵廷实进士送伦长官出游","f":"七言绝句","c":["我梦名山为点头，名山到处是真游。","床头买酒黄金尽，那向长江更买舟。"]},{"t":"麦秀夫于城南小渚中累土结茅居之容一之马伯干取酒共醉桃花下各赋诗为乐秀夫谒余同作附其韵 其一","f":"七言绝句","c":["春江淡荡桃花浔，绝岸回风落醉金。","一路潺湲烟锁断，无人知道此溪深。"]},{"t":"麦秀夫于城南小渚中累土结茅居之容一之马伯干取酒共醉桃花下各赋诗为乐秀夫谒余同作附其韵 其二","f":"七言绝句","c":["川练萦纡岛上花，世间遥望出城霞。","仙源不比函关路，老子来时坐一槎。"]},{"t":"麦秀夫于城南小渚中累土结茅居之容一之马伯干取酒共醉桃花下各赋诗为乐秀夫谒余同作附其韵 其三","f":"七言绝句","c":["我梦桃花何处浔，水清蘋白一篱金。","美人家住红云岛，欲往从之江水深。"]},{"t":"麦秀夫于城南小渚中累土结茅居之容一之马伯干取酒共醉桃花下各赋诗为乐秀夫谒余同作附其韵 其四","f":"七言绝句","c":["手拄藤枝鬓插花，夜收沆瀣晓餐霞。","贵人已隔门前水，野老还通月下槎。"]},{"t":"麦秀夫于城南小渚中累土结茅居之容一之马伯干取酒共醉桃花下各赋诗为乐秀夫谒余同作附其韵 其五","f":"七言绝句","c":["红白花开绿渚浔，风光买我不论金。","辋川不借閒人看，只爱诗家著语深。"]},{"t":"麦秀夫于城南小渚中累土结茅居之容一之马伯干取酒共醉桃花下各赋诗为乐秀夫谒余同作附其韵 其六","f":"七言绝句","c":["漠漠春烟淡淡花，竹边孤屿阁飞霞。","春江水满秋江水，更著新槎换旧槎。"]},{"t":"麦秀夫于城南小渚中累土结茅居之容一之马伯干取酒共醉桃花下各赋诗为乐秀夫谒余同作附其韵 其七","f":"七言绝句","c":["安期只在海东浔，何处名山浪铸金。","欲向桃花问消息，柴门深锁碧溪深。"]},{"t":"麦秀夫于城南小渚中累土结茅居之容一之马伯干取酒共醉桃花下各赋诗为乐秀夫谒余同作附其韵 其八","f":"七言绝句","c":["武陵春尽水流花，洗却耶溪十丈霞。","昼坐竹根看未足，满蓑明月夜萦槎。"]},{"t":"麦秀夫于城南小渚中累土结茅居之容一之马伯干取酒共醉桃花下各赋诗为乐秀夫谒余同作附其韵 其九","f":"七言绝句","c":["东浔披卷尽西浔，海水秋连万顷金。","卷里我能题百首，溪蓬斟酒莫辞深。"]},{"t":"麦秀夫于城南小渚中累土结茅居之容一之马伯干取酒共醉桃花下各赋诗为乐秀夫谒余同作附其韵 其十","f":"七言绝句","c":["闭门春雨可怜花，谁共花前倾紫霞。","但放此杯深似海，回公肚里得横槎。"]},{"t":"得伦长官诗疑其果于游而未可以游次韵复之 其一","f":"七言绝句","c":["一百青钱解杖头，樽中有酒胜閒游。","门前春浪高于屋，莫向长江弄破舟。"]},{"t":"得伦长官诗疑其果于游而未可以游次韵复之 其二","f":"七言绝句","c":["短檠细字写蝇头，衰老而今尚好游。","何处与君谈半偈，玉台留作济人舟。"]},{"t":"赠张进士入京 其一","f":"七言绝句","c":["五年不出独何心，万里行囊又一琴。","难写别离今日意，江门春水不如深。"]},{"t":"赠张进士入京 其二","f":"七言绝句","c":["有心谁莫弄儿嬉，孔老枝条我亦知。","风日小塘君不顾，竹林藤簟自皇羲。"]},{"t":"赠张进士入京 其三","f":"七言绝句","c":["能将糟粕委诸书，影响人间不受驱。","五百年中名世出，先王政教果何如。"]},{"t":"赠张进士入京 其四","f":"七言绝句","c":["津头日暮送夫君，别意那堪更遣闻。","芳树鸟啼山雨过，柴门空闭一溪云。"]},{"t":"赠张进士入京 其五","f":"七言绝句","c":["玉台居士玉台眠，碧海三山病枕前。","君欲有为休问我，白头世事已茫然。"]},{"t":"赠张进士入京 其六","f":"七言绝句","c":["会馀汤饼欲春阑，往即公程亦不难。","不独有官兼有子，老亲嬴得一开颜。"]},{"t":"赠张进士入京 其七","f":"七言绝句","c":["南风吹上石门舟，又到西华寺里游。","记得联舟此相送，而今空有雪盈头。"]},{"t":"赠张进士入京 其八","f":"七言绝句","c":["昔曾寄住长安寺，潦倒沧溟梦不回。","何处思君还有梦，青山斜日两徘徊。"]},{"t":"次韵东所送姜酒 其一","f":"七言绝句","c":["宁知生蚤与生迟，真凤真麟出以时。","何处氤氲姜酒气，香风吹入野人卮。"]},{"t":"次韵东所送姜酒 其二","f":"七言绝句","c":["病起朝天果未迟，出门刚遇凤来时。","两山居士何如喜，一饮从教累百卮。"]},{"t":"与廷实看李世卿题竹","f":"七言绝句","c":["来看竹上旧题名，已有清风挹世卿。","夭矫龙蛇不堪捕，安知不是野狐精。"]},{"t":"题熊氏桐轩 其一","f":"七言绝句","c":["湖海逢君四十年，破琴残韵尚依然。","棹歌本是闽南调，传到于今更不传。"]},{"t":"题熊氏桐轩 其二","f":"七言绝句","c":["桐轩云是勿轩孙，何处江湖何处村。","古锦囊中风韵在，几时弹向白沙门。"]},{"t":"饮马氏园赠童子马国馨 其一","f":"七言绝句","c":["日转芭蕉双窦鸣，飞飞蜂蝶喜新晴。","衰翁醉卧溪园里，一曲春牛和国馨。"]},{"t":"饮马氏园赠童子马国馨 其二","f":"七言绝句","c":["白发跏趺溪树根，还从地主见诸孙。","醉中自唱渔家傲，击碎花边老瓦盆。"]},{"t":"得沈大参时旸漳州发来书答之六岁能诵予春牛之句","f":"七言绝句","c":["前后题缄两度收，春风无雁过漳州。","青灯一榻南都梦，回首于今二十秋。"]},{"t":"悼旧","f":"七言绝句","c":["里中兴没一浮云，六十年中几度闻。","只恨坟荒无祭扫，前村更有未封坟。"]},{"t":"马文祥寄五气朝元垆至 其一","f":"七言绝句","c":["隐者年来少在山，白云几片落人间。","玉台小径蓬蒿底，吾对吾垆尽日閒。"]},{"t":"马文祥寄五气朝元垆至 其二","f":"七言绝句","c":["人间荤血共欢娱，谁作朝元五气垆。","自汲山泉煮春茗，不留俗客炰江鱼。"]},{"t":"马文祥寄五气朝元垆至 其三","f":"七言绝句","c":["合是神仙太乙垆，旁通五窍似莲珠。","如何水火收功用，去问刘安下手初。"]},{"t":"马文祥寄五气朝元垆至 其四","f":"七言绝句","c":["眼前诗景浩相撩，何处丹垆火又消。","莫笑道人归未得，秋风云路几扶摇。"]},{"t":"五月二十六雨","f":"七言绝句","c":["时雨时旸歌帝力，今年今雨卜年丰。","路傍酒价知天道，何处醉乡眠此翁。"]},{"t":"六月一日不雨","f":"七言绝句","c":["窗眼阴晴晓未分，一年忧乐稍相寻。","山林自惯清凉极，且放今朝到铄金。"]},{"t":"图新书舍中植蕉数本壁间李世卿题句潮州饶鉴至读之有所兴起勉以小诗","f":"七言绝句","c":["一寸芳心卷却春，竹枝遗响落图新。","潮州客子来何暮，还对芭蕉索楚人。"]},{"t":"赠梁景行赴春闱","f":"七言绝句","c":["宗烈平生读书处，老夫题作小壶山。","壶山不解留君住，君著壶山梦里看。"]},{"t":"梦亡友袁德纯侍御 其一","f":"七言绝句","c":["再试宜兴割鸡手，置之柏府公岩岩。","如何不返龙川驾，遗恨千年在岭南。"]},{"t":"梦亡友袁德纯侍御 其二","f":"七言绝句","c":["自别君来十九秋，江门暮雨忽相投。","当时呼酒留君语，却到于今羡海鸥。"]},{"t":"周侍御文化将访白沙阻风江上连日以诗迓之 其一","f":"七言绝句","c":["长风不打画船回，更为山灵扫玉台。","走马城中具茶果，青天白日绣衣来。"]},{"t":"周侍御文化将访白沙阻风江上连日以诗迓之 其二","f":"七言绝句","c":["将晴积雨此何时，我病山中久不知。","骢马今朝在何处，江边人吏望旌旗。"]},{"t":"周侍御文化将访白沙阻风江上连日以诗迓之 其三","f":"七言绝句","c":["昔者吾闻周柱史，青牛紫气出函关。","有心来鼓南溟柁，信息朝来已到山。"]},{"t":"怀胡大参希仁 其一","f":"七言绝句","c":["鲁连谢去都无事，范蠡归来未了心。","三十馀年穷学道，而今方识古人深。"]},{"t":"怀胡大参希仁 其二","f":"七言绝句","c":["先生齿发今如何，我发秋来白又多。","若与先生论出处，江门只好听渔歌。"]},{"t":"梅下杂诗 其一","f":"七言绝句","c":["虚名每被诗家卖，素艳常遭俗眼媸。","闻向人间非得计，移根天上白龙池。"]},{"t":"梅下杂诗 其二","f":"七言绝句","c":["向暖南枝已播诗，北枝向冷尚迟迟。","肩舆欲过江门去，争得春风剪拂之。"]},{"t":"梅下杂诗 其三","f":"七言绝句","c":["梅花信是菊花传，赏到梅花又一年。","处士岂非诗俊杰，长官元是酒神仙。"]},{"t":"题瑞鹊巷","f":"七言绝句","c":["瑞鹊多年我眼中，笑烹牛鼎夜灯同。","如今柏府开诗卷，还对樽前两病翁。"]},{"t":"赠化州守郑顺解官归","f":"七言绝句","c":["湖上鸱夷久买舟，清风明月几宜休。","未知进退存亡事，只问归来郑化州。"]},{"t":"赠罗梁还程乡 其一","f":"七言绝句","c":["一峰诸子在通家，生死交情俗可嗟。","泉壤有知开口笑，江门来去看梅花。"]},{"t":"赠罗梁还程乡 其二","f":"七言绝句","c":["飞出一帆何处风，道人眠处玉台东。","春光一路相随去，朝雨渡头花欲红。"]},{"t":"赠罗梁还程乡 其三","f":"七言绝句","c":["世道如今觉我非，冲寒犹肯到柴扉。","江门春酒无多少，须劝罗生一醉归。"]},{"t":"赠罗梁还程乡 其四","f":"七言绝句","c":["翩翩双屦一长筇，意气凭凌四百峰。","肯向程乡留一载，长官真好主人翁。"]},{"t":"赠罗梁还程乡 其五","f":"七言绝句","c":["一客三旬住玉台，梅花正傍玉台开。","客心暗与梅花契，去到明年腊又来。"]},{"t":"蓬岛烟霞图赠罗定直","f":"七言绝句","c":["丹青谁弄烟霞笔，题赠湖西公子行。","携过罗浮莫开看，罗浮怕有异人争。"]},{"t":"挽林别驾汝和 其一","f":"七言绝句","c":["昔岁逢君在郁台，扬眉抚剑泰山摧。","纷纷白眼轻豪俊，只有余公解爱才。"]},{"t":"挽林别驾汝和 其二","f":"七言绝句","c":["别驾一城聊塞北，短檠诸子自江南。","平生抱负何由见，冢上铭诗仔细参。"]},{"t":"挽林别驾汝和 其三","f":"七言绝句","c":["赤冈经雨草萋萋，山北山南路欲迷。","怕到使君投辖处，黑云堆陇鹧鸪啼。"]},{"t":"挽林别驾汝和 其四","f":"七言绝句","c":["有时江畔倚秋藤，袅袅如闻击楫声。","春色眼前人不见，江花江水总含情。"]},{"t":"县取脚色","f":"七言绝句","c":["萧萧白发映春漪，脚色年来自不知。","满眼江山难具报，只将年月载公移。"]},{"t":"炒蚬忆世卿 其一","f":"七言绝句","c":["蚬酒三钟一曲歌，江边长袖舞婆娑。","如今歌舞人何处，惭愧春铛蚬子多。"]},{"t":"炒蚬忆世卿 其二","f":"七言绝句","c":["奴拾枯枝给早炊，铛中风味此奴知。","春风解忆江门否，正是江门蚬贱时。"]},{"t":"雨中漫兴 其一","f":"七言绝句","c":["种桃之岁在单阏，种竹如今又几年。","竹长桃枯人老去，钓船春雨日高眠。"]},{"t":"雨中漫兴 其二","f":"七言绝句","c":["急起翩翩白鹤双，黑云将雨欲迷江。","人间未有高栖地，何处深山著老庞。"]},{"t":"问厚郭胡父子起居于其乡人苏","f":"七言绝句","c":["居邻厚郭一鸡飞，桂树于今大几围。","老忆旧时灯火伴，青山何处望霏微。"]},{"t":"读宛陵先生历览昔贤皆泯泯寻思鲁叟自波波 其一","f":"七言绝句","c":["几上凝尘封玉轸，南风不入琵琶引。","仲由言志夫子哂，当泯泯时须泯泯。"]},{"t":"读宛陵先生历览昔贤皆泯泯寻思鲁叟自波波 其二","f":"七言绝句","c":["著渔蓑了唱渔歌，受制江山老奈何。","溪上女儿閒抹鬓，东尘西市走波波。"]},{"t":"读宛陵先生历览昔贤皆泯泯寻思鲁叟自波波 其三","f":"七言绝句","c":["泯泯波波世与身，都官两语到头真。","后生更把遗诗笑，公亦人间半醉人。"]},{"t":"读宛陵先生历览昔贤皆泯泯寻思鲁叟自波波 其四","f":"七言绝句","c":["波波泯泯不同时，静久无忧动辄疑。","圣人坐北吾遭逸，天下苍生怨望伊。"]},{"t":"次韵罗明仲先生见寄 其一","f":"七言绝句","c":["白头一枕小庐山，偶寄孤松十竹间。","朝市山林俱有事，今人忙处古人閒。"]},{"t":"次韵罗明仲先生见寄 其二","f":"七言绝句","c":["高轩频过武夷山，曾听仙歌九曲间。","坡公莫被山僧笑，只得今朝半日閒。"]},{"t":"次韵罗明仲先生见寄 其三","f":"七言绝句","c":["谁轻朱绂爱青山，回首波波泯泯间。","万籁无声天宇静，先生还似老夫閒。"]},{"t":"次韵罗明仲先生见寄 其四","f":"七言绝句","c":["三月啼莺正满山，傍花随柳水云间。","古来曾点称如许，不是天公不放閒。"]},{"t":"次韵罗明仲先生见寄 其五","f":"七言绝句","c":["武夷碧水照丹山，按部时还到彼间。","东坡也被山僧笑，只得今朝一日閒。"]},{"t":"偶阅岳季方题商山四皓图次韵 其一","f":"七言绝句","c":["道穷夫子不东周，历世纷纷讲智谋。","四老若将三杰比，真成饮水胜封侯。"]},{"t":"偶阅岳季方题商山四皓图次韵 其二","f":"七言绝句","c":["水墨谁将画此图，山人搔首看卢胡。","花水诸峰流落尽，白云犹为隐屠苏。"]},{"t":"偶阅岳季方题商山四皓图次韵 其三","f":"七言绝句","c":["虎困龙疲战两间，孤标千丈起商颜。","不将老眼看人世，肯为留侯误出山。"]},{"t":"偶阅岳季方题商山四皓图次韵 其四","f":"七言绝句","c":["定惠安刘理不难，紫芝歌已动长安。","试将脚色从头看，高祖如何敢溺冠。"]},{"t":"阅周溪图作赠刘景林归呈尊甫翁肃庵程乡令 其一","f":"七言绝句","c":["太极无阶不可跻，却从楼上望周溪。","天泉十丈无人汲，云谷老翁来杖藜。"]},{"t":"阅周溪图作赠刘景林归呈尊甫翁肃庵程乡令 其二","f":"七言绝句","c":["月色溪光荡两楹，酒醒开眼得蓬瀛。","试问老仙谁接引，舂陵云谷两先生。"]},{"t":"阅周溪图作赠刘景林归呈尊甫翁肃庵程乡令 其三","f":"七言绝句","c":["两仙何处舞霓裳，天上人间思渺茫。","脚底飞云三万丈，随君不得到程乡。"]},{"t":"阅周溪图作赠刘景林归呈尊甫翁肃庵程乡令 其四","f":"七言绝句","c":["水北原南秋更多，满川明月濯缨歌。","长官要结溪山好，去问南昌乞钓蓑。"]},{"t":"东白张先生借予藤蓑不还戏之 其一","f":"七言绝句","c":["月下溪边逐影行，还闻何处泻溪声。","扶君直到源头看，七尺芙蓉赠一茎。"]},{"t":"东白张先生借予藤蓑不还戏之 其二","f":"七言绝句","c":["咫尺溪光谷口分，谷中人语隔溪闻。","明朝更下山亭去，溪上清风可送君。"]},{"t":"丁明府置庄萧二节妇祭田邑人讼而夺之","f":"七言绝句","c":["岁月人间岂待深，等閒兴废递相寻。","秪应节妇坟头月，还照当年茂宰心。"]},{"t":"赠晋江掌教陈昌期赴任","f":"七言绝句","c":["身为五典三纲主，官作司徒典乐看。","教授苏胡元有样，莫将资级小儒官。"]},{"t":"村晚","f":"七言绝句","c":["渔笛狂吹失旧腔，采菱日暮斗歌长。","老夫独面东溟坐，月上孤琴未解囊。"]},{"t":"对菊 其一","f":"七言绝句","c":["溪绕庐冈宅绕沙，眼前酒伴眼前花。","登高此地从头记，三十六回无孟嘉。"]},{"t":"对菊 其二","f":"七言绝句","c":["因花催酒酒催诗，诗酒平生两不亏。","秋到若无诗与酒，看花元似不曾知。"]},{"t":"对菊 其三","f":"七言绝句","c":["菊径旁通水背村，秋光荡漾短篱门。","与侬别样何妆点，笑插金英满鬓根。"]},{"t":"对菊 其四","f":"七言绝句","c":["映山映水两三丛，移上山亭爱杀侬。","千古冷香吹不断，长官头上帽檐风。"]},{"t":"对菊 其五","f":"七言绝句","c":["篱前水色映花光，来坐渔竿弄晚芳。","西北酒姬解人意，问人沽酒压糟尝。"]},{"t":"代简答吴抚州次定山韵","f":"七言绝句","c":["何许苍生望不休，翩翩皂盖拥诸侯。","定山也未忘情在，更把黄州赠抚州。"]},{"t":"送子长还玉台兼怀林缉熙张廷实 其一","f":"七言绝句","c":["十里崖云古色黄，白龙高映玉台光。","山僧莫信閒饶舌，那得神仙此处藏。"]},{"t":"送子长还玉台兼怀林缉熙张廷实 其二","f":"七言绝句","c":["山肯留人月肯留，好山好水好人游。","谁还望见罗浮影，疑杀平湖五字讴。"]},{"t":"送子长还玉台兼怀林缉熙张廷实 其三","f":"七言绝句","c":["来时溟涬许同科，曾听圭峰踏月歌。","今日君骑地官马，白云招手奈君何。"]},{"t":"赠袁晖用林时嘉韵 其一","f":"七言绝句","c":["白首看云共此台，青山明月小迟回。","何时得见春风面，更到明年二月来。"]},{"t":"赠袁晖用林时嘉韵 其二","f":"七言绝句","c":["风雨相留更晚台，边炉煮蟹饯君回。","扁舟夜鼓寒潮枕，又是江门一度来。"]},{"t":"赠袁晖用林时嘉韵 其三","f":"七言绝句","c":["植竹为垣土作台，野桥分路到溪回。","江门若比瞿塘水，何处游人肯上来。"]},{"t":"赠袁晖用林时嘉韵 其四","f":"七言绝句","c":["青山依旧锁溪台，前度游人去不回。","赖是山人无诉牒，有人真本卖山来。"]},{"t":"冬至日示袁晖用前韵","f":"七言绝句","c":["面壁山人不下台，老阴消尽少阳回。","白云影尽千峰里，紫菊香腾十丈来。"]},{"t":"袁晖久在白沙候容贯不至以诗来和之","f":"七言绝句","c":["冷雨凄风寄我台，香林草屋梦空回。","山中酒伴何曾见，水上诗瓢只谩来。"]},{"t":"拟于精舍旁结小庵以处袁晖","f":"七言绝句","c":["精舍岩西拟一台，松高竹密路斜回。","草庵半属袁郎了，好带茶园一匮来。"]},{"t":"次韵赠胡曹 其一","f":"七言绝句","c":["梅坞传觞是偶同，小桃催放数花红。","人间爱见春风面，天上还看斗柄东。"]},{"t":"次韵赠胡曹 其二","f":"七言绝句","c":["今雨到门君又同，四人对饮夜垆红。","眼前莫道东溟远，我欲乘槎更向东。"]},{"t":"答蒋方伯","f":"七言绝句","c":["笔下横斜醉始多，茅笼飞出右军窝。","如何更作山阴梦，数纸换公双白鹅。"]},{"t":"得萧文明寄自作草书至 其一","f":"七言绝句","c":["草圣留情累十春，熙熙穆穆果何人。","如今到处张东海，除是谭生解识真。"]},{"t":"得萧文明寄自作草书至 其二","f":"七言绝句","c":["魏晋名家是一关，前驱黄米未知还。","却疑醉点风花句，四海于今几定山。"]},{"t":"得萧文明寄自作草书至 其三","f":"七言绝句","c":["束茅十丈扫罗浮，高榜飞云海若愁。","何处约君同洗砚，月残霜冷铁桥秋。"]},{"t":"送柑答之","f":"七言绝句","c":["遗我红柑索我歌，狂柑不饮奈柑何。","大崖山下无人寄，日尽千瓢舞破蓑。"]},{"t":"双凤石 其一","f":"七言绝句","c":["双凤岩栖岂远而，玉台西望斗光垂。","蓬莱水阔无因到，愿借山人一只骑。"]},{"t":"双凤石 其二","f":"七言绝句","c":["鬼凿寒岩万丈开，翩翩双凤忽飞来。","而今石化孤鸾在，何处人间去不回。"]},{"t":"龙山吟走笔和陈冕 其一","f":"七言绝句","c":["龙山气魄小终南，行者何年住此庵。","黄云道人飞两脚，也到白龙天际岩。"]},{"t":"龙山吟走笔和陈冕 其二","f":"七言绝句","c":["何处龙山吊古坟，忽传佳句到黄云。","始知佛是西方我，报答人间父母恩。"]},{"t":"龙山吟走笔和陈冕 其三","f":"七言绝句","c":["老柱高擎何处天，滴醯洗藓认当年。","山僧犹话飞来日，撞破龙山一道烟。"]},{"t":"龙山吟走笔和陈冕 其四","f":"七言绝句","c":["第一山人俗姓卢，脚踭涂字也碑趺。","寺旁老塔依然是，却是乾坤种种无。"]},{"t":"龙山吟走笔和陈冕 其五","f":"七言绝句","c":["浮生日月易消磨，回首龙山月一阿。","想得当时卢行者，笑人叉手缚诸魔。"]},{"t":"龙山吟走笔和陈冕 其六","f":"七言绝句","c":["风雨江门罢晚墟，隔船灯火夜呼卢。","惊回一觉龙山梦，閒对云僧讲地图。"]},{"t":"次韵苏伯诚吉士 其一","f":"七言绝句","c":["鲁水何刚爱一沂，江门新浴试新衣。","长风夜卷残云去，公抱大江明月归。"]},{"t":"次韵苏伯诚吉士 其二","f":"七言绝句","c":["我浴江门点浴沂，藤蓑自样制春衣。","寻常只著藤蓑去，细雨斜风钓不归。"]},{"t":"喜杨敷至","f":"七言绝句","c":["笠影于今落海潮，十年云水梦相撩。","一双我办云卿屦，万丈携君访铁桥。"]},{"t":"新年试笔","f":"七言绝句","c":["舍下水生春水开，竹间波弄碧洄洄。","东风日日江门道，不尽官船打鼓来。"]},{"t":"对影","f":"七言绝句","c":["风月情真诗浩荡，江湖水阔蓑飘翩。","丹青不是江门影，又画瞿昙又画仙。"]},{"t":"雨中偶得","f":"七言绝句","c":["高浪张灯何处船，客边风雨夜如年。","行人自有明朝路，莫遣阴晴不属天。"]},{"t":"题陶宪长画唐诗图","f":"七言绝句","c":["诗中之画画中诗，晴雪孤舟荡晚晖。","同在五湖烟水内，是鸱夷不是鸱夷。"]},{"t":"雨后观园","f":"七言绝句","c":["二月平原水乱流，微茫生意盎初浮。","黄茅翠甲惊人眼，是我曾无为草忧。"]},{"t":"佥宪莆阳李公自海南征黎过白沙","f":"七言绝句","c":["蛇窟纵横木短弓，霜风何处捲飞蓬。","清时欲献征黎颂，血刃犹誇甲胄雄。"]},{"t":"饮名酒","f":"七言绝句","c":["徐孺眼欺湖水碧，庞公心死鹿门深。","尊前水月千千顷，手上丝纶万万寻。"]},{"t":"观竞渡","f":"七言绝句","c":["快意深时恨亦深，干戈何处不相寻。","谁将五月龙舟水，尽洗中原虎斗心。"]},{"t":"赠茶园何视履翁","f":"七言绝句","c":["读易溪边日已斜，晚风吹落钓鱼槎。","江门水月真无限，也照先生帽顶花。"]},{"t":"题王廷直画","f":"七言绝句","c":["曲肱带酒眠花间，有月穿松到我前。","人去华山今已久，丹青犹画在山年。"]},{"t":"赠画师","f":"七言绝句","c":["高枕松根不记秋，秋来春去几时休。","山中此梦公能画，我有黄金赠一舟。"]},{"t":"次韵马广重过白沙 其一","f":"七言绝句","c":["绿榕阴里早秋天，又借渔翁半日眠。","三度槁梧携过此，如今不记是何年。"]},{"t":"次韵马广重过白沙 其二","f":"七言绝句","c":["阴晴十里不同天，独树溪边看雨眠。","何处引杯归未得，相思真有日如年。"]},{"t":"葵山小睡次韵谢天锡 其一","f":"七言绝句","c":["閒到忘閒始是閒，閒中消得几葵山。","曲肱枕断疏桐影，梦绕白龙池上还。"]},{"t":"葵山小睡次韵谢天锡 其二","f":"七言绝句","c":["无心可比白云閒，白云被风吹出山。","道人肯比桃花水，流向人间更不还。"]},{"t":"送刘程乡游玉台","f":"七言绝句","c":["春草杨敷曾醉处，秋风又拂长官衣。","黄云不是栖贤地，才到黄云便说归。"]},{"t":"葵山受诸持斋者拜戏作示之","f":"七言绝句","c":["山花山鸟共谐嬉，山石危横步不知。","笑领头陀称老宿，真成老子是婴儿。"]},{"t":"次韵张别驾古劳望白龙池","f":"七言绝句","c":["一泓何处泻天池，泡沫君看水面漦。","若对昆崙修缺典，数篇休欠白龙诗。"]},{"t":"睡起","f":"七言绝句","c":["天地蜉蝣共始终，十年痴卧一无穷。","道人试画无穷看，月在西岩日在东。"]},{"t":"候方伯东山刘先生","f":"七言绝句","c":["几处龙光发夜函，画船信息满东南。","津头小吏殷勤报，坐爇炉香月底庵。"]},{"t":"赠夏进士升","f":"七言绝句","c":["春日春风江漾沙，官船不发对山家。","山杯一举山翁醉，笑点青藜数岸花。"]},{"t":"顾别驾欲人以号称不以官口号取笑","f":"七言绝句","c":["别乘官高上元簿，夫君英气盖东南。","何须不学程明道，只要人称顾勉庵。"]},{"t":"书称顾别驾勉庵别驾诗以博笑","f":"七言绝句","c":["勉庵别驾今相随，书法兼之盖亦宜。","若道是名皆外物，因君分别却生疑。"]},{"t":"顾别驾来教民板筑复以诗见示次韵奉答","f":"七言绝句","c":["斛板亲传易简方，旁观点点复行行。","无人不拜先生赐，茅屋家家是土墙。"]},{"t":"读漳州张太守功德碑","f":"七言绝句","c":["罢守三州卧两山，漳州面目此碑间。","郡人欲识蒙庵老，也傍斯文捉一斑。"]},{"t":"次韵黄泽饮酒见寄 其一","f":"七言绝句","c":["南山北山花笑人，有酒不肯延佳宾。","请君试向西园看，又减黄鹂一半春。"]},{"t":"次韵黄泽饮酒见寄 其二","f":"七言绝句","c":["拚饮如何更问人，樽前不见李元宾。","晨朝有酒晨朝醉，莫待黄昏老却春。"]},{"t":"送扇与万松庵","f":"七言绝句","c":["山中团扇织朱藤，小把还誇入手轻。","见说高斋蚊嘴赤，夜深来扑老先生。"]},{"t":"次韵刘方伯东山见寄","f":"七言绝句","c":["一为雷雨沛西东，十郡民归岳伯功。","我有江门水千顷，春来只好浴凫翁。"]},{"t":"松隐挽诗","f":"七言绝句","c":["清静忘机乐未休，水风何处弄浮沤。","典刑今在山头月，曾照疏松枕畔秋。"]},{"t":"送薛廉宪江门 其一","f":"七言绝句","c":["江上看云独送君，庐山云亦华山云。","解衣半晌云中坐，才出云来路又分。"]},{"t":"送薛廉宪江门 其二","f":"七言绝句","c":["无端声色谢盲聋，多少人心弊弊中。","万里青天今日送，江门津口一帆风。"]},{"t":"送薛廉宪江门 其三","f":"七言绝句","c":["东山于我问渔矶，君见东山咏我诗。","莫共越人谋出处，直夫先谢外台归。"]},{"t":"谢东山惠广西酒","f":"七言绝句","c":["月下花前舞影欹，桂江酒美独斟时。","眼前莫道都忘却，也向东山有报诗。"]},{"t":"李评事题其弟世卿诗卷曰《采菊》，盖取予赠世卿古诗首句语名之，因题","f":"七言绝句","c":["是处江山有钓蓑，相逢休要问如何。","閒吹黄鹤楼前笛，即是庐山采菊歌。"]},{"t":"次韵世卿再至白沙","f":"七言绝句","c":["脚底白云无定方，风流到处贺知章。","这回却是无人见，走共渔翁酒处藏。"]},{"t":"茂卿评事惠扇答之","f":"七言绝句","c":["远望不见大厓山，君家兄弟果皆难。","不知风动今多少，也到先生掌握间。"]},{"t":"度楚云台前小桥","f":"七言绝句","c":["一木欲度溪岸高，江门丈人放步牢。","脚底太行开几片，秋风随处洒鸿毛。"]},{"t":"用前韵答张直兄弟助修楚云台","f":"七言绝句","c":["托契青莲意便高，千秋分付此台牢。","先生醉拍藜床笑，笑杀杨朱靳一毛。"]},{"t":"偕一之世卿诣楚云台偶作呈世卿 其二","f":"七言绝句","c":["半床明月半床云，光景行窝到几分。","眼角东溟秋一片，邵尧夫也不如君。"]},{"t":"代简奉寄邱明府","f":"七言绝句","c":["何处思君独举杯，江门薄暮钓船回。","风吹不尽寒蓑月，影过松间千丈来。"]},{"t":"寄廷实制中","f":"七言绝句","c":["东阁摩挲旧雨琴，青山回首又秋深。","制中面目今何似，折尽寒灯半夜心。"]},{"t":"闻黄泽发解","f":"七言绝句","c":["笑领秋风第一花，文章谁敢谤飞沙。","狂歌欲买花前醉，不怕无钱付酒家。"]},{"t":"和林子逢至白沙","f":"七言绝句","c":["一样春风几样花，乾坤分付各生涯。","如今著我沧江上，只有秋香扑钓槎。"]},{"t":"秋夜楚云台小集赠俞溥","f":"七言绝句","c":["新秋有客来信丰，风月此杯聊此同。","江山阔幅无人话，六七青袍一病翁。"]},{"t":"忆衡山呈世卿 其一","f":"七言绝句","c":["身轻何处谢炊烟，石洞松脂不记年。","尺牍已通南岳主，一丸还有白龙仙。"]},{"t":"忆衡山呈世卿 其二","f":"七言绝句","c":["今日山斋拥白绵，幽怀抱膝又经年。","湘中忆我无归路，更住衡山几日船。"]},{"t":"忆衡山呈世卿 其三","f":"七言绝句","c":["楚山西望翠重重，说著衡山便不同。","九尺仙筇倚墙角，待君来问祝融峰。"]},{"t":"忆衡山呈世卿 其四","f":"七言绝句","c":["曲肱何处枕湘流，不到名山死不休。","高咏祝融峰顶月，与君当作逍遥游。"]},{"t":"谪仙亭","f":"七言绝句","c":["迁客一亭眠海滨，当时谁号谪仙人。","花汀柳市无疆界，尽是乾坤一样春。"]},{"t":"世卿还黄公山","f":"七言绝句","c":["黄公椽子李家山，水国初归作梦看。","爱杀在家兄弟好，一壶春酒对承颜。"]},{"t":"谢金方伯历","f":"七言绝句","c":["扣门惊睡云霞晓，洗手开缄日月新。","莫笑土床空耐冷，薇垣又借一番春。"]},{"t":"闻周京春试下第遣黎公往报其家","f":"七言绝句","c":["浣壁小儿期大魁，倚门慈母梦归来。","春榜未登非恶报，开缄莫欠老黎杯。"]},{"t":"题山水小画寄姜知县","f":"七言绝句","c":["泉声山色正邦心，谁寄渔蓑渭水浔。","解点无中含有意，世间除是画工深。"]},{"t":"送蒋诚之考绩入京","f":"七言绝句","c":["尘埃局促非天游，大翼岂肯抢揄休。","王明受福在今日，野老放歌回白头。"]},{"t":"沈石田作玉台图题诗其上见寄次韵以复","f":"七言绝句","c":["到眼丹青忽自惊，玉台形我我何形。","石田虽有千金贶，老子都疑一世名。"]},{"t":"方伯金公顾白沙次韵答之","f":"七言绝句","c":["晚饭对公山阁雨，尊前又拜岁书新。","别来试把梅花数，三十六回江上春。"]},{"t":"题一峰传稿后","f":"七言绝句","c":["一峰独去江湖远，千古长留列传新。","岁岁桃花满东岸，只将荣谢记冬春。"]},{"t":"闵都宪惠历","f":"七言绝句","c":["前历将穷后历新，台端两度拜山人。","东西岭外今何地，飞尽严霜是好春。"]},{"t":"送林时嘉","f":"七言绝句","c":["南川梦里旧青湖，何处青灯一榻孤。","留取幽禽守花月，隔林还与尽情呼。"]},{"t":"次韵陈冕 其一","f":"七言绝句","c":["课试失期无了日，酒杯劝影有长春。","风流倘带龙门选，不愧当年第一人。"]},{"t":"次韵陈冕 其二","f":"七言绝句","c":["西游笠顶是青天，每爱前村酒处眠。","秋雨闭门人不见，依稀犹记下江年。"]},{"t":"冕与张别驾约游清淇","f":"七言绝句","c":["长江月色浩无津，爱月撑江别驾真。","借问此来谁主约，翩翩犹是未官人。"]},{"t":"寄题邵西涧","f":"七言绝句","c":["涧里仙蒲几节来，涧边尘迹尚封苔。","赊君涧水西头月，并与蒲香入酒杯。"]},{"t":"悼区孟章","f":"七言绝句","c":["一坐虚寒誓不归，病危何处觅刀圭。","青山若问君来去，只有当年海月知。"]},{"t":"悼马龙","f":"七言绝句","c":["道南诗卷出湖西，恨失当年马上携。","高枕何如一峰好，夕阳回首万山低。"]},{"t":"次韵顾别驾留宿碧玉楼 其一","f":"七言绝句","c":["白云沧海共悠然，病榻年深别驾眠。","领略可胜诸老意，一帘疏雨对江天。"]},{"t":"次韵顾别驾留宿碧玉楼 其二","f":"七言绝句","c":["信宿留公岂偶然，山中麋鹿避人眠。","乾坤多少登临意，一洞天深一洞天。"]},{"t":"次韵顾别驾留宿碧玉楼 其三","f":"七言绝句","c":["一弛一张皆自然，嘉宾未醉主人眠。","两鸠相对山楼午，唤得晴天作雨天。"]},{"t":"次韵顾别驾留宿碧玉楼 其四","f":"七言绝句","c":["不相同处是同然，三十年来办一眠。","何处白云堪作雨，白云封断白龙天。"]},{"t":"次韵顾别驾留宿碧玉楼 其五","f":"七言绝句","c":["勾引渔郎恐未然，桃花岩下笑人眠。","白头我亦人间睡，不是桃源洞里天。"]},{"t":"偶忆廷实迁居之作次韵示民泽 其一","f":"七言绝句","c":["君将肝肺托诸诗，我道溪山是外围。","人或有疑容未信，已如深信不妨疑。"]},{"t":"偶忆廷实迁居之作次韵示民泽 其二","f":"七言绝句","c":["小胜江山大胜诗，斩关直出两重围。","自家真乐如无地，傍柳随花也属疑。"]},{"t":"湛民泽携诸生游圭峰甚适奉寄小诗呈文定上人 其一","f":"七言绝句","c":["天风吹入紫云层，高阁逢秋快一登。","多少傍花随柳意，还馀一个玉台僧。"]},{"t":"湛民泽携诸生游圭峰甚适奉寄小诗呈文定上人 其二","f":"七言绝句","c":["秋落遥峰翠几层，不知何处啸孙登。","而今小坐黄云看，谁道方袍不是僧。"]},{"t":"湛民泽携诸生游圭峰甚适奉寄小诗呈文定上人 其三","f":"七言绝句","c":["洞崖秋藓碧层层，夺竹穿松际晓登。","想得紫芝初入手，汲泉钻火欲呼僧。"]},{"t":"湛民泽携诸生游圭峰甚适奉寄小诗呈文定上人 其四","f":"七言绝句","c":["阁天孤峙老棱层，万古荒台万古登。","君逐我来无记性，东坡言是德云僧。"]},{"t":"山斗为罗一峰作 其一","f":"七言绝句","c":["青天白日一峰尊，碧玉先生敛衽看。","四海未知山斗价，一钱相售是君难。"]},{"t":"山斗为罗一峰作 其二","f":"七言绝句","c":["曲论迷真亦异哉，乾坤何代不生才。","今谁敢避愚公号，曾作夫君北斗来。"]},{"t":"观黎?坡先生画像 其一","f":"七言绝句","c":["羊裘不钓世间名，考迹桐江更考情。","散发松根坐磐石，葫芦无酒对先生。"]},{"t":"观黎?坡先生画像 其二","f":"七言绝句","c":["无诗无影不留真，描画先生到几分。","赖有当年亲点笔，一声孤鹤在秋云。"]},{"t":"次韵周宪副梦中见寄 其一","f":"七言绝句","c":["黄花簪满碧方巾，已作人间了事人。","筹策庙堂无我梦，只将杯酒托经纶。"]},{"t":"次韵周宪副梦中见寄 其二","f":"七言绝句","c":["金带累累梦欲通，庭柯忽撼夜来风。","白头相见知何日，挑尽残灯碧玉中。"]},{"t":"代简答黄太守","f":"七言绝句","c":["韩山片石旧空闻，尺札秋风此拜君。","隐几独惭非老手，得逢青眼看斯文。"]},{"t":"次韵廷实见示 其一","f":"七言绝句","c":["击壤之前未有诗，击壤之后诗堪疑。","风花雪月人人是，又堕风花雪月围。"]},{"t":"次韵廷实见示 其二","f":"七言绝句","c":["骚坛处处自张围，我不操兵世莫疑。","翠壁青林端有句，傍花随柳却无诗。"]},{"t":"寄题张主事小西湖次韵 其一","f":"七言绝句","c":["咫尺波光对五湖，满城况是眼中无。","山禽自斗声音好，来傍竹林眠处呼。"]},{"t":"寄题张主事小西湖次韵 其二","f":"七言绝句","c":["人间风月几西湖，居士围中亦偶呼。","千树梅花一只鹤，可曾认得主人无。"]},{"t":"龙江邓翘送晚菊","f":"七言绝句","c":["氤氲何处送花舟，岁晚相看碧玉秋。","笑把一杯花亦笑，年年公酒为花留。"]},{"t":"次韵送藤枕","f":"七言绝句","c":["万事无心一片云，再来西华打眠人。","紫藤一枕谁分付，尽日酣酣红树根。"]},{"t":"悼陈冕 其二","f":"七言绝句","c":["东方欲白星渐稀，一场春梦晓钟时。","伯道有子常事耳，刘蕡登科人不知。"]},{"t":"悼陈冕 其三","f":"七言绝句","c":["风入梅花递少香，月临江阁有微霜。","去年此地客剧饮，此夜今年人悼亡。"]},{"t":"寄左行人","f":"七言绝句","c":["白狐可改先公墓，我许还公尺劵书。","汉老未还东白记，也凭门下一吹嘘。"]},{"t":"左行人寄惠倭金酒盏醉中赋答","f":"七言绝句","c":["睡乡元自醉乡分，醉兴深时睡兴深。","六十七回春又过，茅柴不管注倭金。"]},{"t":"刘景仁自雷州别二亲还永丰过白沙赠之","f":"七言绝句","c":["何处寒笳动晓风，江门别舸太匆匆。","半肩不是雷阳物，何得雷阳在梦中。"]},{"t":"与邝筠巢求兰 其一","f":"七言绝句","c":["楚畹当年不尽花，每逢秋露忆君家。","白云只隔扶溪水，不使馀香到白沙。"]},{"t":"与邝筠巢求兰 其二","f":"七言绝句","c":["坠露声残楚水昏，一杯何处酹湘魂。","山人口是游蜂嘴，不到扶溪竹下门。"]},{"t":"次韵王乐用佥宪见寄 其一","f":"七言绝句","c":["春到江门好放舟，放舟处处是天游。","能将公事此中了，何啻于今第一流。"]},{"t":"次韵王乐用佥宪见寄 其二","f":"七言绝句","c":["拍拍满胸都是春，一声未唱已通神。","新诗若道尧夫是，只问尧夫是底人。"]},{"t":"谢生得京酝以为美使致白沙开幕视之空樽而已乃因发一笑","f":"七言绝句","c":["十年美誉酒家闻，屋里茅柴且赏真。","偶对泥樽开口笑，先生不是醉乡人。"]},{"t":"题李子长画 其一","f":"七言绝句","c":["青山影里人家少，绿树阴中石径微。","偶出洞门回首望，白云何处有柴扉。"]},{"t":"题李子长画 其二","f":"七言绝句","c":["谷静山深树几丛，溪边白石可青筇。","诗中此景多相似，只恐诗家是画工。"]},{"t":"寄邓俊圭","f":"七言绝句","c":["韶州西去是衡山，楚客舟从岭左还。","欲语祝融天上事，思君迢递见君难。"]},{"t":"外祖父无子以侄孙林广为后广之曾大父以一身兼两戎籍不能办而一之为子孙世役久之业尽人亡惟有广耳有司今又以广补北京镇南卫伍自是而后林氏子孙在新会者无孑遗矣丘陇之守委之谁耶予力不能振之赋二诗赠广庶有识而怜之者 其一","f":"七言绝句","c":["茅檐家具尽随身，老妇娇儿日可亲。","有梦只寻丘陇去，不须回首问耕人。"]},{"t":"外祖父无子以侄孙林广为后广之曾大父以一身兼两戎籍不能办而一之为子孙世役久之业尽人亡惟有广耳有司今又以广补北京镇南卫伍自是而后林氏子孙在新会者无孑遗矣丘陇之守委之谁耶予力不能振之赋二诗赠广庶有识而怜之者 其二","f":"七言绝句","c":["泪尽庐冈失母家，冢傍枯树也无花。","平安莫遣无书信，一度春归一度嗟。"]},{"t":"赠刘别驾肃庵解官归永丰 其一","f":"七言绝句","c":["西来双棹不曾休，再过江边碧玉楼。","共说西湖归去晚，客心应未死金牛。"]},{"t":"赠刘别驾肃庵解官归永丰 其二","f":"七言绝句","c":["一蓑归去钓秋江，花近渔舟水亦香。","却笑此翁閒未惯，水中鸥影尚回翔。"]},{"t":"赠刘别驾肃庵解官归永丰 其三","f":"七言绝句","c":["朱门谁道不如贫，笑把狂诗写赠人。","日暮孤舟向何处，野花啼鸟故山春。"]},{"t":"得廷实报定山谢事归忆东白仲昭诸先生有作 其一","f":"七言绝句","c":["也曾收拾定山书，三月天曹谢事初。","见说定山长在病，当时不出意何如。"]},{"t":"得廷实报定山谢事归忆东白仲昭诸先生有作 其二","f":"七言绝句","c":["当时不出意何如，得丧难逃真数书。","更忆往年张学士，西山对面说河图。"]},{"t":"得廷实报定山谢事归忆东白仲昭诸先生有作 其三","f":"七言绝句","c":["西山对面说河图，远志谁将小草呼。","今古圣贤不同调，各留一影落堪舆。"]},{"t":"得廷实报定山谢事归忆东白仲昭诸先生有作 其四","f":"七言绝句","c":["各留一影落堪舆，叹息乾坤几丈夫。","脱赠藤蓑君亦爱，江门春雨忆皇都。"]},{"t":"得廷实报定山谢事归忆东白仲昭诸先生有作 其五","f":"七言绝句","c":["江门春雨忆皇都，个个先生六十馀。","必有嘉言告当宁，他年应得史臣书。"]},{"t":"题空夫卷为余行人作","f":"七言绝句","c":["三十年来学鍊空，凡身犹在有无中。","到门有客求题句，不是空夫果是公。"]},{"t":"题吴宪副累叶传芳卷","f":"七言绝句","c":["壶山八面照莆阳，吴氏传来奕叶芳。","莫向通衢高绰楔，只谈世业教诸郎。"]},{"t":"答张梧州书中议李世卿人物庄定山出处熊御史荐剡所及 其一","f":"七言绝句","c":["德行文章要两全，乾坤回首二千年。","自从孟子七篇后，直到于今有几贤。"]},{"t":"答张梧州书中议李世卿人物庄定山出处熊御史荐剡所及 其二","f":"七言绝句","c":["多病为人未足羞，遍身无病是吾忧。","眼中谁是医和手，恨杀刀圭药未投。"]},{"t":"答张梧州书中议李世卿人物庄定山出处熊御史荐剡所及 其三","f":"七言绝句","c":["欲归不归何迟迟，不是孤臣托病时。","此是定山最高处，江门渔父却能知。"]},{"t":"答张梧州书中议李世卿人物庄定山出处熊御史荐剡所及 其四","f":"七言绝句","c":["买舟南岳去寻医，七十今年病不支。","倾盖独怜熊御史，肺肝今彻野人知。"]},{"t":"邓督府欲得慈元记上石答之 其一","f":"七言绝句","c":["西涯许撰慈元记，大手文章不要多。","拙作岂堪传胜事，如今此石未须磨。"]},{"t":"邓督府欲得慈元记上石答之 其二","f":"七言绝句","c":["东山规矩赵生成，顷者一缄传到京。","有庙未应无祀典，老夫重敢告先生。"]},{"t":"偶得示诸生 其一","f":"七言绝句","c":["平地工夫到九层，不如那个主人能。","他乡消息无寻处，去问嵩山戴笠僧。"]},{"t":"偶得示诸生 其二","f":"七言绝句","c":["江云欲变三秋色，江雨初交十日秋。","凉夜一蓑摇艇去，满身明月大江流。"]},{"t":"寄李世卿","f":"七言绝句","c":["衡岳千寻云万寻，丹青难写梦中心。","人间铁笛无吹处，又向秋风寄此音。"]},{"t":"永顺彭宣慰世忠堂","f":"七言绝句","c":["宣慰之堂名世忠，灵溪水与沧溟通。","如今百丈高铜柱，又见儿孙起故封。"]},{"t":"次韵送林大参之任广西 其一","f":"七言绝句","c":["病里逢春实怕春，对花著语未惊人。","今朝纵有狂诗送，不是当年翰墨臣。"]},{"t":"次韵送林大参之任广西 其二","f":"七言绝句","c":["东西岭表非无事，经济术中怕有心。","何处老仙求救世，刀圭倒尽药囊深。"]},{"t":"次韵送林大参之任广西 其三","f":"七言绝句","c":["碧玉高楼架紫云，世间应笑此楼深。","忽闻夜半鹏风起，九万扶摇好在今。"]},{"t":"次韵送林大参之任广西 其四","f":"七言绝句","c":["夫子当时见逝川，一声浩叹不知年。","东溟更比川流阔，不共东溟一派传。"]},{"t":"和答姚主事","f":"七言绝句","c":["问我平生遗我诗，清风明月想襟期。","此心若道元无事，似我江门看水时。"]},{"t":"虽乏向用之才忝有晦藏之地引步朱陵寄怀青玉李拾遗徵之不至上疏何为张乖崖救火事严徒劳分争因而有作","f":"七言绝句","c":["海北多年一钓船，大翼遨空鱼跃川。","尽言天下知音少，白雪不知何处弦。"]},{"t":"题健斋费子充殿元号","f":"七言绝句","c":["化机浩浩不曾停，刚见群龙面目成。","谁道名斋无此意，江门月上看潮生。"]},{"t":"读罢有感","f":"七言绝句","c":["坐掩残书慨古今，白头契分向谁深。","顶门欲试回生手，争得名家一寸针。"]},{"t":"海北汪廷举新作怀沙亭修古书院冷香桥于海上遣使归图并求慕竹楼记值予在病复以是诗 其一","f":"七言绝句","c":["海边西望海云遮，何处怀沙不见沙。","壁上画图君试看，冷香今日落谁家。"]},{"t":"海北汪廷举新作怀沙亭修古书院冷香桥于海上遣使归图并求慕竹楼记值予在病复以是诗 其二","f":"七言绝句","c":["忽然土木见经纶，岭海于今一使君。","忙杀多年簿书手，可能谈笑起斯文。"]},{"t":"海北汪廷举新作怀沙亭修古书院冷香桥于海上遣使归图并求慕竹楼记值予在病复以是诗 其三","f":"七言绝句","c":["独怜不见竹坡翁，慕竹楼高月已空。","欲点山茅照西所，一瓢无计引春风。"]},{"t":"次韵送海北使阮刊","f":"七言绝句","c":["春日溪边送阮郎，桃花半落溪水香。","相逢休问来时路，大舶不知何处洋。"]},{"t":"次韵李子长寒菊 其一","f":"七言绝句","c":["四尺霜茎一寸葩，幽香何只暗浮丫。","借令岁晚无人见，不做人间九日花。"]},{"t":"次韵李子长寒菊 其二","f":"七言绝句","c":["水北一丛含数葩，梅梢寒月过篱丫。","茅茨可僦从人爱，不卖庐山半亩花。"]},{"t":"罗服周呈所作丁知县祠诗因忆旧腊寄示菊花诸诗比今为又长一格赏之以诗","f":"七言绝句","c":["醉舞黄花落鬓毛，当时诗语太矜豪。","春风再咏甘棠下，又长黄花一格高。"]},{"t":"邓秋波六十一偶失一贺小诗索笑","f":"七言绝句","c":["六十光阴一鸟过，一瓢还许醉秋波。","只今那有苕溪叟，日日尊前闻放歌。"]},{"t":"寄吴别驾献臣 其一","f":"七言绝句","c":["一官万里向西行，雪锦楼高别驾登。","若问野人何处所，朱陵洞里白云层。"]},{"t":"寄吴别驾献臣 其二","f":"七言绝句","c":["罗江许薄偶然逢，又得成都一信通。","惟有大厓李居士，洞庭何处醉春风。"]},{"t":"赠乌文瑞","f":"七言绝句","c":["回首长汀路几多，琴书又打铁桥过。","趋庭若问东南事，曾听江门一放歌。"]},{"t":"某昔过淮见平江总戎礼遇甚至都阃王侯厥配陈氏于平江总戎戚也一日过予白沙相与道旧平江今为天下兵马元帅相去万里无由幸会虽隐显殊途然于公之旧德未尝一日忘也因事赋诗托侯为达之诗曰","f":"七言绝句","c":["不见平江十七秋，春风秋月梦何悠。","病中忽见东床面，却忆淮南是旧游。"]},{"t":"和答王佥宪乐用 其一","f":"七言绝句","c":["春在城中不见春，城中春不是长春。","湛生羞作春风面，故向人间更避人。"]},{"t":"和答王佥宪乐用 其二","f":"七言绝句","c":["静处春生动处春，一家春化万家春。","公今料理春来处，便是乾坤造化人。"]},{"t":"和答王佥宪乐用 其三","f":"七言绝句","c":["春王正月众家春，望柳寻花我自春。","先生欲学程明道，莫厌寻花傍柳人。"]},{"t":"和答王佥宪乐用 其四","f":"七言绝句","c":["一物春知物物春，一年春亦万年春。","总在乾坤形气内，敢诬当世谓无人。"]},{"t":"寒江独钓","f":"七言绝句","c":["我道非空亦非小，万事舍旃终未了。","朔风吹雪满江天，我只弄我桐江钓。"]},{"t":"杜甫游春","f":"七言绝句","c":["碧柳黄鹂三月画，江湖风雨万篇诗。","花前浊酒不得醉，驴背春风空自吹。"]},{"t":"秋江晚渡","f":"七言绝句","c":["扁舟何处渡长津，水阔烟生不见身。","莫向西岩敛高楫，天涯时有暮归人。"]},{"t":"庄子观泉","f":"七言绝句","c":["珊珊泻下天花烂，仰首白龙高十万。","丹青已会识者心，谁道漆园非具眼。"]},{"t":"答石阡太守祁致和","f":"七言绝句","c":["六年饱读石阡书，习气于今想破除。","雪月风花还属我，不曾閒过邵尧夫。"]},{"t":"程节妇诗钟氏狂客之女","f":"七言绝句","c":["风俗当年坏一丝，直到于今腐烂时。","欲论千古纲常事，除是渠家节妇知。"]},{"t":"赠按治侍御王公哲","f":"七言绝句","c":["明朝骢马又何之，眼见东巡西怨时。","短歌忽被风吹去，都落人间作口碑。"]},{"t":"偶得 其一","f":"七言绝句","c":["白雪阳春谁会弹，莫愁天下赏音难。","江门夜半看明月，想到朱陵青玉坛。"]},{"t":"偶得 其二","f":"七言绝句","c":["朱陵我居青玉坛，五岳虽雄无此山。","钟期老仙还未还，高山流水我须弹。"]},{"t":"次韵送陈秉常之荆门州任 其一","f":"七言绝句","c":["不辞远道赴荆门，不避儿童笑稗官。","閒望白云飞綵水，脚头落处洞门宽。"]},{"t":"次韵送陈秉常之荆门州任 其二","f":"七言绝句","c":["紫盖垂阴宿雾收，下临云梦此何州。","黄鹤飞来一回顾，不尽荆门天际头。"]},{"t":"次韵送陈秉常之荆门州任 其三","f":"七言绝句","c":["得手未偿灯火债，设心岂异贤良科。","世间膏火煎熬外，无奈箕山处士何。"]},{"t":"题山泉为林节推","f":"七言绝句","c":["高厓百丈到沧溟，咫尺寒泉万里清。","若道眼中惟见水，老狂何意向诗倾。"]},{"t":"吴瑞卿送菊用东坡韵答之","f":"七言绝句","c":["江山摇落见霜葩，枕畔香风到细丫。","不是先生爱孤寂，人间回首已无花。"]},{"t":"题画云窝","f":"七言绝句","c":["若个丹青可此翁，云窝自有主人封。","扁舟一去无踪迹，黄鹤楼前望五峰。"]},{"t":"送人","f":"七言绝句","c":["寒水江门可半篙，渔翁江上理鱼舠。","狂歌欲送夫君别，却顾樽中无浊醪。"]},{"t":"次韵张廷实见寄 其一","f":"七言绝句","c":["两脚著地此何关，白云与尔同去还。","正当海阔天高处，不离区区跬步间。"]},{"t":"次韵张廷实见寄 其二","f":"七言绝句","c":["岁月人间古又今，斯文兴废递相寻。","崔嵬百丈皆平地，西上一筇何处深。"]},{"t":"黄别驾报世卿将来白沙","f":"七言绝句","c":["君去庐山几度春，君来不来桃花新。","花日喜逢黄别驾，共对庐山说故人。"]},{"t":"送陈仲治用旧韵","f":"七言绝句","c":["万言策进大廷对，三百人争甲榜名。","醉放渔歌此相送，白头閒动少年情。"]},{"t":"久病吟","f":"七言绝句","c":["梅花未发先扃牖，落尽梅花未整巾。","明日庐山春又至，伴眠楼上岁华新。"]},{"t":"卜室大云山","f":"七言绝句","c":["云屋久住大云山，我亦云中借半间。","未愁此地云封浅，拟带朱陵一洞还。"]},{"t":"县送春至","f":"七言绝句","c":["四角圭田酒入唇，长官送我意何勤。","莫言自有长春在，也共人间一岁春。"]},{"t":"谢伯倚得孙送姜酒至","f":"七言绝句","c":["七十一年云水中，半江老隐旧知侬。","一杯引满为君喜，伯倚今朝又作翁。"]},{"t":"漫笔","f":"七言绝句","c":["一蓑春雨江门钓，万里长风海上吹。","南岳归来无一事，小庐峰顶卧观时。"]},{"t":"喜闻刘亚卿得请还东山","f":"七言绝句","c":["平生畏就人间饭，向晚还同此鹤栖。","今夜开怀看邸报，东山归卧祝融西。"]},{"t":"观时","f":"七言绝句","c":["山云将雨过桃溪，晚脱万红何处溪。","年光也逐溪流转，已送啼莺过隔溪。"]},{"t":"寄陈仲冶金台","f":"七言绝句","c":["万里传声仲冶裘，上林春好任郎游。","而翁八十二春秋，浩笑江边碧玉楼。"]},{"t":"忆世卿","f":"七言绝句","c":["楚乡迢递庐山春，君来不来花又新。","引筇踏烂庐山月，折得梅花懒寄人。"]},{"t":"题湛民泽家庙","f":"七言绝句","c":["忽然突兀见新堂，远抱飞云万丈光。","主翁合是比闾长，此地还成礼义乡。"]},{"t":"张廷举送姜酒至","f":"七言绝句","c":["七十谬为人所尊，直从西埭到东墩。","一杯引满为君喜，廷举今年始抱孙。"]},{"t":"别廷实张主事","f":"七言绝句","c":["万丈祝融何处山，三年碧玉梦相关。","多少画工传不去，都没贤今画幅宽。"]},{"t":"寄题五峰为叶本厚父作 其一","f":"七言绝句","c":["清世谁堪住五峰，石床三尺白云封。","祝融三亩终留我，略与先生脚板同。"]},{"t":"寄题五峰为叶本厚父作 其二","f":"七言绝句","c":["扶溪作饭江门吃，五峰丈人予未识。","何当坐我五峰前，共对梅花说周易。"]},{"t":"赠张不已","f":"七言绝句","c":["不已心期不已知，明年八月战秋闱。","摩天气吐三千丈，蟾阙高扳第一枝。"]},{"t":"感事呈宋督学先生","f":"七言绝句","c":["禄位升天元有命，情怀化俗却无医。","道不易行休恕已，仁非可让更由谁。"]},{"t":"寄廷实主事","f":"七言绝句","c":["豨莶鼎内还丹意，枳壳墟边待酒心。","明朝许约西游步，一寸豨莶地万寻。"]},{"t":"和答林方伯待用春日见寄 其一","f":"七言绝句","c":["对花把酒春无几，寡欲安心老合知。","病过冬春还引望，中天月色几盈亏。"]},{"t":"和答林方伯待用春日见寄 其二","f":"七言绝句","c":["旧雨春归莺不知，雨情莺老落花时。","月露滴开莺眼膜，乾坤不了一盈亏。"]},{"t":"答陈静轩过访","f":"七言绝句","c":["公是登堂拜母人，往来不倦拜丘坟。","通家无论乡闾旧，八十头颅事事真。"]},{"t":"丁长官祠示里人","f":"七言绝句","c":["古人冷淡今人笑，此义足起人闻听。","莫遣藤萝终得意，顿令箫鼓不闻声。"]},{"t":"寄李白州都宪","f":"七言绝句","c":["东南遗爱望重临，万里滇南恨正深。","引领东山归去路，骑牛跨凤许相寻。"]},{"t":"讳日有感","f":"七言绝句","c":["十二月逢哉生魄，江山为尔生愁色。","黄昏庭树乌上啼，一声何处江楼笛。"]},{"t":"送梁宗烈赴春试 其一","f":"七言绝句","c":["梦入天门看春榜，榜中不记状元名。","世间此梦真何梦，说到梁生似有情。"]},{"t":"送梁宗烈赴春试 其二","f":"七言绝句","c":["君持素履向朱门，五色云中见至尊。","且莫轻言天下事，须将风俗究根源。"]},{"t":"枕上","f":"七言绝句","c":["仲尼不作周公梦，天下共嗟吾道衰。","总为乾坤元气薄，圣人诚处众人知。"]},{"t":"与张东白","f":"七言绝句","c":["入忙救火张忠定，正远飞章李拾遗。","何故山人都不作，山人贪睡起常迟。"]},{"t":"答陈中贵见访","f":"七言绝句","c":["积岁江门几度过，不将锦绣薄藤蓑。","雪坭鸿爪他年梦，记得渔翁此放歌。"]},{"t":"题慈元庙呈徐岭南纮","f":"七言绝句","c":["前有东山后有徐，慈元风教万年垂。","岭南他日传遗事，消得江门几句诗。"]},{"t":"江门钓濑与湛民泽收管 其一","f":"七言绝句","c":["小坐江门不记年，蒲裀当膝几回穿。","如今老去还分付，不卖区区敝帚钱。"]},{"t":"江门钓濑与湛民泽收管 其二","f":"七言绝句","c":["皇王帝伯都归尽，雪月风花未了吟。","莫道金针不传与，江门风月钓台深。"]},{"t":"江门钓濑与湛民泽收管 其三","f":"七言绝句","c":["江门渔父与谁年，惭愧公来坐榻穿。","问我江门垂钓处，囊里曾无料理钱。"]},{"t":"与湛民泽","f":"七言绝句","c":["六经尽在虚无里，万里都归感应中。","若向此边参得透，始知吾学是中庸。"]},{"t":"江门钓台","f":"七言绝句","c":["何处江边著钓台，楚云溟月尽收回。","若比桐江还胜槩，千年埋没一朝开。"]},{"t":"再用韵与湛民泽","f":"七言绝句","c":["日斜刘九放船回，层起江门水底台。","浩浩碧波山锁断，潮打厓门两扇开。"]},{"t":"民泽祖樵林居士搆堂于上游庄民泽乞题","f":"七言绝句","c":["入云堂搆昔人开，兰桂香风次第来。","黄云山高几千丈，后山前日寄声回。"]},{"t":"次韵张廷实读伊洛渊源录","f":"七言绝句","c":["往古来今几圣贤，都从心上契心传。","孟子聪明还孟子，如今且莫信人言。"]},{"t":"晓枕","f":"七言绝句","c":["圣贤都从一上来，时止时行道与偕。","若使舂陵为孟子，光风霁月更襟怀。"]},{"t":"漫笔","f":"七言绝句","c":["浩笑江门点旧诗，诗中几度见承箕。","他日携书南岳住，却话山楼浩笑时。"]},{"t":"赠杨中顺德杨明府之子","f":"七言绝句","c":["山下柴扉不浪开，杨生端为老夫来。","欲报封君无一事，只将枉句赠生回。"]},{"t":"哭景旸 其一","f":"七言绝句","c":["诘杙为楹四十秋，才醒一梦便长休。","名登鼎甲死亦枉，老抚诸孤病只愁。"]},{"t":"哭景旸 其二","f":"七言绝句","c":["影翳山楼痰吐夜，寒生老屋病交秋。","渡中短纸谁封附，远大为词解我忧。"]},{"t":"闻东山先生得请归赋此","f":"七言绝句","c":["青玉之坛横素琴，绝无人地五峰深。","碧云锁断元无路，东山东山何处寻。"]},{"t":"问马默斋病于其侄孙马大年","f":"七言绝句","c":["荔颗红时酒正多，口疮不饮奈公何。","郎君解记春牛否，还为而翁一放歌。"]},{"t":"林傽贡士入京告行于白沙赠之","f":"七言绝句","c":["乖崖救火出人间，造次来分太华山。","收拾如今到山处，明朝不见藕如船。"]},{"t":"枕上谩笔","f":"七言绝句","c":["正翕眼时元活活，到敷散处自乾乾。","谁会五行真动静，万古周流本自然。"]},{"t":"答容彦文见访","f":"七言绝句","c":["裹粮縳鸭问庐山，久病劳君每厚颜。","若问庐山近来事，重阳过后菊花残。"]},{"t":"次韵东所见寄","f":"七言绝句","c":["若水清风当颖出，山人莫道不前知。","拍手江门春信早，黄鹂飞上绿杨枝。"]},{"t":"答文定上人 其一","f":"七言绝句","c":["千金帖子忽飞驰，洗手开缄只汗颐。","前代昌黎今我是，恍然海上记留衣。"]},{"t":"答文定上人 其二","f":"七言绝句","c":["神交今在识荆前，再结前生未了缘。","果蒙道力相扶起，蚤晚东林对长官。"]},{"t":"钟太守美宣挽 其一","f":"七言绝句","c":["诗人自古例多贫，恨杀滇南金带新。","公与定山贫到老，已有陈黄一辈人。"]},{"t":"钟太守美宣挽 其二","f":"七言绝句","c":["天下功名无我关，只缘我自爱江山。","若对江山元没兴，纸钱灰冷未知閒。"]},{"t":"梦游衡山遇南极数老人来过却须先生作主与诸老对酌洪崖寿崖在旁歌诗以侑觞合坐皆喜予以诗一首识兴云","f":"七言绝句","c":["衡岳去天能几何，一株松下月明多。","南极老仙骑鹿过，一瓢斟月两崖歌。"]},{"t":"题任明府思亲楼卷用定山韵","f":"七言绝句","c":["人间何处不楼居，亦有如椽大笔书。","定山丈人都不管，一拳不屑老何如。"]},{"t":"碧玉楼昼梦扶病出游村径甚适忽安福罗进士携彭秀才来访遂书以赠之","f":"七言绝句","c":["春早春寒著莫人，黄鹂啭处暖初匀。","狂心刚被风吹动，走遍南垞到北津。"]},{"t":"泉石为顺德张氏题","f":"七言绝句","c":["江山几处堪还我，泉石边头合有人。","高著一双无极眼，闲看宇宙万回春。"]},{"t":"罗浮春寄民泽 其一","f":"七言绝句","c":["海上花开万玉林，閒门碧玉梦相寻。","不知开处花多少，折尽罗浮半夜心。"]},{"t":"罗浮春寄民泽 其二","f":"七言绝句","c":["九肋蹒跚清楚阔，九苞真与黄云深。","复有凤凰山上月，遍照罗浮玉洞春。"]},{"t":"陈海蓬诸子冠毕来见赠以诗","f":"七言绝句","c":["兄弟参差作雁行，春风碧玉喜同登。","近午天风吹雁去，翩翩吹入紫云层。"]},{"t":"周方伯至白沙","f":"七言绝句","c":["天上客来寻故人，江门月下足音闻。","便传一点江门信，逢著桃源且问津。"]},{"t":"偶得","f":"七言绝句","c":["一碧光横南岳前，灵坛秋玉青相连。","道士来携三尺木，高山流水一声弦。"]},{"t":"答送茄瓜 其一","f":"七言绝句","c":["两头肥绿压肩斜，五月江园始送瓜。","童子近前与翁语，小篮瓜底是新茄。"]},{"t":"答送茄瓜 其二","f":"七言绝句","c":["同将形色委人间，窃比高松一鹤閒。","口腹累人都未免，茄瓜篮里又诗还。"]},{"t":"新年 其一","f":"五言律诗","c":["阴雨方连日，新年损物华。","呼儿酌我酒，骑马到谁家。","黯黯寒云密，萧萧暮景斜。","人生正无赖，狼藉任桃花。"]},{"t":"新年 其二","f":"五言律诗","c":["今日胜元日，江天乍放晴。","呼瓶汲井水，煮茗待门生。","山鸟鸣将下，桃花暗复明。","所嗟人易老，况复岁华更。"]},{"t":"止客宿","f":"五言律诗","c":["为恨开年雨，江村马迹稀。","诸君能枉拜，今夕不须归。","岁酒堪投辖，人家欲掩扉。","仍闻仆夫语，畏逐骏蹄飞。"]},{"t":"暮雨客去","f":"五言律诗","c":["入郭路初暝，过桥客已劳。","仆夫亦人子，马足徇吾曹。","春色归诗妙，花枝爱酒豪。","良宵只孤负，遮莫雨萧骚。"]},{"t":"登陶公壮哉亭","f":"五言律诗","c":["新亭开石窟，远势借昆崙。","天地双眸迥，沧溟一口吞。","公来席不暖，士死庙长存。","忆昔干戈际，南征万马奔。"]},{"t":"是夕范生小酌","f":"五言律诗","c":["日月双轮转，乾坤一气旋。","是时冬始闰，细雨夜如年。","人语斜风外，天机落叶边。","凭谁给灯火，更坐读残篇。"]},{"t":"至容贯宅","f":"五言律诗","c":["在昔偶相遇，如今共白头。","敝衣寒露肘，破屋早知秋。","家业凭觚翰，厨烟管去留。","老夫如辟谷，与子入罗浮。"]},{"t":"福童灌园","f":"五言律诗","c":["绾瓶行百步，池在小桥东。","抱瓮虽无忝，寒衣却未丰。","数畦仍待绿，十趾遂流红。","口腹终同及，能无愧此童。"]},{"t":"寄胡宁寿康斋先师之甥","f":"五言律诗","c":["年华当转鸟，诗思更涂鸦。","父子皆吾友，箕裘一舅家。","人犹思岭北，书不到天涯。","莫作妻孥计，浮生日易斜。"]},{"t":"石门","f":"五言律诗","c":["白发非公事，扁舟进此门。","山云寒不雨，江路曲通村。","玩世吾何有，长途马不存。","晚来堪一醉，江月照空樽。"]},{"t":"岁晚江上追次王半山韵","f":"五言律诗","c":["山寒烟错寞，江晓日荒凉。","水际风巾动，梅边蜡屐香。","低头挈小榼，拍手笑轻航。","何但供游走，而须此日光。"]},{"t":"辱和拙作见示九日醉中再次奉答","f":"五言律诗","c":["激楚嗟难和，霓裳更可同。","更阑朱鸟下，声断碧云中。","稍歇沾花雨，还吹落帽风。","万松期不至，半偈欲腾空。"]},{"t":"九日马默斋送姑苏酒至次韵奉答","f":"五言律诗","c":["姑苏一壶酒，九日到山开。","即事焉能赋，颓龄漫爱杯。","清风生菊径，落日满溪台。","酩酊藜床上，云来覆老莱。"]},{"t":"求荔枝栽贞节堂","f":"五言律诗","c":["高榜近东溟，朝光满北楹。","欲便清昼睡，须待绿阴横。","名木从谁假，幽居赖母成。","君家多黑叶，火急送双茎。"]},{"t":"华山飞翠","f":"五言律诗","c":["何处青天外，穹然起一丘。","山名疑属我，诗景尽归楼。","九夏云长润，千岩翠欲流。","野夫好游走，衰病只罗浮。"]},{"t":"对鹤 其一","f":"五言律诗","c":["潦倒溪翁谁，人疑鸟不疑。","閒将鹤起舞，不作老无奇。","任病还亲酒，虽慵不废诗。","悠然清唳外，一枕到皇羲。"]},{"t":"对鹤 其二","f":"五言律诗","c":["吾晚病兼贫，麻衣稳称身。","朝来参两鹤，花底作三人。","日出东南雨，莺啼宇宙春。","三杯下衫袖，拂拭旧龙唇。"]},{"t":"题罗一峰赠马龙道南卷","f":"五言律诗","c":["花发春来少，愁添老去长。","高才想倾盖，昨夜语连床。","天下罗公佛，湖西马子香。","离筵一杯酒，歌苦莫相忘。"]},{"t":"饮陂头","f":"五言律诗","c":["入崦花丛密，遵陂石路高。","柴门过午饭，村老对春醪。","水白都如练，风清不作刀。","自然五字句，非谢亦非陶。"]},{"t":"吴村吊庄节妇墓 其一","f":"五言律诗","c":["豺虎何由近，风涛浩若无。","行人看墓榜，英爽在清都。","江暝云长合，原寒草不枯。","乾坤不朽事，持此报君夫。"]},{"t":"吴村吊庄节妇墓 其二","f":"五言律诗","c":["此里有此墓，千年亦不磨。","世方逐蔡琰，吾甚敬曹娥。","淫盗死殊色，良人及逝波。","江翻练裙带，激烈有遗歌。"]},{"t":"怀古次韵王半山 其一","f":"五言律诗","c":["三径五株柳，孤村独板门。","先生正高卧，众鸟莫交喧。","晋宋当时改，乾坤此老存。","手中一把菊，秋色满丘园。"]},{"t":"怀古次韵王半山 其二","f":"五言律诗","c":["相逢疏柳下，宾主两忘言。","处士乃无履，江州初到门。","低头入茅宇，散发对金樽。","长揖朱轓别，狂歌向小园。"]},{"t":"即事","f":"五言律诗","c":["龙溪一片水，何处是真源。","沈吟搔白首，伫立向黄昏。","宿鸟争投树，归牛渐满村。","少年谁氏子，歌吹隔江繁。"]},{"t":"经故居","f":"五言律诗","c":["到溪田作圃，环堵树为门。","老忆先庐在，贫知草座温。","三迁时己后，二纪恨空存。","旧事无人话，斜晖满故园。"]},{"t":"容琴月生孙以诗来贺之","f":"五言律诗","c":["春意复西良，孙枝茁更芳。","自堪为喜极，谁肯笑诗狂。","竹杖还渠撰，金杯与客长。","簪花垂白发，叠映绿衣香。"]},{"t":"赠何廷桂罢馆归","f":"五言律诗","c":["科头行百里，笠影落烟霞。","四十亲舒卷，寻常过酒家。","儿童非讲席，铅椠此归槎。","共待春芳发，来看旧种花。"]},{"t":"赠谢德明有事赴广还 其一","f":"五言律诗","c":["毕嫁吾何有，劳君作犬商。","钗裙是荆布，岁月胜资妆。","月动江涛白，山衰木叶黄。","无钱入城府，来往但轻艕。"]},{"t":"赠谢德明有事赴广还 其二","f":"五言律诗","c":["月落五仙城，天空一雁鸣。","离愁动江色，归缆解钟声。","鹭应船讴起，溪寻酒幔行。","经过不买醉，贪嗅早梅馨。"]},{"t":"有传罗一峰观化 其一","f":"五言律诗","c":["悲风何处起，散作断肠声。","乘彼白云去，湖西问死生。","四海方悬仰，一峰何可倾。","平生不下泪，今日尽沾缨。"]},{"t":"有传罗一峰观化 其二","f":"五言律诗","c":["问讯南川子，金牛有是非。","忧为妻子地，泪湿故人衣。","岁晚流言恶，天涯信使稀。","西风吹落叶，故故傍愁飞。"]},{"t":"四月 其二","f":"五言律诗","c":["生意日无涯，乾坤自不知。","受风荷柄曲，擎雨柏枝垂。","静坐观群妙，聊行觅小诗。","临阶爱新竹，抽作碧参差。"]},{"t":"风雨夜有数十客共饭达旦不寐","f":"五言律诗","c":["老觉生涯少，贫添食指繁。","雨中谁举火，夜半客推门。","室暗承尘湿，阶翻坠瓦喧。","平明不曾睡，负锸理花根。"]},{"t":"闻方伯彭公上荐剡 其二","f":"五言律诗","c":["骨相合长贫，岩栖累十春。","忽传邦伯疏，见笑北山神。","伎俩只馀子，行藏独老亲。","古来称冰鉴，谁是鉴中人。"]},{"t":"初秋夜 其一","f":"五言律诗","c":["四时相代谢，已度一日秋。","风吹露下叶，月照水边楼。","尧舜今当御，巢由竟媚幽。","山灵邀梦去，昨夜又罗浮。"]},{"t":"初秋夜 其二","f":"五言律诗","c":["自我不出户，岁星今十周。","丹砂求未遂，绿鬓去难留。","时节来将晚，山河值早秋。","西风捲雨去，星月满池流。"]},{"t":"秋梦 其一","f":"五言律诗","c":["山斗英魂在，江湖秋梦深。","还将百年泪，滴破一峰心。","絮酒熏天地，金牛恨古今。","龙泉不挂墓，吾欲殉吾琴。"]},{"t":"秋梦 其二","f":"五言律诗","c":["南海五千里，不来庄定山。","何由到江北，此会非人间。","短短目相属，悠悠心自閒。","莫言但是梦，好梦亦云悭。"]},{"t":"秋梦 其三","f":"五言律诗","c":["夜来何所梦，洗耳白龙池。","秋月下相照，天风高自吹。","永持一瓢水，细嚼万年枝。","山鬼向我拜，先生是希夷。"]},{"t":"答惠州郑别驾惠葛布","f":"五言律诗","c":["惠我一疋葛，缝衣笑不奢。","赋诗酬别驾，爱酒典邻家。","独酌秋风里，浩歌山月斜。","醉魂不觉远，卧探惠阳花。"]},{"t":"世泽 其一","f":"五言律诗","c":["世泽由来远，何年播广东。","吾庐依外海，分派自南雄。","家剩为裘业，山馀偃斧封。","千秋文物类，并与劫灰空。"]},{"t":"世泽 其二","f":"五言律诗","c":["世泽由来远，时当阨难中。","长须躬陇亩，赤脚话儿童。","骨肉危相保，干戈晚益穷。","存亡一丝发，端为谢苍穹。"]},{"t":"世泽 其三","f":"五言律诗","c":["世泽由来远，中更几替隆。","市廛怀直道，夷险信阴功。","地接华山隐，家严涑水翁。","百年还旧物，报事亦无穷。"]},{"t":"世泽 其四","f":"五言律诗","c":["世泽由来远，谁兴启迪功。","今无夭颜子，古有圣重瞳。","想像千年下，凄凉百感中。","痴儿何足了，徒只愧家风。"]},{"t":"江门墟","f":"五言律诗","c":["十步一茅椽，非村非市廛。","行人思店饭，过鸟避墟烟。","日漾红云岛，鱼翻黄叶川。","谁为问津者，莫上趁墟船。"]},{"t":"中秋期友赏月遣苍头致馈以诗迓之","f":"五言律诗","c":["笼鹅并榼酒，食有一金携。","寂寂惭吾子，依依向隔溪。","开筵面华月，出户望青藜。","若负今宵醉，何不西山栖。"]},{"t":"即席赋","f":"五言律诗","c":["夕风生微凉，池塘散月光。","呼儿看酒具，待客饮江乡。","月对歌筵徙，风拖舞袖长。","人生行乐耳，归棹夜相将。"]},{"t":"盆池栽莲至秋始花 其一","f":"五言律诗","c":["栽种已后时，花发秋将迟。","虽无女伴采，亦有山蜂知。","叶稀因地力，香远是天资。","安得三闾手，临轩赋楚词。"]},{"t":"盆池栽莲至秋始花 其二","f":"五言律诗","c":["秋露开炎萼，非时不遣誇。","盆中玉井水，溪上舂陵家。","酒醒凉风发，诗成缺月斜。","愿为若耶叟，种水作生涯。"]},{"t":"盆池栽莲至秋始花 其三","f":"五言律诗","c":["开花恨不早，花落却生愁。","白露能消物，红莲不耐秋。","频来痴小女，对此泪长流。","不识荣枯理，哀乐空相仇。"]},{"t":"盆池栽莲至秋始花 其四","f":"五言律诗","c":["此夕不能寐，此乐殊无央。","下堂步明月，月印花自长。","涓涓花间露，夜滴池水香。","但惜花月好，那知风露伤。"]},{"t":"圭峰阁","f":"五言律诗","c":["胜处不在远，杪秋何处寻。","步崖碧涧落，眠石青松阴。","地少沧溟入，山高雁鹜沈。","此时閒伫望，谁识倚阑心。"]},{"t":"庚子元旦","f":"五言律诗","c":["风日佳元日，乾坤自此春。","蒸空云气湿，照水柳芽新。","笑语聊供客，杯盘少对人。","能宽垂老意，花鸟不无神。"]},{"t":"春兴","f":"五言律诗","c":["野晴花簇白，山暖树更青。","卯酒醉欲睡，午风吹又醒。","閒拈曲江句，胜读法华经。","自在山窗下，跏趺趣己冥。"]},{"t":"晨起","f":"五言律诗","c":["群雀晓啾啾，闭门春事幽。","下床花到眼，招手鹤朝头。","永日还书卷，衰年但酒瓯。","醉来江柳下，笑引子陵钩。"]},{"t":"早起","f":"五言律诗","c":["推枕起新晴，披衣向小明。","坐忘新病减，梦少夙心清。","轧轧开邻户，鼕鼕杀县更。","跛奴呼具盥，旋起绕花行。"]},{"t":"春怀次韵陆放翁","f":"五言律诗","c":["江发溶溶绿，山开面面青。","春风何气力，吹动綵云亭。","时物归春雨，交游散晓星。","十年江海梦，谁道不曾醒。"]},{"t":"清明日往孔家山墓","f":"五言律诗","c":["旧隐经都会，佳城入孔家。","春云低拂马，山路曲萦蛇。","只隔飘香处，犹疑坏圃花。","九原无晓夜，谁管夕阳斜。"]},{"t":"春兴追次后山韵","f":"五言律诗","c":["万物各得性，天开一岁春。","风柔翻弱羽，波暖跃纤鳞。","稚柳初成趣，芳芹亦赏新。","川云将岳雨，何者不供人。"]},{"t":"雨坐","f":"五言律诗","c":["风雨坐前楹，关关双鸟鸣。","正当落花处，更作送春声。","大化归无极，斯人乐久生。","不知川上水，东逝几时停。"]},{"t":"吊陈毅卿墓","f":"五言律诗","c":["微风松下起，落日照蜻蜓。","絮酒知吾辈，春山忆毅卿。","由来都大梦，终寄一浮萍。","极目苍岑外，波涛满地生。"]},{"t":"蓬莱山祭伍光墓","f":"古风","c":["道骨成仙蜕，名山是阆丘。","云中骑款段，天上叫?辀。","人世黄梁熟，吾侪白发秋。","仍留一杯酒，何处酹金牛。"]},{"t":"树穴兰 其一","f":"五言律诗","c":["树穴疑生理，花开不记年。","灵根那藉土，芳气值薰天。","瘦比餐芝老，清于辟谷仙。","平生谁得见，云峤但苍然。"]},{"t":"树穴兰 其二","f":"五言律诗","c":["大托千寻树，真堪托此生。","春风卷骚怨，秋月照琴声。","南极峰连起，东溟水一横。","所栖非近地，持赠若为情。"]},{"t":"家兄携秉常看山予病不能往","f":"五言律诗","c":["行色千崖里，风光三月中。","山家愁酒少，造物爱诗工。","好鸟簧为韵，新花锦作丛。","吾能骑瘦马，不惜远追从。"]},{"t":"题龟山小隐贺聂清碧新居","f":"五言律诗","c":["濒海地三亩，连云厦数间。","龟山爱清碧，清碧爱龟山。","笠屐谁同往，江湖我自閒。","芙蓉小溪水，曾此照衰颜。"]},{"t":"山下别业","f":"五言律诗","c":["豕脚有濡需，乾坤胡适随。","看云因坐久，抱瓮得归迟。","家累无多口，生涯但一陂。","归哉五湖乐，吾未羡鸱夷。"]},{"t":"弄孙","f":"五言律诗","c":["画栋三重檐，曈昽晓雀穿。","一儿卧我膝，一儿坐奴肩。","风日秋逾美，诗书老未传。","二雏当慰我，心赏独悠然。"]},{"t":"戏赠都老","f":"五言律诗","c":["蔡坑黄野舟，独坐小园幽。","被命为都老，倾心向县侯。","万家春且至，一纪俗全偷。","莫倚无言化，须君九借筹。"]},{"t":"韦夫人挽","f":"五言律诗","c":["人生如朝露，死亦同蜕蝉。","有子能如诩，夫人可以仙。","春台花灼灼，秋浦月娟娟。","唤醒何州梦，归来泪迸泉。"]},{"t":"次韵何宗濂","f":"五言律诗","c":["洒落仪曹句，遗名得自求。","如何行不顾，胶向漆中投。","无事由来得，多言大抵浮。","结趺樗木下，即此是良谋。"]},{"t":"金洲石","f":"五言律诗","c":["舟楫公馀日，金洲不少留。","中流几丈石，明月五湖秋。","目击金山寺，春来白鹭洲。","西风从此去，几日到罗浮。"]},{"t":"吊李九渊","f":"五言律诗","c":["水竹更新主，风花失故权。","夜台无起日，春草自流年。","万有终归尽，千秋不必传。","倒巾此相对，只有玉台山。"]},{"t":"德庆州舟中呈伍南山","f":"五言律诗","c":["江涨麻墟雨，天低德庆城。","正当击楫处，空有结趺情。","入夏寻双井，沿流到七星。","同行邹道士，劝我学长生。"]},{"t":"德庆峡是年大水舟行不由故道","f":"五言律诗","c":["客路一千里，羊肠八百盘。","时时行树杪，往往异人间。","竹缆牵江暝，絺衣入峡寒。","倚门应尽日，谁与报平安。"]},{"t":"和尚石","f":"五言律诗","c":["舟楫行天上，斜晖卷浪花。","回流忽吞吐，鸣橹极呕哑。","便可通星汉，还堪著钓槎。","云根僧一个，疑我不袈裟。"]},{"t":"南归寄乡旧 其八","f":"五言律诗","c":["紫水团沙北，黄云古刹东。","楼吞沧海日，幔卷玉台风。","物色求钟鼎，丹砂访葛洪。","芙蓉开十丈，天际白龙宫。"]},{"t":"南归寄乡旧 其九","f":"五言律诗","c":["出处有分付，将非人所能。","君看飞鸟辈，谁不顾高腾。","放意三杯酒，留情半夜灯。","韦丹非俗吏，灵澈自高僧。"]},{"t":"南归寄乡旧 其十","f":"五言律诗","c":["沙渠风日美，弄水爱群儿。","花落莺犹语，春归蝶未知。","惜芳心未已，高咏社公祠。","四序每如此，独忧无乃痴。"]},{"t":"春兴","f":"五言律诗","c":["野鸟飞窗静，春萝补屋穿。","时时咽花气，翳翳傍林园。","山鸟日暮至，长鸣芳树烟。","唤醒陶令醉，惊觉华山眠。"]},{"t":"社西村 其一","f":"古风","c":["孤村比屋静，疏竹小塘幽。","何处还三径，如公也一丘。","晚田行布狗，春草散?辀。","汲涧谁家女，金樱插满头。"]},{"t":"社西村 其六","f":"五言律诗","c":["卜筑真何意，施为但自由。","乡音还社阮，家业且陂头。","野老眠看客，山童坐饮牛。","无生知乐否，更为问骷髅。"]},{"t":"寄马默斋 其一","f":"五言律诗","c":["山阴元有兴，画舫在须登。","闭阁思君子，开门见老僧。","骑驴山路隐，挂席海波腾。","揣度安危事，如公恐未能。"]},{"t":"月坐","f":"五言律诗","c":["林深月到迟，爱月坐成痴。","平生不戚戚，衰老尤嬉嬉。","曾西卑管仲，孟子述宣尼。","何事由求辈，区区欲有为。"]},{"t":"怀古","f":"五言律诗","c":["千里拜林宗，行藏未始同。","诸贤皆好义，夫子独时中。","东汉非刘氏，西山是阆风。","堂堂四百载，载籍为谁空。"]},{"t":"读西涯李学士撰赵员外沧江别墅记","f":"五言律诗","c":["江空秋月清，月出秋江明。","水月自相得，乾坤谁与争。","作亭赵员外，属记李先生。","何时理烟艇，载酒下南京。"]},{"t":"思亲堂","f":"五言律诗","c":["父子自天性，谁能咏蓼莪。","声容想如在，风木悲奈何。","草露滴秋陇，庭乌号夜柯。","思亲两眼泪，万古注江河。"]},{"t":"送郑巡检休官还莆","f":"五言律诗","c":["卑栖一枝足，高举入云层。","大鹏非斥鴳，斥鴳非大鹏。","卑高各有适，小大不相能。","归去木兰溪，溪鱼美可罾。"]},{"t":"怀古","f":"五言律诗","c":["皇皇复皇皇，开辟到陶唐。","迟日江山丽，春风花草香。","闾阎尽孝弟，简册无祯祥。","乾坤十二会，巳午任中央。"]},{"t":"万松草屋 其一","f":"五言律诗","c":["南山爱夫子，夫子爱南山。","孤鹤去千载，万松栖半间。","无愁催白发，有药驻朱颜。","夜半风雷作，龙来问大还。"]},{"t":"万松草屋 其二","f":"五言律诗","c":["畏途千百转，回首见诸山。","若个幽求子，结茅松树间。","希夷归华顶，黄绮在商颜。","分我青精饭，从君亦不还。"]},{"t":"寄太虚上人 其一","f":"五言律诗","c":["太虚石洞居，孤绝少人依。","远客携琴至，逢师乞食归。","一莆青草上，四面白云飞。","尽日无言说，岩花落满衣。"]},{"t":"寄太虚上人 其二","f":"五言律诗","c":["定山聊作主，石洞更无邻。","劝我无多事，如公是一人。","朝闻履虎尾，莫见批龙鳞。","莫笑杨朱小，杨朱解爱身。"]},{"t":"九日寄丁明府","f":"五言律诗","c":["病里登高意，村边社树苍。","有欢开酒禁，无力控诗狂。","老鬓花簪丑，秋襟水照凉。","如何丁明府，不肯共重阳。"]},{"t":"菊节后五日丁明府彦诚携酒来饮白沙社赋补会 其一","f":"五言律诗","c":["秋色上篱尖，天高霜气严。","对花无阿堵，笑我似陶潜。","节去杯盘在，公来吏隐兼。","江门赋补会，胜话无穷年。"]},{"t":"菊节后五日丁明府彦诚携酒来饮白沙社赋补会 其二","f":"五言律诗","c":["此日还供酒，人情盖亦难。","暂随明府醉，断送菊花残。","极浦明秋日，临流弄晚竿。","遥怜张阃幕，相忆在长安。"]},{"t":"菊节后五日丁明府彦诚携酒来饮白沙社赋补会 其三","f":"五言律诗","c":["百里非无地，东篱不借人。","因君九日爱，倾此一杯春。","菊谢人间世，官閒酒处身。","想无厌花意，投辖暮江滨。"]},{"t":"对菊","f":"五言律诗","c":["种菊不盈区，挥金每顾馀。","古今閒计较，俄顷失欢娱。","西廪高堆粟，东楼剩贮书。","路旁杨柳树，憔悴不成疏。"]},{"t":"秋晚","f":"五言律诗","c":["皎皎月又缺，鲜鲜菊可收。","汀云迷岛屿，山雨落扶留。","市有屠牛杌，江连逻吏舟。","恐无赊酒处，垂白对清秋。"]},{"t":"陈方伯耻庵挽诗 其一","f":"五言律诗","c":["乾坤如此老，没齿向斯文。","公自沧溟水，人无觳觫君。","衣冠全素履，江海挹清芬。","病起须持酒，青山欲到坟。"]},{"t":"陈方伯耻庵挽诗 其二","f":"五言律诗","c":["中年倦俯仰，上疏乞山林。","黾勉南州牧，迟回北极心。","民蒙三日雨，世病一钩金。","殄瘁声悲处，龙蛇岁值今。"]},{"t":"苦热 其一","f":"五言律诗","c":["挥汗书难继，清心雨未来。","手提弱丝去，风撼社门开。","指点封君句，摩挲土栋苔。","松根吾欲卧，返照又相催。"]},{"t":"苦热 其二","f":"五言律诗","c":["晚凉慰我渴，秋暑著人烦。","拄杖缘溪足，看湖到柳根。","哦诗衰骨痛，开卷病眸昏。","六月飞云冷，相思只断魂。"]},{"t":"晚步 其二","f":"五言律诗","c":["居常懒出户，肯到社西头。","海国诸峰暝，乾坤六月秋。","微凉生浦树，返照下西楼。","今夕蒲团上，前山更卧游。"]},{"t":"崔清献公裔孙潜示遗芳卷复许示遗像予既书纪梦之作于其还也赠之诗","f":"五言律诗","c":["积雨阶苔上，经旬断履痕。","谁为门下客，公是菊坡孙。","泽与流风远，名因避相尊。","丹青遗像在，何日照江门。"]},{"t":"太夫人晚归携诸孙候于贞节桥下 其一","f":"五言律诗","c":["寒花明隔坞，暝色欲归潮。","未愁山路黑，莫放板车摇。","耄耋供人事，儿孙候此桥。","殷勤望四崦，风急暮云飘。"]},{"t":"太夫人晚归携诸孙候于贞节桥下 其二","f":"五言律诗","c":["延缘看落日，伊轧到溪西。","丫路依冈转，垂萝拂盖低。","喜从中道见，痴效小儿啼。","报赐心何极，乾坤圣寿齐。"]},{"t":"枕上偶成","f":"五言律诗","c":["翰苑无官府，蒲团了岁年。","岩云交树白，水月印沙圆。","懒甚陶元亮，閒于魏仲先。","吾曹生分薄，于福敢求全。"]},{"t":"梅村诗次韵黎雪青","f":"五言律诗","c":["梅村梅发早，已过赏花期。","玄酒初无味，名家岂在诗。","井寒人汲少，川暝鸟飞卑。","高枕沧溟者，神仙定不疑。"]},{"t":"次韵秋兴感事录寄东所 其二","f":"五言律诗","c":["秋露落芙蓉，河山日不同。","物情诗卷里，天道雨声中。","朝出马愁坂，暮行船逆风。","欲投云谷隐，鞭鹤上层空。"]},{"t":"次韵秋兴感事录寄东所 其三","f":"五言律诗","c":["昆崙一池水，色与银河同。","问子为谁氏，从师向此中。","短檠非世业，破笠是家风。","回首唐虞际，浮云点太空。"]},{"t":"次韵秋兴感事录寄东所 其四","f":"五言律诗","c":["首阳非立异，柳下不妨同。","岁月黑甜外，乾坤软饱中。","腐儒甘粝食，烈士死长风。","今古谁能计，贤愚并一空。"]},{"t":"得林子逢书感平湖事赋此次前韵 其一","f":"五言律诗","c":["平湖千里水，浣濯与谁同。","咄咄诸魔里，冥冥一梦中。","支离深岁月，感慨极秋风。","点检希颜处，吾瓢合屡空。"]},{"t":"得林子逢书感平湖事赋此次前韵 其二","f":"五言律诗","c":["同人未为失，子不善为同。","宦况浮云外，生涯大鳖中。","孤篙撑急水，弱羽试冲风。","佛者空诸有，吾儒亦有空。"]},{"t":"与梁文冠","f":"五言律诗","c":["铅椠谁分付，闻君有义方。","纸田须乐垦，画果岂堪尝。","得雨花蹊润，随风鸟韵长。","公来诗不少，排日两三章。"]},{"t":"与客","f":"五言律诗","c":["客访贫家少，连旬幸作东。","笙簧都万籁，俎豆亦千峰。","冠带迎人懒，情怀傍酒浓。","白头君莫笑，醉袖舞春风。"]},{"t":"四月廿七日五鼓起索衣往来房户间失脚仆地伤面咎在不谨然亦衰年久病气弱无力之验也为诗以自悼 其一","f":"五言律诗","c":["胫骨衰无力，颠危刚莫支。","少年非一蹶，今日独多悲。","形模甘老丑，面目对人疑。","呼儿教涤血，不忍报慈闱。"]},{"t":"四月廿七日五鼓起索衣往来房户间失脚仆地伤面咎在不谨然亦衰年久病气弱无力之验也为诗以自悼 其二","f":"五言律诗","c":["风捲芭蕉雨，南窗夜拥衾。","人当惩乐正，我已愧曾参。","一一观天命，时时动此心。","林间子规鸟，那更助悲吟。"]},{"t":"寄张进士廷实","f":"五言律诗","c":["是诗难入俗，正坐不雕镌。","水满鱼争跃，花深蝶喜穿。","日高云卧处，春在鸟啼边。","不及陈无已，能无赏自然。"]},{"t":"偕伍伯饶杨伯顺甥舅顺德李子长游李村山","f":"五言律诗","c":["游走意何穷，天枢日夜东。","青山都老脚，破笠又春风。","径草分遥碧，岩花坠小红。","乾坤浑欲到，何处问壶公。"]},{"t":"昼睡偶成寄玉台文定上人","f":"五言律诗","c":["老脚春还短，名山梦每登。","玉台天上寺，文定意中僧。","得法休藏钵，传心信有灯。","道人北窗下，一枕一瞢腾。"]},{"t":"春日书事","f":"五言律诗","c":["开年今日雨，疏柳小塘春。","紫燕将归社，黄鹂欲唤人。","未明事南亩，选日䀻西宾。","元亮朝朝醉，江村白酒新。"]},{"t":"驿吏送酒","f":"五言律诗","c":["市榼通邮吏，三杯洗侍儿。","十分春意思，一副酒肝脾。","江岭长看画，风花不尽诗。","混然天地内，公是醉乡谁。"]},{"t":"春日醉中言怀 其一","f":"五言律诗","c":["山林亦朝市，朝市亦山林。","两鬓白于旧，三杯狂到今。","子云休儗赋，元亮已忘琴。","南山千丈石，可以明我心。"]},{"t":"春日醉中言怀 其二","f":"五言律诗","c":["古人不可见，空见古人心。","春风开我盏，流水到谁琴。","无说可传后，何才敢议今。","玉台花信少，扶杖更西林。"]},{"t":"与客谈诗","f":"五言律诗","c":["风雅馀三百，唐音仅几家。","梦犹将影说，痒莫隔靴爬。","岂是安排定，胡为孟浪誇。","超然不到处，应是用心差。"]},{"t":"雨中李世卿往还","f":"五言律诗","c":["助谈风满席，伴宿月流衾。","贫贱交游冷，江山脚迹深。","惠连何处梦，孟母此时心。","稍歇松斋雨，还来辨绣针。"]},{"t":"得林宪副待用书有怀故友张兼素","f":"五言律诗","c":["蹇蹇张兼素，从君致匪躬。","天来今日定，书展故人封。","贾傅生还恸，湘累死亦忠。","平生两行泪，万里寄秋风。"]},{"t":"寄容贯圭峰 其一","f":"五言律诗","c":["西风扶策上，病骨快新凉。","乞米分僧饭，闻香过梵堂。","闭门秋竹静，语鸟暮钟藏。","浩浩蒲团上，还同在醉乡。"]},{"t":"寄容贯圭峰 其二","f":"五言律诗","c":["落日荒台上，疏松古塔边。","身休论出世，趣欲到无弦。","峰阁初生月，渠通自到泉。","西庵凭借问，许住过残年。"]},{"t":"江村晚望寄世卿圭峰","f":"五言律诗","c":["一望一延缘，诸山进目前。","乡邦无一老，知旧半重泉。","黄叶寺旁下，白云池上连。","无穷幽涧水，日夜注东川。"]},{"t":"赠黄进士廷章还京","f":"五言律诗","c":["锦衣在亲旁，饮酒日百觞。","乐处嫌春短，离心向夜长。","青云冠盖起，黄甲姓名香。","五色持文线，千年补舜裳。"]},{"t":"白雀群飞益高","f":"五言律诗","c":["取势翩翩上，江空暮雨馀。","情轻鸠并妇，声细雁呼奴。","白雪洒孤嶂，青天开一图。","安能随蚱蜢，跳踯在泥涂。"]},{"t":"得林别驾书云去秋九月尝梦予于广信舟中兼示道路所闻","f":"五言律诗","c":["潦倒年斯迈，芳菲日自迟。","忽闻天上梦，又落世间疑。","扛鼎须凭力，无才敢与知。","涪翁亦秋思，漫寄颖滨诗。"]},{"t":"重过大忠祠","f":"五言律诗","c":["宋有中流柱，三人吾所钦。","青山遗此庙，终古厌人心。","月到厓门白，神游海雾深。","兴亡谁复道，猿鸟莫哀吟。"]},{"t":"次韵寄廷实 其一","f":"五言律诗","c":["吾犹堪起倒，吾肯谢亲宾。","在世宁须此，如公故可人。","百年应得见，一面始能亲。","独向湘江去，无忘越岭春。"]},{"t":"筑室 其一","f":"五言律诗","c":["垂老无筋力，宁非板筑人。","居常只谩过，即事始知贫。","海国秋风早，山房夜气新。","痴儿解了事，吾坐养吾真。"]},{"t":"筑室 其二","f":"五言律诗","c":["一室无多事，贫家每作难。","从来无厚积，况复不能悭。","贷粟干知友，营材入远山。","三间开土阁，聊得奉慈颜。"]},{"t":"送景易赴秋试","f":"五言律诗","c":["未达穷通理，难忘得失心。","安能谢朝市，且莫厌山林。","烹鼎须兼味，吹竽当好音。","文章无定价，敝帚不论金。"]},{"t":"图新书舍怀世卿时别白沙半月","f":"五言律诗","c":["月上斋垣白，疏梅共主宾。","偶来对月饮，不见如花人。","已觉书难至，常疑梦与亲。","海山犹在眼，何处却逢春。"]}]};